window.SUBI18N = {"en": {"nav_home": "Home", "nav_tutorial": "Tutorial", "nav_donate": "Donate", "nav_support": "Support", "foot_privacy": "Privacy Policy", "foot_terms": "Terms of Service", "doc_tutorial": "Text to Speech Tutorial — How to Make Voiceovers | Text 2 Speech", "doc_donate": "Donate — Keep Text 2 Speech Free for Everyone | Text 2 Speech", "doc_support": "Support & FAQ — Text 2 Speech Text to Speech Help", "doc_auth": "Account — Text 2 Speech", "doc_privacy": "Privacy Policy — Text 2 Speech", "doc_terms": "Terms of Service — Text 2 Speech", "tut_h1": "Tutorial", "tut_sub": "Short, practical guides for getting the most out of Text 2 Speech.", "tut_g1h": "Getting started: your first generated voice", "tut_g1p": "Start with the language selector — it decides which voices you see. Pick the language your text is written in, then try two or three voices with the Preview button; voices differ a lot in warmth and pace. Type a short paragraph first, generate it, and listen. Once the voice feels right, turn on Speed or Pitch and nudge them in small steps: +10% speed suits energetic content, a slightly lower pitch often sounds more authoritative. For anything longer than a page, generate section by section and keep the same voice and settings so the parts blend.", "tut_g2h": "How to use the break feature", "tut_g2p": "Break markers insert exact silence into generated audio. Type <b>[break:200ms]</b> for a short beat, <b>[break:1s]</b> or <b>[break:2s]</b> for longer pauses — dramatic reveals, list items and scene changes all land better with air around them. Pressing <b>Ctrl+B</b> drops a [break:500ms] marker at your cursor. Markers never appear in the audio or the subtitles; you hear only the pause. A good rule of thumb: 300–600ms between sentences that change topic, 1–2 seconds between scenes. Note that Preview mode simply skips the markers, so judge final timing on the generated file.", "tut_g3h": "A tour of the voice collection", "tut_g3p": "Text 2 Speech's catalog holds 300+ neural voices across 75 languages, and each language offers several personalities — newsreader-flat, warm and conversational, bright and youthful. Names carry their region (Aria - US, Natasha - AU), and a few voices are multilingual, handling mixed-language text gracefully. Gender filtering and name search keep the list manageable. When in doubt, generate the same paragraph with three candidate voices and pick with your ears, not the names: the right voice depends on the material, not the label.", "don_h1": "Donate", "don_sub": "Text 2 Speech is free for everyone. If it saves you time, a small contribution keeps it that way.", "don_where_h": "Where donations go", "don_where_p": "Server costs · Feature development · Service maintenance", "don_amount": "Amount", "don_paypal": "PayPal (USD)", "don_wechat": "WeChat Pay (CNY)", "don_alipay": "Alipay", "don_crypto": "Cryptocurrency", "don_crypto_sub": "USDT · ETH · BTC and more", "don_btn": "Donate Now", "don_alert": "Donation checkout opens with the public launch. Thank you for offering!", "sup_h1": "Support", "sup_sub": "Most answers live in the FAQ on the home page. Still stuck? Send us the details.", "sup_quick_h": "Quick fixes", "sup_quick_p": "• No sound on Preview: check the browser tab isn't muted and try another voice.<br>• A voice sounds wrong for your text: match the Voice Language to the text language first.<br>• Long text is slow: split it into chapters and generate in parts.<br>• A result disappeared: results live only for the current browser session — download promptly.", "sup_contact_h": "Contact", "sup_email": "Your email", "sup_topic": "Topic", "sup_o1": "Generation problem", "sup_o2": "Voice request", "sup_o3": "Bug report", "sup_o4": "Business / licensing", "sup_o5": "Other", "sup_msg": "Message", "sup_msg_ph": "Describe what happened, which voice you used, and what you expected...", "sup_send": "Send message", "sup_alert": "Thanks — the support inbox opens with the public launch. For now, the FAQ covers the common cases.", "sup_notice": "The contact form opens with the public launch. Until then, the FAQ on the home page covers the most common questions.", "auth_h1": "Welcome back", "auth_sub": "Accounts are optional — the converter works fully without one. Sign in to keep your voice favorites and history in sync (rolling out with the public launch).", "auth_email": "Email", "auth_pass": "Password", "auth_signin": "Sign in", "auth_newq": "New here?", "auth_create": "Create an account", "auth_forgot": "Forgot password?", "auth_alert_signin": "Accounts arrive with the public launch. Everything on Text 2 Speech already works signed-out.", "auth_alert_create": "Accounts arrive with the public launch. No sign-up is needed to convert text.", "auth_alert_forgot": "Password reset arrives with accounts at public launch.", "priv_h1": "Privacy Policy", "priv_updated": "Last updated: October 2026", "priv_intro": "Text 2 Speech is designed to need as little of your data as possible. You can use the converter without an account and without giving us your name or email.", "priv_s1h": "Text you convert", "priv_s1p": "Text you submit is sent to the speech engine only to produce your audio. Generated files are stored against a random session identifier and deleted automatically after a short period; they are never published, indexed or used to train models.", "priv_s2h": "Cookies and analytics", "priv_s2p": "If you accept the cookie banner, we use privacy-respecting analytics cookies to count visits and see which features are popular. Declining changes nothing about how the tool works.", "priv_s3h": "What we never do", "priv_s3p": "We do not sell personal data, we do not build advertising profiles, and we do not keep your generated audio after your session ends.", "priv_s4h": "Contact", "priv_s4p": "Questions about privacy: reach us through the <a href=\"/support.html\">Support page</a>.", "terms_h1": "Terms of Service", "terms_updated": "Last updated: October 2026", "terms_s1h": "The service", "terms_s1p": "Text 2 Speech converts text you provide into synthesized speech and lets you play and download the result, together with subtitle files. The service is provided as-is, without guarantees of uninterrupted availability.", "terms_s2h": "Your responsibilities", "terms_s2p": "Only convert text you have the right to use. Do not use generated audio to impersonate real people, deceive listeners, or break applicable laws. You are responsible for how you publish and license what you create.", "terms_s3h": "Acceptable use", "terms_s3p": "Personal, educational and creative use is welcome. Commercial use of generated audio is your responsibility to clear against the rights in your source text and any applicable voice-licensing rules in your jurisdiction.", "terms_s4h": "Changes", "terms_s4p": "Features and these terms may evolve; material changes will be noted on this page with a new date."}, "zh": {"auth_alert_create": "账户功能将随正式上线推出。转换文本无需注册。", "auth_alert_forgot": "密码重置将随账户功能在正式上线时推出。", "auth_alert_signin": "账户功能将随正式上线推出。Text 2 Speech 的所有功能在未登录时已经可以使用。", "auth_create": "创建账户", "auth_email": "电子邮箱", "auth_forgot": "忘记密码？", "auth_h1": "欢迎回来", "auth_newq": "第一次来？", "auth_pass": "密码", "auth_signin": "登录", "auth_sub": "账户是可选的——没有账户也能完整使用转换器。登录后可以同步你的语音收藏和历史记录（随正式上线推出）。", "doc_auth": "账户 — Text 2 Speech", "doc_donate": "捐赠 — 让 Text 2 Speech 对所有人免费 | Text 2 Speech", "doc_privacy": "隐私政策 — Text 2 Speech", "doc_support": "支持与常见问题 — Text 2 Speech 文字转语音帮助", "doc_terms": "服务条款 — Text 2 Speech", "doc_tutorial": "文字转语音教程 — 如何制作配音 | Text 2 Speech", "don_alert": "捐赠结账将在正式上线时开放。感谢你的好意！", "don_alipay": "Alipay", "don_amount": "金额", "don_btn": "立即捐赠", "don_crypto": "加密货币", "don_crypto_sub": "USDT · ETH · BTC 等", "don_h1": "捐赠", "don_paypal": "PayPal（美元）", "don_sub": "Text 2 Speech 对所有人免费。如果它为你节省了时间，一份小小的心意就能让它一直免费下去。", "don_wechat": "WeChat Pay（人民币）", "don_where_h": "捐赠的用途", "don_where_p": "服务器费用 · 功能开发 · 服务维护", "foot_privacy": "隐私政策", "foot_terms": "服务条款", "nav_donate": "捐赠", "nav_home": "首页", "nav_support": "支持", "nav_tutorial": "教程", "priv_h1": "隐私政策", "priv_intro": "Text 2 Speech 的设计目标是尽可能少地收集你的数据。你无需账户，也无需提供姓名或电子邮箱即可使用转换器。", "priv_s1h": "你转换的文本", "priv_s1p": "你提交的文本仅会发送给语音引擎以生成音频。生成的文件会以随机生成的会话标识符保存，并在短时间后自动删除；它们永远不会被发布、收录索引或用于训练模型。", "priv_s2h": "Cookie 与分析", "priv_s2p": "如果你接受 Cookie 提示，我们会使用注重隐私的分析 Cookie 来统计访问量并了解哪些功能受欢迎。拒绝不会改变工具的任何使用方式。", "priv_s3h": "我们绝不会做的事", "priv_s3p": "我们不出售个人数据，不建立广告画像，也不会在你的会话结束后保留你生成的音频。", "priv_s4h": "联系方式", "priv_s4p": "有隐私方面的问题：请通过<a href=\"/support.html\">支持页面</a>联系我们。", "priv_updated": "最后更新：2026 年 10 月", "sup_alert": "谢谢——支持邮箱将在正式上线时开放。目前常见问题涵盖了大多数常见情况。", "sup_contact_h": "联系我们", "sup_email": "你的电子邮箱", "sup_h1": "支持", "sup_msg": "留言", "sup_msg_ph": "请描述发生了什么、你用了哪个语音，以及你期望的结果...", "sup_notice": "联系表单将在正式上线时开放。在此之前，首页的常见问题解答涵盖了大多数常见问题。", "sup_o1": "生成问题", "sup_o2": "语音请求", "sup_o3": "错误报告", "sup_o4": "商务 / 授权", "sup_o5": "其他", "sup_quick_h": "快速解决", "sup_quick_p": "• 试听没有声音：检查浏览器标签页是否被静音，并换一个语音试试。<br>• 某个语音读你的文本听起来不对：先确认语音语言与文本语言一致。<br>• 长文本生成慢：拆成章节，分段生成。<br>• 结果消失了：结果只保留在当前浏览器会话中——请及时下载。", "sup_send": "发送留言", "sup_sub": "大多数答案都在首页的常见问题中。还是没解决？把详细情况发给我们。", "sup_topic": "主题", "terms_h1": "服务条款", "terms_s1h": "本服务", "terms_s1p": "Text 2 Speech 将你提供的文本转换为合成语音，并让你播放和下载结果以及字幕文件。本服务按「现状」提供，不保证不间断可用。", "terms_s2h": "你的责任", "terms_s2p": "请只转换你有权使用的文本。不要使用生成的音频冒充真实人物、欺骗听众或违反适用法律。你需要对你发布和授权使用自己创作内容的方式负责。", "terms_s3h": "可接受的使用", "terms_s3p": "欢迎个人、教育和创作用途。将生成的音频用于商业用途时，你有责任根据源文本的权利以及你所在司法管辖区适用的语音授权规则自行确认无误。", "terms_s4h": "变更", "terms_s4p": "功能和本条款可能会演变；重大变更会在本页注明，并更新日期。", "terms_updated": "最后更新：2026 年 10 月", "tut_g1h": "入门：生成你的第一段语音", "tut_g1p": "先从语言选择器开始——它决定了你能看到哪些语音。选择与你的文本相同的语言，然后用试听按钮试试两三个语音；不同语音在温暖度和节奏上差别很大。先输入一小段文字，生成后听一听。当语音感觉对了，再开启语速或音调，用小步幅微调：语速 +10% 适合充满活力的内容，音调稍低一些通常听起来更有权威感。如果内容超过一页，请逐段生成，并保持相同的语音和设置，这样各部分才能自然衔接。", "tut_g2h": "如何使用停顿功能", "tut_g2p": "停顿标记可以在生成的音频中插入精确的静音。输入 <b>[break:200ms]</b> 得到一个短停顿，输入 <b>[break:1s]</b> 或 <b>[break:2s]</b> 得到更长的停顿——戏剧性的揭示、列表条目和场景切换，周围留些空白效果都会更好。按 <b>Ctrl+B</b> 可以在光标处插入一个 [break:500ms] 标记。标记不会出现在音频或字幕中；你只会听到停顿。一个实用的经验法则：话题转换的句子之间留 300–600ms，场景之间留 1–2 秒。请注意，试听模式会直接跳过这些标记，因此请以生成的文件为准来判断最终的节奏。", "tut_g3h": "语音库导览", "tut_g3p": "Text 2 Speech 的目录收录了 300+ 个神经网络语音，覆盖 75 种语言，每种语言都有多种风格——平稳的新闻播报风、温暖的对话风、明亮的年轻风。名称中带有地区信息（Aria - US、Natasha - AU），还有一些语音支持多语言，能从容处理混合语言文本。性别筛选和名称搜索让列表更易于管理。拿不准时，用同一段文字生成三个候选语音，凭耳朵而不是名字来选：合适的语音取决于内容，而不是标签。", "tut_h1": "教程", "tut_sub": "简短实用的指南，帮你充分用好 Text 2 Speech。"}, "zh-TW": {"auth_alert_create": "帳戶功能將隨正式上線推出。轉換文字無需註冊。", "auth_alert_forgot": "密碼重設將隨帳戶功能於正式上線時推出。", "auth_alert_signin": "帳戶功能將隨正式上線推出。Text 2 Speech 的所有功能在未登入時已經可以使用。", "auth_create": "建立帳戶", "auth_email": "電子郵件", "auth_forgot": "忘記密碼？", "auth_h1": "歡迎回來", "auth_newq": "第一次來？", "auth_pass": "密碼", "auth_signin": "登入", "auth_sub": "帳戶是選用的——沒有帳戶也能完整使用轉換器。登入後可以同步你的語音收藏和記錄（隨正式上線推出）。", "doc_auth": "帳戶 — Text 2 Speech", "doc_donate": "捐贈 — 讓 Text 2 Speech 對所有人免費 | Text 2 Speech", "doc_privacy": "隱私政策 — Text 2 Speech", "doc_support": "支援與常見問題 — Text 2 Speech 文字轉語音說明", "doc_terms": "服務條款 — Text 2 Speech", "doc_tutorial": "文字轉語音教學 — 如何製作配音 | Text 2 Speech", "don_alert": "捐贈結帳將於正式上線時開放。感謝你的好意！", "don_alipay": "Alipay", "don_amount": "金額", "don_btn": "立即捐贈", "don_crypto": "加密貨幣", "don_crypto_sub": "USDT · ETH · BTC 等", "don_h1": "捐贈", "don_paypal": "PayPal（美元）", "don_sub": "Text 2 Speech 對所有人免費。如果它為你節省了時間，一份小小的心意就能讓它持續免費下去。", "don_wechat": "WeChat Pay（人民幣）", "don_where_h": "捐贈的用途", "don_where_p": "伺服器費用 · 功能開發 · 服務維護", "foot_privacy": "隱私政策", "foot_terms": "服務條款", "nav_donate": "捐贈", "nav_home": "首頁", "nav_support": "支援", "nav_tutorial": "教學", "priv_h1": "隱私政策", "priv_intro": "Text 2 Speech 的設計目標是盡可能少地蒐集你的資料。你無需帳戶，也無需提供姓名或電子郵件即可使用轉換器。", "priv_s1h": "你轉換的文字", "priv_s1p": "你提交的文字只會傳送給語音引擎以產生音訊。產生的檔案會以隨機產生的工作階段識別碼儲存，並在短時間後自動刪除；它們永遠不會被發表、收錄索引或用於訓練模型。", "priv_s2h": "Cookie 與分析", "priv_s2p": "如果你接受 Cookie 提示，我們會使用注重隱私的分析 Cookie 來統計造訪次數並了解哪些功能受歡迎。拒絕不會改變工具的任何使用方式。", "priv_s3h": "我們絕不會做的事", "priv_s3p": "我們不出售個人資料，不建立廣告檔案，也不會在你的工作階段結束後保留你產生的音訊。", "priv_s4h": "聯絡方式", "priv_s4p": "有隱私方面的問題：請透過<a href=\"/support.html\">支援頁面</a>聯絡我們。", "priv_updated": "最後更新：2026 年 10 月", "sup_alert": "謝謝——支援信箱將於正式上線時開放。目前常見問題涵蓋了大多數常見情況。", "sup_contact_h": "聯絡我們", "sup_email": "你的電子郵件", "sup_h1": "支援", "sup_msg": "訊息", "sup_msg_ph": "請描述發生了什麼、你用了哪個語音，以及你期望的結果...", "sup_notice": "聯絡表單將於正式上線時開放。在此之前，首頁的常見問題涵蓋了大多數常見問題。", "sup_o1": "產生問題", "sup_o2": "語音請求", "sup_o3": "錯誤回報", "sup_o4": "商務 / 授權", "sup_o5": "其他", "sup_quick_h": "快速修復", "sup_quick_p": "• 預覽沒有聲音：檢查瀏覽器分頁是否被靜音，並換一個語音試試。<br>• 某個語音讀你的文字聽起來不對：先確認語音語言與文字語言相符。<br>• 長文字產生很慢：拆成章節，分段產生。<br>• 結果不見了：結果只保留在目前的瀏覽器工作階段中——請及時下載。", "sup_send": "傳送訊息", "sup_sub": "大多數答案都在首頁的常見問題中。還是卡住了？把詳細情況傳給我們。", "sup_topic": "主題", "terms_h1": "服務條款", "terms_s1h": "本服務", "terms_s1p": "Text 2 Speech 將你提供的文字轉換為合成語音，並讓你播放和下載結果以及字幕檔案。本服務依「現狀」提供，不保證不中斷可用。", "terms_s2h": "你的責任", "terms_s2p": "請只轉換你有權使用的文字。不要使用產生的音訊冒充真實人物、欺騙聽眾或違反適用法律。你需要為你發表和授權使用自己創作內容的方式負責。", "terms_s3h": "可接受的使用", "terms_s3p": "歡迎個人、教育和創作用途。將產生的音訊用於商業用途時，你有責任根據來源文字的權利以及你所在司法管轄區適用的語音授權規則自行確認無誤。", "terms_s4h": "變更", "terms_s4p": "功能和本條款可能會演變；重大變更會在本頁註明，並更新日期。", "terms_updated": "最後更新：2026 年 10 月", "tut_g1h": "快速入門：產生你的第一段語音", "tut_g1p": "先從語言選擇器開始——它決定了你會看到哪些語音。選擇與你的文字相同的語言，然後用預覽按鈕試聽兩三個語音；不同語音在溫暖程度和節奏上差異很大。先輸入一小段文字，產生後聆聽看看。當語音感覺對了，再開啟語速或音調，用小幅度微調：語速 +10% 適合充滿活力的內容，音調稍微低一點通常聽起來更有權威感。如果內容超過一頁，請逐段產生，並維持相同的語音和設定，這樣各部分才能自然銜接。", "tut_g2h": "如何使用停頓功能", "tut_g2p": "停頓標記可以在產生的音訊中插入精確的靜音。輸入 <b>[break:200ms]</b> 取得一個短停頓，輸入 <b>[break:1s]</b> 或 <b>[break:2s]</b> 取得更長的停頓——戲劇性的揭曉、清單項目和場景轉換，周圍留些空白效果都會更好。按下 <b>Ctrl+B</b> 可以在游標處插入一個 [break:500ms] 標記。標記不會出現在音訊或字幕中；你只會聽到停頓。一個實用的經驗法則：話題轉換的句子之間留 300–600ms，場景之間留 1–2 秒。請注意，預覽模式會直接略過這些標記，因此請以產生的檔案為準來判斷最終的節奏。", "tut_g3h": "語音收藏導覽", "tut_g3p": "Text 2 Speech 的目錄收錄了 300+ 個神經網路語音，涵蓋 75 種語言，每種語言都有多種風格——平穩的新聞播報風、溫暖的對話風、明亮的年輕風。名稱中帶有地區資訊（Aria - US、Natasha - AU），還有一些語音支援多語言，能從容處理混合語言文字。性別篩選和名稱搜尋讓清單更易於管理。拿不定主意時，用同一段文字產生三個候選語音，憑耳朵而不是名字來選：合適的語音取決於素材，而不是標籤。", "tut_h1": "教學", "tut_sub": "簡短實用的指南，協助你充分運用 Text 2 Speech。"}, "ar": {"auth_alert_create": "تصل الحسابات مع الإطلاق العام. لا حاجة إلى التسجيل لتحويل النص.", "auth_alert_forgot": "تصل إعادة تعيين كلمة المرور مع الحسابات عند الإطلاق العام.", "auth_alert_signin": "تصل الحسابات مع الإطلاق العام. كل شيء في Text 2 Speech يعمل أصلًا من دون تسجيل دخول.", "auth_create": "إنشاء حساب", "auth_email": "البريد الإلكتروني", "auth_forgot": "نسيت كلمة المرور؟", "auth_h1": "مرحبًا بعودتك", "auth_newq": "جديد هنا؟", "auth_pass": "كلمة المرور", "auth_signin": "تسجيل الدخول", "auth_sub": "الحسابات اختيارية — يعمل المحوّل بكامل طاقته من دون حساب. سجّل الدخول للحفاظ على مزامنة أصواتك المفضلة وسجلّك (يُطرح مع الإطلاق العام).", "doc_auth": "الحساب — Text 2 Speech", "doc_donate": "تبرع — حافظ على بقاء Text 2 Speech مجانيًا للجميع | Text 2 Speech", "doc_privacy": "سياسة الخصوصية — Text 2 Speech", "doc_support": "الدعم والأسئلة الشائعة — مساعدة Text 2 Speech لتحويل النص إلى كلام", "doc_terms": "شروط الخدمة — Text 2 Speech", "doc_tutorial": "دليل تحويل النص إلى كلام — كيفية إنشاء التعليقات الصوتية | Text 2 Speech", "don_alert": "سيفتح الدفع للتبرعات مع الإطلاق العام. شكرًا لعرضك الكريم!", "don_alipay": "Alipay", "don_amount": "المبلغ", "don_btn": "تبرع الآن", "don_crypto": "العملات الرقمية", "don_crypto_sub": "USDT · ETH · BTC وغيرها", "don_h1": "تبرع", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech مجاني للجميع. فإذا وفّر عليك الوقت، فإن مساهمة صغيرة تساعد في بقائه كذلك.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "أين تذهب التبرعات", "don_where_p": "تكاليف الخوادم · تطوير الميزات · صيانة الخدمة", "foot_privacy": "سياسة الخصوصية", "foot_terms": "شروط الخدمة", "nav_donate": "تبرع", "nav_home": "الرئيسية", "nav_support": "الدعم", "nav_tutorial": "الدليل التعليمي", "priv_h1": "سياسة الخصوصية", "priv_intro": "صُمم Text 2 Speech ليحتاج إلى أقل قدر ممكن من بياناتك. يمكنك استخدام المحوّل من دون حساب ومن دون أن تقدّم لنا اسمك أو بريدك الإلكتروني.", "priv_s1h": "النص الذي تحوّله", "priv_s1p": "يُرسَل النص الذي ترسله إلى محرك الكلام فقط لإنتاج الصوت الخاص بك. وتُخزَّن الملفات الناتجة مقابل معرّف جلسة عشوائي وتُحذف تلقائيًا بعد فترة قصيرة؛ ولا تُنشر أبدًا أو تُفهرس أو تُستخدم لتدريب النماذج.", "priv_s2h": "ملفات تعريف الارتباط والتحليلات", "priv_s2p": "إذا قبلت شريط ملفات تعريف الارتباط، نستخدم ملفات تحليلات تحترم الخصوصية لحساب الزيارات ومعرفة الميزات الأكثر رواجًا. ولا يغيّر الرفض شيئًا في طريقة عمل الأداة.", "priv_s3h": "ما لا نفعله أبدًا", "priv_s3p": "نحن لا نبيع البيانات الشخصية، ولا نبني ملفات تعريف للإعلانات، ولا نحتفظ بصوتك الناتج بعد انتهاء جلستك.", "priv_s4h": "اتصل بنا", "priv_s4p": "أسئلة حول الخصوصية: تواصل معنا عبر <a href=\"/support.html\">صفحة الدعم</a>.", "priv_updated": "آخر تحديث: أكتوبر 2026", "sup_alert": "شكرًا — سيفتح صندوق بريد الدعم مع الإطلاق العام. وحتى ذلك الحين، تغطّي الأسئلة الشائعة الحالات الشائعة.", "sup_contact_h": "اتصل بنا", "sup_email": "بريدك الإلكتروني", "sup_h1": "الدعم", "sup_msg": "الرسالة", "sup_msg_ph": "صف ما حدث، والصوت الذي استخدمته، وما كنت تتوقعه...", "sup_notice": "يُفتح نموذج التواصل مع الإطلاق الرسمي. حتى ذلك الحين، تغطي الأسئلة الشائعة في الصفحة الرئيسية أكثر الأسئلة تكرارًا.", "sup_o1": "مشكلة في الإنشاء", "sup_o2": "طلب صوت", "sup_o3": "الإبلاغ عن خطأ", "sup_o4": "أعمال / ترخيص", "sup_o5": "أخرى", "sup_quick_h": "حلول سريعة", "sup_quick_p": "• لا صوت في المعاينة: تأكد من أن علامة تبويب المتصفح ليست مكتومة وجرّب صوتًا آخر.<br>• صوت لا يناسب نصك: طابق لغة الصوت مع لغة النص أولًا.<br>• النص الطويل بطيء: قسّمه إلى فصول وأنشئه على أجزاء.<br>• اختفت نتيجة: تُحفظ النتائج فقط خلال جلسة المتصفح الحالية — نزّلها فورًا.", "sup_send": "إرسال الرسالة", "sup_sub": "معظم الإجابات موجودة في الأسئلة الشائعة في الصفحة الرئيسية. ما زلت عالقًا؟ أرسل لنا التفاصيل.", "sup_topic": "الموضوع", "terms_h1": "شروط الخدمة", "terms_s1h": "الخدمة", "terms_s1p": "يحوّل Text 2 Speech النص الذي تقدّمه إلى كلام مُصطنع ويمكّنك من تشغيل النتيجة وتنزيلها، إلى جانب ملفات الترجمة المصاحبة. وتُقدَّم الخدمة كما هي، من دون ضمانات بتوفرها من دون انقطاع.", "terms_s2h": "مسؤولياتك", "terms_s2p": "حوّل فقط النصوص التي يحق لك استخدامها. ولا تستخدم الصوت الناتج لانتحال شخصيات أشخاص حقيقيين أو خداع المستمعين أو مخالفة القوانين المعمول بها. فأنت مسؤول عن كيفية نشر وترخيص ما تُنشئه.", "terms_s3h": "الاستخدام المقبول", "terms_s3p": "الاستخدام الشخصي والتعليمي والإبداعي مرحّب به. أما الاستخدام التجاري للصوت الناتج فمسؤوليته عليك للتأكد من توافقه مع حقوق نصك الأصلي وأي قواعد لترخيص الأصوات معمول بها في نطاق اختصاصك.", "terms_s4h": "التغييرات", "terms_s4p": "قد تتطوّر الميزات وهذه الشروط؛ وستُسجَّل أي تغييرات جوهرية في هذه الصفحة بتاريخ جديد.", "terms_updated": "آخر تحديث: أكتوبر 2026", "tut_g1h": "البداية: أول صوت تُنشئه", "tut_g1p": "ابدأ بمُنتقي اللغة — فهو الذي يحدد الأصوات التي ستراها. اختر لغة النص الذي كتبته، ثم جرّب صوتين أو ثلاثة باستخدام زر المعاينة؛ فالأصوات تختلف كثيرًا في الدفء والإيقاع. اكتب فقرة قصيرة أولًا، وأنشئها، واستمع إليها. وعندما تجد الصوت المناسب، فعِّل السرعة أو حدة الصوت وحرّكهما بخطوات صغيرة: زيادة السرعة بنسبة +10% تناسب المحتوى الحيوي، وخفض حدة الصوت قليلًا غالبًا ما يمنح إحساسًا بثقة أكبر. ولأي نص أطول من صفحة، أنشئه قسمًا تلو الآخر مع الحفاظ على الصوت والإعدادات نفسها حتى تندمج الأجزاء بتناغم.", "tut_g2h": "كيفية استخدام ميزة الوقفات", "tut_g2p": "تُدرج علامات الوقفة صمتًا دقيقًا في الصوت الناتج. اكتب <b>[break:200ms]</b> لوقفة قصيرة، أو <b>[break:1s]</b> أو <b>[break:2s]</b> لوقفات أطول — فالكشفات الدرامية وعناصر القوائم وتغيّر المشاهد تبدو أفضل عندما يحيط بها بعض الفراغ. والضغط على <b>Ctrl+B</b> يُدرج علامة [break:500ms] عند موضع المؤشر. لا تظهر هذه العلامات أبدًا في الصوت أو في الترجمة المصاحبة؛ ستسمع الصمت فقط. وقاعدة عملية جيدة: من 300–600ms بين الجمل التي يتغيّر فيها الموضوع، ومن 1–2 ثانية بين المشاهد. لاحظ أن وضع المعاينة يتخطى هذه العلامات ببساطة، لذا احكم على التوقيت النهائي من الملف المُنشأ.", "tut_g3h": "جولة في مجموعة الأصوات", "tut_g3p": "تضم مكتبة Text 2 Speech أكثر من 300+ صوت عصبي في 75 لغة، وتقدّم كل لغة عدة شخصيات صوتية — بأسلوب مذيع أخبار مسطّح، أو دافئ ومحادثتي، أو مشرق وشاب. تحمل الأسماء منطقتها (Aria - US, Natasha - AU)، وبعض الأصوات متعددة اللغات وتتعامل مع النصوص مختلطة اللغات بسلاسة. ويساعدك تصفية الجنس والبحث بالاسم في جعل القائمة قابلة للإدارة. وإذا احترت، أنشئ الفقرة نفسها بثلاثة أصوات مرشّحة واختر بأذنيك لا بالأسماء: فالصوت المناسب يعتمد على المادة نفسها، لا على الاسم.", "tut_h1": "الدليل التعليمي", "tut_sub": "أدلة قصيرة وعملية لمساعدتك على الاستفادة القصوى من Text 2 Speech."}, "cs": {"auth_alert_create": "Účty dorazí s veřejným spuštěním. K převodu textu není registrace potřeba.", "auth_alert_forgot": "Obnovení hesla dorazí spolu s účty při veřejném spuštění.", "auth_alert_signin": "Účty dorazí s veřejným spuštěním. Vše ve Text 2 Speech už teď funguje i bez přihlášení.", "auth_create": "Vytvořit účet", "auth_email": "E-mail", "auth_forgot": "Zapomněli jste heslo?", "auth_h1": "Vítejte zpět", "auth_newq": "Jste tu poprvé?", "auth_pass": "Heslo", "auth_signin": "Přihlásit se", "auth_sub": "Účty jsou volitelné — převodník plně funguje i bez nich. Přihlaste se, abyste měli synchronizované oblíbené hlasy a historii (zavádí se s veřejným spuštěním).", "doc_auth": "Účet — Text 2 Speech", "doc_donate": "Přispět — pomozte udržet Text 2 Speech zdarma pro všechny | Text 2 Speech", "doc_privacy": "Zásady ochrany soukromí — Text 2 Speech", "doc_support": "Podpora a časté dotazy — nápověda k Text 2 Speech Text to Speech", "doc_terms": "Podmínky služby — Text 2 Speech", "doc_tutorial": "Návod k převodu textu na řeč — jak vytvářet hlasové komentáře | Text 2 Speech", "don_alert": "Platby příspěvků se otevřou spolu s veřejným spuštěním. Děkujeme za vaši nabídku!", "don_alipay": "Alipay", "don_amount": "Částka", "don_btn": "Přispět", "don_crypto": "Kryptoměny", "don_crypto_sub": "USDT · ETH · BTC a další", "don_h1": "Přispět", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech je zdarma pro všechny. Pokud vám šetří čas, malý příspěvek pomůže, aby to tak zůstalo.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Na co příspěvky jdou", "don_where_p": "Náklady na servery · Vývoj funkcí · Údržba služby", "foot_privacy": "Zásady ochrany soukromí", "foot_terms": "Podmínky služby", "nav_donate": "Přispět", "nav_home": "Domů", "nav_support": "Podpora", "nav_tutorial": "Návod", "priv_h1": "Zásady ochrany soukromí", "priv_intro": "Text 2 Speech je navržen tak, aby potřeboval co nejméně vašich údajů. Převodník můžete používat bez účtu a bez toho, abyste nám sdělili své jméno nebo e-mail.", "priv_s1h": "Text, který převádíte", "priv_s1p": "Text, který odešlete, se posílá řečovému modulu pouze za účelem vytvoření vašeho zvuku. Vygenerované soubory se ukládají pod náhodným identifikátorem relace a po krátké době se automaticky mažou; nikdy se nezveřejňují, neindexují ani nepoužívají k trénování modelů.", "priv_s2h": "Soubory cookie a analytika", "priv_s2p": "Pokud přijmete banner souborů cookie, používáme analytické soubory cookie respektující soukromí k počítání návštěv a zjišťování, které funkce jsou oblíbené. Odmítnutí nic nemění na tom, jak nástroj funguje.", "priv_s3h": "Co nikdy neděláme", "priv_s3p": "Neprodáváme osobní údaje, nevytváříme reklamní profily a neuchováváme váš vygenerovaný zvuk po skončení vaší relace.", "priv_s4h": "Kontakt", "priv_s4p": "Otázky k soukromí: kontaktujte nás přes <a href=\"/support.html\">stránku podpory</a>.", "priv_updated": "Poslední aktualizace: říjen 2026", "sup_alert": "Děkujeme — schránka podpory se otevře spolu s veřejným spuštěním. Prozatím časté dotazy pokrývají běžné případy.", "sup_contact_h": "Kontakt", "sup_email": "Váš e-mail", "sup_h1": "Podpora", "sup_msg": "Zpráva", "sup_msg_ph": "Popište, co se stalo, jaký hlas jste použili a co jste očekávali...", "sup_notice": "Kontaktní formulář se otevře se spuštěním služby. Do té doby najdete odpovědi na nejčastější otázky v FAQ na hlavní stránce.", "sup_o1": "Problém s generováním", "sup_o2": "Žádost o hlas", "sup_o3": "Hlášení chyby", "sup_o4": "Obchod / licence", "sup_o5": "Jiné", "sup_quick_h": "Rychlé opravy", "sup_quick_p": "• V náhledu není slyšet zvuk: zkontrolujte, zda karta prohlížeče není ztlumená, a zkuste jiný hlas.<br>• Hlas k vašemu textu nezní dobře: nejprve slaďte jazyk hlasu s jazykem textu.<br>• Dlouhý text je pomalý: rozdělte ho na kapitoly a generujte po částech.<br>• Výsledek zmizel: výsledky existují jen pro aktuální relaci prohlížeče — stahujte je včas.", "sup_send": "Odeslat zprávu", "sup_sub": "Většinu odpovědí najdete v častých dotazech na domovské stránce. Pořád se nedaří? Pošlete nám podrobnosti.", "sup_topic": "Téma", "terms_h1": "Podmínky služby", "terms_s1h": "Služba", "terms_s1p": "Text 2 Speech převádí vámi poskytnutý text na syntetizovanou řeč a umožňuje vám výsledek přehrát a stáhnout spolu se soubory titulků. Služba je poskytována „tak, jak je“, bez záruk nepřetržité dostupnosti.", "terms_s2h": "Vaše odpovědnosti", "terms_s2p": "Převádějte pouze text, k jehož použití máte právo. Nepoužívejte vygenerovaný zvuk k vydávání se za skutečné osoby, klamání posluchačů ani porušování platných zákonů. Jste odpovědní za to, jak to, co vytvoříte, zveřejňujete a licencujete.", "terms_s3h": "Přípustné použití", "terms_s3p": "Osobní, vzdělávací a tvůrčí použití je vítáno. Komerční využití vygenerovaného zvuku je na vaší odpovědnosti — ověřte si práva ke zdrojovému textu a všechna příslušná pravidla licencování hlasů ve vaší jurisdikci.", "terms_s4h": "Změny", "terms_s4p": "Funkce i tyto podmínky se mohou vyvíjet; podstatné změny budou na této stránce zaznamenány s novým datem.", "terms_updated": "Poslední aktualizace: říjen 2026", "tut_g1h": "Začínáme: váš první vygenerovaný hlas", "tut_g1p": "Začněte výběrem jazyka — ten rozhoduje o tom, jaké hlasy uvidíte. Vyberte jazyk, ve kterém je váš text napsaný, a pak si tlačítkem Náhled vyzkoušejte dva nebo tři hlasy; hlasy se hodně liší vřelostí i tempem. Nejprve napište krátký odstavec, vygenerujte ho a poslechněte si výsledek. Když hlas sedí, zapněte rychlost nebo výšku tónu a posouvejte je po malých krocích: rychlost +10% se hodí k energickému obsahu, o něco nižší tón často zní autoritativněji. U všeho delšího než jedna stránka generujte po částech a používejte stále stejný hlas a nastavení, aby na sebe části navazovaly.", "tut_g2h": "Jak používat funkci pauz", "tut_g2p": "Značky pauz vkládají do vygenerovaného zvuku přesné ticho. Zadejte <b>[break:200ms]</b> pro krátkou pauzu, <b>[break:1s]</b> nebo <b>[break:2s]</b> pro delší pauzy — dramatická odhalení, položky seznamu i změny scén vyniknou lépe, když kolem nich bude vzduch. Stisknutím <b>Ctrl+B</b> vložíte na pozici kurzoru značku [break:500ms]. Značky se nikdy neobjeví ve zvuku ani v titulcích; uslyšíte jen pauzu. Dobré pravidlo: 300–600ms mezi větami, které mění téma, 1–2 sekundy mezi scénami. Pamatujte, že režim náhledu značky jednoduše přeskočí, takže konečné načasování posuzujte až podle vygenerovaného souboru.", "tut_g3h": "Prohlídka kolekce hlasů", "tut_g3p": "Katalog Text 2 Speech obsahuje více než 300 neuronových hlasů v 75 jazycích a každý jazyk nabízí několik osobností — strohou jako hlasatel zpráv, vřelou a konverzační, svěží a mladistvou. Názvy nesou svůj region (Aria - US, Natasha - AU) a několik hlasů je vícejazyčných a elegantně zvládá text ve smíšených jazycích. Filtrování podle pohlaví a vyhledávání podle jména udržují seznam přehledný. Když váháte, vygenerujte stejný odstavec třemi kandidátskými hlasy a vybírejte ušima, ne podle názvů: správný hlas závisí na materiálu, ne na štítku.", "tut_h1": "Návod", "tut_sub": "Krátké praktické návody, jak z Text 2 Speech vytěžit maximum."}, "da": {"auth_alert_create": "Konti kommer med den offentlige lancering. Tilmelding er ikke nødvendig for at konvertere tekst.", "auth_alert_forgot": "Nulstilling af adgangskode kommer sammen med konti ved den offentlige lancering.", "auth_alert_signin": "Konti kommer med den offentlige lancering. Alt på Text 2 Speech fungerer allerede uden login.", "auth_create": "Opret en konto", "auth_email": "E-mail", "auth_forgot": "Glemt adgangskode?", "auth_h1": "Velkommen tilbage", "auth_newq": "Ny her?", "auth_pass": "Adgangskode", "auth_signin": "Log ind", "auth_sub": "Konti er valgfrie — konverteren fungerer fuldt ud uden en konto. Log ind for at holde dine stemmefavoritter og din historik synkroniseret (rulles ud med den offentlige lancering).", "doc_auth": "Konto — Text 2 Speech", "doc_donate": "Donér — Hold Text 2 Speech gratis for alle | Text 2 Speech", "doc_privacy": "Privatlivspolitik — Text 2 Speech", "doc_support": "Support og ofte stillede spørgsmål — Hjælp til Text 2 Speech Tekst til tale", "doc_terms": "Servicevilkår — Text 2 Speech", "doc_tutorial": "Tekst til tale-vejledning — Sådan laver du speak | Text 2 Speech", "don_alert": "Donationsbetaling åbner med den offentlige lancering. Tak for tilbuddet!", "don_alipay": "Alipay", "don_amount": "Beløb", "don_btn": "Donér nu", "don_crypto": "Kryptovaluta", "don_crypto_sub": "USDT · ETH · BTC og mere", "don_h1": "Donér", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech er gratis for alle. Hvis det sparer dig tid, hjælper et lille bidrag med at holde det sådan.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Hvad donationer går til", "don_where_p": "Serveromkostninger · Funktionsudvikling · Vedligeholdelse af tjenesten", "foot_privacy": "Privatlivspolitik", "foot_terms": "Servicevilkår", "nav_donate": "Donér", "nav_home": "Hjem", "nav_support": "Support", "nav_tutorial": "Vejledning", "priv_h1": "Privatlivspolitik", "priv_intro": "Text 2 Speech er designet til at have brug for så få af dine data som muligt. Du kan bruge konverteren uden en konto og uden at give os dit navn eller din e-mail.", "priv_s1h": "Tekst, du konverterer", "priv_s1p": "Tekst, du indsender, sendes kun til talemotoren for at producere din lyd. Genererede filer gemmes under en tilfældig sessionsidentifikator og slettes automatisk efter kort tid; de udgives, indekseres eller bruges aldrig til at træne modeller.", "priv_s2h": "Cookies og analyse", "priv_s2p": "Hvis du accepterer cookiebanneret, bruger vi analysecookies, der respekterer privatlivet, til at tælle besøg og se, hvilke funktioner der er populære. At afvise ændrer intet ved, hvordan værktøjet fungerer.", "priv_s3h": "Det gør vi aldrig", "priv_s3p": "Vi sælger ikke personoplysninger, vi opbygger ikke reklameprofiler, og vi beholder ikke din genererede lyd, efter din session er slut.", "priv_s4h": "Kontakt", "priv_s4p": "Spørgsmål om privatliv: kontakt os via <a href=\"/support.html\">Supportsiden</a>.", "priv_updated": "Sidst opdateret: oktober 2026", "sup_alert": "Tak — supportindbakken åbner med den offentlige lancering. Indtil da dækker FAQ'en de almindelige tilfælde.", "sup_contact_h": "Kontakt", "sup_email": "Din e-mail", "sup_h1": "Support", "sup_msg": "Besked", "sup_msg_ph": "Beskriv, hvad der skete, hvilken stemme du brugte, og hvad du forventede...", "sup_notice": "Kontaktformularen åbner ved den offentlige lancering. Indtil da dækker FAQ på forsiden de mest almindelige spørgsmål.", "sup_o1": "Problem med generering", "sup_o2": "Ønske om stemme", "sup_o3": "Fejlrapport", "sup_o4": "Forretning / licensering", "sup_o5": "Andet", "sup_quick_h": "Hurtige løsninger", "sup_quick_p": "• Ingen lyd ved Eksempel: kontrollér, at browserfanen ikke er slået fra, og prøv en anden stemme.<br>• En stemme lyder forkert til din tekst: match først Stemmesprog med tekstsproget.<br>• Lang tekst er langsom: del den op i kapitler, og generér i dele.<br>• Et resultat forsvandt: resultater gemmes kun i den aktuelle browsersession — download med det samme.", "sup_send": "Send besked", "sup_sub": "De fleste svar findes i FAQ'en på forsiden. Sidder du stadig fast? Send os detaljerne.", "sup_topic": "Emne", "terms_h1": "Servicevilkår", "terms_s1h": "Tjenesten", "terms_s1p": "Text 2 Speech konverterer tekst, du angiver, til syntetiseret tale og lader dig afspille og downloade resultatet sammen med undertekstfiler. Tjenesten leveres, som den er, uden garantier for uafbrudt tilgængelighed.", "terms_s2h": "Dit ansvar", "terms_s2p": "Konvertér kun tekst, du har ret til at bruge. Brug ikke genereret lyd til at efterligne rigtige personer, vildlede lyttere eller overtræde gældende love. Du er ansvarlig for, hvordan du udgiver og licenserer det, du skaber.", "terms_s3h": "Acceptabel brug", "terms_s3p": "Personlig, uddannelsesmæssig og kreativ brug er velkommen. Kommerciel brug af genereret lyd er dit eget ansvar at afklare i forhold til rettighederne i din kildetekst og eventuelle gældende regler for stemmelicensering i dit land.", "terms_s4h": "Ændringer", "terms_s4p": "Funktioner og disse vilkår kan udvikle sig; væsentlige ændringer vil blive noteret på denne side med en ny dato.", "terms_updated": "Sidst opdateret: oktober 2026", "tut_g1h": "Kom godt i gang: din første genererede stemme", "tut_g1p": "Start med sprogvælgeren — den bestemmer, hvilke stemmer du ser. Vælg det sprog, din tekst er skrevet på, og prøv derefter to eller tre stemmer med knappen Eksempel; stemmer adskiller sig meget i varme og tempo. Skriv først et kort afsnit, generér det, og lyt. Når stemmen føles rigtig, kan du slå Hastighed eller Tonehøjde til og justere i små trin: +10 % hastighed passer til energisk indhold, og en lidt lavere tonehøjde lyder ofte mere autoritativ. Til alt, der er længere end en side, bør du generere afsnit for afsnit og beholde den samme stemme og de samme indstillinger, så delene glider sammen.", "tut_g2h": "Sådan bruger du pausefunktionen", "tut_g2p": "Pausemarkører indsætter præcis stilhed i den genererede lyd. Skriv <b>[break:200ms]</b> for et kort ophold, <b>[break:1s]</b> eller <b>[break:2s]</b> for længere pauser — dramatiske afsløringer, listepunkter og sceneskift lander alle bedre med luft omkring sig. Tryk på <b>Ctrl+B</b> for at indsætte en [break:500ms]-markør ved markøren. Markører vises aldrig i lyden eller underteksterne; du hører kun pausen. En god tommelfingerregel: 300–600 ms mellem sætninger, der skifter emne, og 1–2 sekunder mellem scener. Bemærk, at Eksempel-tilstand blot springer markørerne over, så bedøm den endelige timing på den genererede fil.", "tut_g3h": "En rundtur i stemmesamlingen", "tut_g3p": "Text 2 Speechs katalog rummer 300+ neurale stemmer på 75 sprog, og hvert sprog byder på flere personligheder — flad nyhedsoplæser, varm og samtalende, lys og ungdommelig. Navne angiver deres region (Aria - US, Natasha - AU), og nogle få stemmer er flersprogede og håndterer tekst på blandede sprog uden problemer. Kønsfiltrering og navnesøgning holder listen overskuelig. Er du i tvivl, så generér det samme afsnit med tre kandidatstemmer og vælg med ørerne, ikke navnene: den rigtige stemme afhænger af materialet, ikke af etiketten.", "tut_h1": "Vejledning", "tut_sub": "Korte, praktiske guider til at få mest muligt ud af Text 2 Speech."}, "de": {"auth_alert_create": "Konten kommen mit der öffentlichen Veröffentlichung. Für die Textkonvertierung ist keine Registrierung nötig.", "auth_alert_forgot": "Die Passwortzurücksetzung kommt zusammen mit den Konten zur öffentlichen Veröffentlichung.", "auth_alert_signin": "Konten kommen mit der öffentlichen Veröffentlichung. Alles auf Text 2 Speech funktioniert bereits ohne Anmeldung.", "auth_create": "Konto erstellen", "auth_email": "E-Mail", "auth_forgot": "Passwort vergessen?", "auth_h1": "Willkommen zurück", "auth_newq": "Neu hier?", "auth_pass": "Passwort", "auth_signin": "Anmelden", "auth_sub": "Konten sind optional — der Konverter funktioniert vollständig ohne eines. Melden Sie sich an, um Ihre Stimmfavoriten und Ihren Verlauf zu synchronisieren (verfügbar ab der öffentlichen Veröffentlichung).", "doc_auth": "Konto — Text 2 Speech", "doc_donate": "Spenden — Halten Sie Text 2 Speech für alle kostenlos | Text 2 Speech", "doc_privacy": "Datenschutzerklärung — Text 2 Speech", "doc_support": "Support & FAQ — Hilfe zu Text 2 Speech Text to Speech", "doc_terms": "Nutzungsbedingungen — Text 2 Speech", "doc_tutorial": "Text-to-Speech-Anleitung — So erstellen Sie Voiceovers | Text 2 Speech", "don_alert": "Die Spendenabwicklung startet mit der öffentlichen Veröffentlichung. Vielen Dank für Ihr Angebot!", "don_alipay": "Alipay", "don_amount": "Betrag", "don_btn": "Jetzt spenden", "don_crypto": "Kryptowährung", "don_crypto_sub": "USDT · ETH · BTC und mehr", "don_h1": "Spenden", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech ist für alle kostenlos. Wenn es Ihnen Zeit spart, hilft ein kleiner Beitrag, dass das so bleibt.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Wofür Spenden verwendet werden", "don_where_p": "Serverkosten · Funktionsentwicklung · Wartung des Dienstes", "foot_privacy": "Datenschutzerklärung", "foot_terms": "Nutzungsbedingungen", "nav_donate": "Spenden", "nav_home": "Startseite", "nav_support": "Support", "nav_tutorial": "Anleitung", "priv_h1": "Datenschutzerklärung", "priv_intro": "Text 2 Speech ist so konzipiert, dass es möglichst wenige Ihrer Daten benötigt. Sie können den Konverter ohne Konto nutzen und ohne uns Ihren Namen oder Ihre E-Mail zu geben.", "priv_s1h": "Text, den Sie konvertieren", "priv_s1p": "Der von Ihnen übermittelte Text wird nur an die Sprach-Engine gesendet, um Ihr Audio zu erzeugen. Generierte Dateien werden unter einer zufälligen Sitzungskennung gespeichert und nach kurzer Zeit automatisch gelöscht; sie werden niemals veröffentlicht, indexiert oder zum Trainieren von Modellen verwendet.", "priv_s2h": "Cookies und Analysen", "priv_s2p": "Wenn Sie das Cookie-Banner akzeptieren, verwenden wir datenschutzfreundliche Analyse-Cookies, um Besuche zu zählen und zu sehen, welche Funktionen beliebt sind. Eine Ablehnung ändert nichts daran, wie das Tool funktioniert.", "priv_s3h": "Was wir niemals tun", "priv_s3p": "Wir verkaufen keine personenbezogenen Daten, wir erstellen keine Werbeprofile und wir behalten Ihr generiertes Audio nicht, nachdem Ihre Sitzung endet.", "priv_s4h": "Kontakt", "priv_s4p": "Fragen zum Datenschutz: Erreichen Sie uns über die <a href=\"/support.html\">Support-Seite</a>.", "priv_updated": "Zuletzt aktualisiert: Oktober 2026", "sup_alert": "Danke — das Support-Postfach öffnet mit der öffentlichen Veröffentlichung. Bis dahin decken die FAQ die häufigsten Fälle ab.", "sup_contact_h": "Kontakt", "sup_email": "Ihre E-Mail", "sup_h1": "Support", "sup_msg": "Nachricht", "sup_msg_ph": "Beschreiben Sie, was passiert ist, welche Stimme Sie verwendet haben und was Sie erwartet hatten...", "sup_notice": "Das Kontaktformular öffnet mit dem offiziellen Start. Bis dahin beantworten die FAQ auf der Startseite die häufigsten Fragen.", "sup_o1": "Problem bei der Generierung", "sup_o2": "Stimmenwunsch", "sup_o3": "Fehlerbericht", "sup_o4": "Geschäftliches / Lizenzierung", "sup_o5": "Sonstiges", "sup_quick_h": "Schnelle Lösungen", "sup_quick_p": "• Kein Ton in der Vorschau: Prüfen Sie, ob der Browser-Tab nicht stummgeschaltet ist, und versuchen Sie eine andere Stimme.<br>• Eine Stimme klingt für Ihren Text falsch: Stellen Sie zuerst die Stimmensprache auf die Sprache des Textes ein.<br>• Langer Text ist langsam: Teilen Sie ihn in Kapitel auf und generieren Sie in Teilen.<br>• Ein Ergebnis ist verschwunden: Ergebnisse existieren nur für die aktuelle Browser-Sitzung — laden Sie sie zeitnah herunter.", "sup_send": "Nachricht senden", "sup_sub": "Die meisten Antworten finden Sie in den FAQ auf der Startseite. Kommen Sie trotzdem nicht weiter? Senden Sie uns die Details.", "sup_topic": "Thema", "terms_h1": "Nutzungsbedingungen", "terms_s1h": "Der Dienst", "terms_s1p": "Text 2 Speech wandelt den von Ihnen bereitgestellten Text in synthetische Sprache um und lässt Sie das Ergebnis zusammen mit Untertiteldateien abspielen und herunterladen. Der Dienst wird ohne Gewähr bereitgestellt, ohne Garantie einer ununterbrochenen Verfügbarkeit.", "terms_s2h": "Ihre Verantwortlichkeiten", "terms_s2p": "Konvertieren Sie nur Text, zu dessen Verwendung Sie berechtigt sind. Verwenden Sie generiertes Audio nicht, um echte Personen zu imitieren, Zuhörer zu täuschen oder geltende Gesetze zu brechen. Sie sind dafür verantwortlich, wie Sie das von Ihnen Erstellte veröffentlichen und lizenzieren.", "terms_s3h": "Zulässige Nutzung", "terms_s3p": "Persönliche, bildungsbezogene und kreative Nutzung ist willkommen. Die kommerzielle Nutzung von generiertem Audio liegt in Ihrer Verantwortung: Klären Sie sie gegenüber den Rechten an Ihrem Ausgangstext und allen in Ihrer Rechtsordnung geltenden Regeln zur Stimmenlizenzierung.", "terms_s4h": "Änderungen", "terms_s4p": "Funktionen und diese Bedingungen können sich weiterentwickeln; wesentliche Änderungen werden auf dieser Seite mit einem neuen Datum vermerkt.", "terms_updated": "Zuletzt aktualisiert: Oktober 2026", "tut_g1h": "Erste Schritte: Ihre erste generierte Stimme", "tut_g1p": "Beginnen Sie mit der Sprachauswahl — sie bestimmt, welche Stimmen Sie sehen. Wählen Sie die Sprache, in der Ihr Text geschrieben ist, und probieren Sie dann zwei oder drei Stimmen über die Vorschau-Schaltfläche aus; Stimmen unterscheiden sich stark in Wärme und Tempo. Tippen Sie zuerst einen kurzen Absatz ein, generieren Sie ihn und hören Sie ihn sich an. Wenn sich die Stimme richtig anfühlt, schalten Sie Geschwindigkeit oder Tonhöhe ein und passen Sie sie in kleinen Schritten an: +10% Geschwindigkeit passt zu energiegeladenen Inhalten, eine etwas tiefere Tonhöhe wirkt oft souveräner. Generieren Sie bei allem, was länger als eine Seite ist, Abschnitt für Abschnitt und behalten Sie dieselbe Stimme und dieselben Einstellungen bei, damit die Teile ineinandergreifen.", "tut_g2h": "So nutzen Sie die Pausenfunktion", "tut_g2p": "Pausenmarker fügen exakte Stille in das generierte Audio ein. Tippen Sie <b>[break:200ms]</b> für eine kurze Pause, <b>[break:1s]</b> oder <b>[break:2s]</b> für längere Pausen — dramatische Enthüllungen, Listenelemente und Szenenwechsel wirken mit Luft drumherum besser. Mit <b>Ctrl+B</b> setzen Sie einen [break:500ms]-Marker an Ihre Cursorposition. Marker erscheinen nie im Audio oder in den Untertiteln; Sie hören nur die Pause. Eine gute Faustregel: 300–600ms zwischen Sätzen mit Themenwechsel, 1–2 Sekunden zwischen Szenen. Beachten Sie, dass der Vorschaumodus die Marker einfach überspringt — beurteilen Sie das endgültige Timing also anhand der generierten Datei.", "tut_g3h": "Ein Rundgang durch die Stimmensammlung", "tut_g3p": "Der Katalog von Text 2 Speech umfasst 300+ neuronale Stimmen in 75 Sprachen, und jede Sprache bietet mehrere Charaktere — sachlich wie ein Nachrichtensprecher, warm und gesprächig, hell und jugendlich. Die Namen verraten ihre Region (Aria - US, Natasha - AU), und einige Stimmen sind mehrsprachig und kommen mit gemischtsprachigem Text problemlos zurecht. Geschlechterfilter und Namenssuche halten die Liste überschaubar. Im Zweifel generieren Sie denselben Absatz mit drei Kandidatenstimmen und entscheiden Sie mit den Ohren, nicht nach den Namen: Die richtige Stimme hängt vom Material ab, nicht vom Etikett.", "tut_h1": "Anleitung", "tut_sub": "Kurze, praktische Anleitungen, um das Beste aus Text 2 Speech herauszuholen."}, "es": {"auth_alert_create": "Las cuentas llegarán con el lanzamiento público. No necesitas registrarte para convertir texto.", "auth_alert_forgot": "El restablecimiento de contraseña llegará junto con las cuentas en el lanzamiento público.", "auth_alert_signin": "Las cuentas llegarán con el lanzamiento público. Todo en Text 2 Speech ya funciona sin iniciar sesión.", "auth_create": "Crear una cuenta", "auth_email": "Correo electrónico", "auth_forgot": "¿Olvidaste tu contraseña?", "auth_h1": "Bienvenido de nuevo", "auth_newq": "¿Nuevo por aquí?", "auth_pass": "Contraseña", "auth_signin": "Iniciar sesión", "auth_sub": "Las cuentas son opcionales: el conversor funciona por completo sin una. Inicia sesión para sincronizar tus voces favoritas y tu historial (disponible con el lanzamiento público).", "doc_auth": "Cuenta — Text 2 Speech", "doc_donate": "Donar — Mantén Text 2 Speech gratis para todos | Text 2 Speech", "doc_privacy": "Política de privacidad — Text 2 Speech", "doc_support": "Soporte y preguntas frecuentes — Ayuda de texto a voz de Text 2 Speech", "doc_terms": "Términos del servicio — Text 2 Speech", "doc_tutorial": "Tutorial de texto a voz — Cómo crear locuciones | Text 2 Speech", "don_alert": "El pago de donaciones se abrirá con el lanzamiento público. ¡Gracias por tu ofrecimiento!", "don_alipay": "Alipay", "don_amount": "Cantidad", "don_btn": "Donar ahora", "don_crypto": "Criptomonedas", "don_crypto_sub": "USDT · ETH · BTC y más", "don_h1": "Donar", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech es gratis para todos. Si te ahorra tiempo, una pequeña aportación ayuda a que siga siéndolo.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "A qué se destinan las donaciones", "don_where_p": "Costes de servidor · Desarrollo de funciones · Mantenimiento del servicio", "foot_privacy": "Política de privacidad", "foot_terms": "Términos del servicio", "nav_donate": "Donar", "nav_home": "Inicio", "nav_support": "Soporte", "nav_tutorial": "Tutorial", "priv_h1": "Política de privacidad", "priv_intro": "Text 2 Speech está diseñado para necesitar la menor cantidad posible de tus datos. Puedes usar el conversor sin una cuenta y sin darnos tu nombre ni tu correo electrónico.", "priv_s1h": "El texto que conviertes", "priv_s1p": "El texto que envías se manda al motor de voz únicamente para producir tu audio. Los archivos generados se almacenan vinculados a un identificador de sesión aleatorio y se eliminan automáticamente al cabo de poco tiempo; nunca se publican, se indexan ni se usan para entrenar modelos.", "priv_s2h": "Cookies y analíticas", "priv_s2p": "Si aceptas el banner de cookies, usamos cookies de analítica que respetan la privacidad para contar las visitas y ver qué funciones son populares. Rechazarlas no cambia en nada el funcionamiento de la herramienta.", "priv_s3h": "Lo que nunca hacemos", "priv_s3p": "No vendemos datos personales, no creamos perfiles publicitarios y no conservamos el audio que generas una vez que termina tu sesión.", "priv_s4h": "Contacto", "priv_s4p": "Preguntas sobre privacidad: escríbenos a través de la <a href=\"/support.html\">página de soporte</a>.", "priv_updated": "Última actualización: octubre de 2026", "sup_alert": "Gracias: la bandeja de soporte se abrirá con el lanzamiento público. Por ahora, las preguntas frecuentes cubren los casos más comunes.", "sup_contact_h": "Contacto", "sup_email": "Tu correo electrónico", "sup_h1": "Soporte", "sup_msg": "Mensaje", "sup_msg_ph": "Describe qué ocurrió, qué voz usaste y qué esperabas...", "sup_notice": "El formulario de contacto se abrirá con el lanzamiento público. Mientras tanto, las preguntas frecuentes de la página principal responden a las dudas más comunes.", "sup_o1": "Problema de generación", "sup_o2": "Solicitud de voz", "sup_o3": "Informe de error", "sup_o4": "Negocios / licencias", "sup_o5": "Otro", "sup_quick_h": "Soluciones rápidas", "sup_quick_p": "• Sin sonido en la vista previa: comprueba que la pestaña del navegador no esté silenciada y prueba otra voz.<br>• Una voz no suena bien con tu texto: primero ajusta el idioma de la voz al idioma del texto.<br>• El texto largo tarda: divídelo en capítulos y genera por partes.<br>• Un resultado desapareció: los resultados solo existen durante la sesión actual del navegador; descárgalos cuanto antes.", "sup_send": "Enviar mensaje", "sup_sub": "La mayoría de las respuestas están en las preguntas frecuentes de la página principal. ¿Sigues atascado? Envíanos los detalles.", "sup_topic": "Tema", "terms_h1": "Términos del servicio", "terms_s1h": "El servicio", "terms_s1p": "Text 2 Speech convierte el texto que proporcionas en voz sintetizada y te permite reproducir y descargar el resultado, junto con los archivos de subtítulos. El servicio se ofrece tal cual, sin garantías de disponibilidad ininterrumpida.", "terms_s2h": "Tus responsabilidades", "terms_s2p": "Convierte solo texto que tengas derecho a usar. No utilices el audio generado para suplantar a personas reales, engañar a los oyentes ni infringir las leyes aplicables. Eres responsable de cómo publicas y licencias lo que creas.", "terms_s3h": "Uso aceptable", "terms_s3p": "El uso personal, educativo y creativo es bienvenido. El uso comercial del audio generado es responsabilidad tuya: debes asegurarte de que cumpla los derechos sobre tu texto original y las normas de licencia de voces aplicables en tu jurisdicción.", "terms_s4h": "Cambios", "terms_s4p": "Las funciones y estos términos pueden evolucionar; los cambios importantes se indicarán en esta página con una nueva fecha.", "terms_updated": "Última actualización: octubre de 2026", "tut_g1h": "Primeros pasos: tu primera voz generada", "tut_g1p": "Empieza por el selector de idioma: determina qué voces verás. Elige el idioma en el que está escrito tu texto y prueba dos o tres voces con el botón de vista previa; las voces difieren mucho en calidez y ritmo. Escribe primero un párrafo corto, genéralo y escúchalo. Cuando la voz te convenza, activa la velocidad o el tono y ajústalos poco a poco: un +10% de velocidad va bien con el contenido enérgico, y un tono algo más bajo suele sonar con más autoridad. Para textos de más de una página, genera sección por sección y mantén la misma voz y los mismos ajustes para que las partes encajen.", "tut_g2h": "Cómo usar la función de pausas", "tut_g2p": "Los marcadores de pausa insertan silencios exactos en el audio generado. Escribe <b>[break:200ms]</b> para una pausa breve, <b>[break:1s]</b> o <b>[break:2s]</b> para pausas más largas: las revelaciones dramáticas, los elementos de una lista y los cambios de escena funcionan mejor con aire a su alrededor. Al pulsar <b>Ctrl+B</b> se inserta un marcador [break:500ms] en la posición del cursor. Los marcadores nunca aparecen en el audio ni en los subtítulos; solo se oye la pausa. Una buena regla práctica: 300–600ms entre frases que cambian de tema y 1–2 segundos entre escenas. Ten en cuenta que el modo de vista previa simplemente omite los marcadores, así que juzga el ritmo final en el archivo generado.", "tut_g3h": "Un recorrido por la colección de voces", "tut_g3p": "El catálogo de Text 2 Speech reúne más de 300 voces neuronales en 75 idiomas, y cada idioma ofrece varias personalidades: plana estilo locutor de noticias, cálida y conversacional, alegre y juvenil. Los nombres indican su región (Aria - US, Natasha - AU), y algunas voces son multilingües y manejan con soltura textos en varios idiomas. El filtro por género y la búsqueda por nombre hacen la lista manejable. Si dudas, genera el mismo párrafo con tres voces candidatas y elige con los oídos, no por los nombres: la voz adecuada depende del material, no de la etiqueta.", "tut_h1": "Tutorial", "tut_sub": "Guías breves y prácticas para sacarle el máximo partido a Text 2 Speech."}, "fa": {"auth_alert_create": "حساب‌های کاربری با عرضه عمومی ارائه می‌شوند. برای تبدیل متن نیازی به ثبت‌نام نیست.", "auth_alert_forgot": "بازیابی گذرواژه هم‌زمان با حساب‌ها در عرضه عمومی ارائه می‌شود.", "auth_alert_signin": "حساب‌های کاربری با عرضه عمومی ارائه می‌شوند. همه‌چیز در Text 2 Speech هم‌اکنون بدون ورود نیز کار می‌کند.", "auth_create": "ایجاد حساب کاربری", "auth_email": "ایمیل", "auth_forgot": "گذرواژه را فراموش کرده‌اید؟", "auth_h1": "خوش بازگشتید", "auth_newq": "تازه‌وارد هستید؟", "auth_pass": "گذرواژه", "auth_signin": "ورود", "auth_sub": "حساب کاربری اختیاری است — مبدل بدون آن هم به‌طور کامل کار می‌کند. برای همگام نگه داشتن صداهای مورد علاقه و سوابقتان وارد شوید (با عرضه عمومی ارائه می‌شود).", "doc_auth": "حساب کاربری — Text 2 Speech", "doc_donate": "حمایت مالی — Text 2 Speech را برای همه رایگان نگه دارید | Text 2 Speech", "doc_privacy": "سیاست حفظ حریم خصوصی — Text 2 Speech", "doc_support": "پشتیبانی و پرسش‌های متداول — راهنمای تبدیل متن به گفتار Text 2 Speech", "doc_terms": "شرایط خدمات — Text 2 Speech", "doc_tutorial": "آموزش تبدیل متن به گفتار — نحوه ساخت نریشن | Text 2 Speech", "don_alert": "پرداخت حمایت مالی با عرضه عمومی فعال می‌شود. از پیشنهاد شما سپاسگزاریم!", "don_alipay": "Alipay", "don_amount": "مبلغ", "don_btn": "هم‌اکنون حمایت کنید", "don_crypto": "ارز دیجیتال", "don_crypto_sub": "USDT · ETH · BTC و موارد دیگر", "don_h1": "حمایت مالی", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech برای همه رایگان است. اگر در وقت شما صرفه‌جویی کرده، یک مشارکت کوچک آن را همین‌طور نگه می‌دارد.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "حمایت‌های مالی کجا هزینه می‌شوند", "don_where_p": "هزینه‌های سرور · توسعه قابلیت‌ها · نگهداری سرویس", "foot_privacy": "سیاست حفظ حریم خصوصی", "foot_terms": "شرایط خدمات", "nav_donate": "حمایت مالی", "nav_home": "خانه", "nav_support": "پشتیبانی", "nav_tutorial": "آموزش", "priv_h1": "سیاست حفظ حریم خصوصی", "priv_intro": "Text 2 Speech طوری طراحی شده است که به کمترین میزان ممکن از داده‌های شما نیاز داشته باشد. می‌توانید بدون حساب کاربری و بدون ارائه نام یا ایمیل خود از مبدل استفاده کنید.", "priv_s1h": "متنی که تبدیل می‌کنید", "priv_s1p": "متنی که ارسال می‌کنید فقط برای تولید صدای شما به موتور گفتار فرستاده می‌شود. فایل‌های تولیدشده با یک شناسه نشست تصادفی ذخیره می‌شوند و پس از مدت کوتاهی به‌طور خودکار حذف می‌گردند؛ هرگز منتشر، نمایه‌سازی یا برای آموزش مدل‌ها استفاده نمی‌شوند.", "priv_s2h": "کوکی‌ها و تحلیل‌ها", "priv_s2p": "اگر بنر کوکی را بپذیرید، از کوکی‌های تحلیلی حافظ حریم خصوصی برای شمارش بازدیدها و مشاهده محبوبیت قابلیت‌ها استفاده می‌کنیم. رد کردن آن هیچ تغییری در نحوه کار ابزار ایجاد نمی‌کند.", "priv_s3h": "کاری که هرگز انجام نمی‌دهیم", "priv_s3p": "ما داده‌های شخصی را نمی‌فروشیم، پروفایل تبلیغاتی ایجاد نمی‌کنیم و صدای تولیدشده شما را پس از پایان نشست نگه نمی‌داریم.", "priv_s4h": "تماس", "priv_s4p": "پرسش‌هایی درباره حریم خصوصی: از طریق <a href=\"/support.html\">صفحه پشتیبانی</a> با ما در تماس باشید.", "priv_updated": "آخرین به‌روزرسانی: اکتبر 2026", "sup_alert": "سپاسگزاریم — صندوق پیام پشتیبانی با عرضه عمومی فعال می‌شود. تا آن زمان، پرسش‌های متداول موارد رایج را پوشش می‌دهند.", "sup_contact_h": "تماس", "sup_email": "ایمیل شما", "sup_h1": "پشتیبانی", "sup_msg": "پیام", "sup_msg_ph": "شرح دهید چه اتفاقی افتاد، از کدام صدا استفاده کردید و انتظارتان چه بود...", "sup_notice": "فرم تماس با راه‌اندازی عمومی فعال می‌شود. تا آن زمان، پرسش‌های متداول صفحهٔ اصلی پاسخ رایج‌ترین سؤال‌ها را دارد.", "sup_o1": "مشکل در تولید", "sup_o2": "درخواست صدا", "sup_o3": "گزارش اشکال", "sup_o4": "تجاری / صدور مجوز", "sup_o5": "سایر", "sup_quick_h": "راه‌حل‌های سریع", "sup_quick_p": "• در پیش‌نمایش صدا ندارید: بررسی کنید برگه مرورگر بی‌صدا نباشد و صدای دیگری را امتحان کنید.<br>• صدایی برای متن شما نادرست به گوش می‌رسد: ابتدا زبان صدا را با زبان متن مطابقت دهید.<br>• متن طولانی کند است: آن را به فصل‌ها تقسیم کنید و به‌صورت بخش‌بخش تولید کنید.<br>• نتیجه‌ای ناپدید شد: نتایج فقط برای نشست فعلی مرورگر باقی می‌مانند — سریع دانلود کنید.", "sup_send": "ارسال پیام", "sup_sub": "بیشتر پاسخ‌ها در بخش پرسش‌های متداول صفحه اصلی قرار دارند. هنوز گیر کرده‌اید؟ جزئیات را برایمان بفرستید.", "sup_topic": "موضوع", "terms_h1": "شرایط خدمات", "terms_s1h": "سرویس", "terms_s1p": "Text 2 Speech متنی را که ارائه می‌دهید به گفتار مصنوعی تبدیل می‌کند و امکان پخش و دانلود نتیجه را همراه با فایل‌های زیرنویس در اختیارتان می‌گذارد. سرویس همان‌گونه که هست ارائه می‌شود، بدون تضمین در دسترس بودن بدون وقفه.", "terms_s2h": "مسئولیت‌های شما", "terms_s2p": "فقط متنی را تبدیل کنید که حق استفاده از آن را دارید. از صدای تولیدشده برای جعل هویت افراد واقعی، فریب شنوندگان یا نقض قوانین قابل اجرا استفاده نکنید. مسئولیت نحوه انتشار و اعطای مجوز آنچه ایجاد می‌کنید بر عهده شماست.", "terms_s3h": "استفاده مجاز", "terms_s3p": "استفاده شخصی، آموزشی و خلاقانه خوش‌آمد است. مسئولیت بررسی استفاده تجاری از صدای تولیدشده، از نظر حقوق متن منبع شما و هرگونه قانون صدور مجوز صدا در حوزه قضایی شما، بر عهده شماست.", "terms_s4h": "تغییرات", "terms_s4p": "قابلیت‌ها و این شرایط ممکن است تغییر کنند؛ تغییرات اساسی با تاریخی جدید در این صفحه ذکر خواهند شد.", "terms_updated": "آخرین به‌روزرسانی: اکتبر 2026", "tut_g1h": "شروع کار: نخستین صدای تولیدشده شما", "tut_g1p": "با انتخابگر زبان شروع کنید — این بخش تعیین می‌کند چه صداهایی را ببینید. زبانی را که متن شما به آن نوشته شده انتخاب کنید، سپس دو یا سه صدا را با دکمه پیش‌نمایش امتحان کنید؛ صداها از نظر گرما و ریتم تفاوت زیادی با هم دارند. ابتدا یک پاراگراف کوتاه بنویسید، آن را تولید کنید و گوش دهید. وقتی صدا درست به نظر رسید، سرعت یا زیر و بمی صدا را فعال کنید و با گام‌های کوچک تنظیمشان کنید: سرعت +10% برای محتوای پرانرژی مناسب است و زیر و بمی کمی پایین‌تر معمولاً مقتدرانه‌تر به گوش می‌رسد. برای هر متنی طولانی‌تر از یک صفحه، آن را بخش‌به‌بخش تولید کنید و صدا و تنظیمات یکسانی را حفظ کنید تا بخش‌ها در کنار هم بنشینند.", "tut_g2h": "نحوه استفاده از قابلیت مکث", "tut_g2p": "نشانگرهای مکث، سکوت دقیقی را در صدای تولیدشده درج می‌کنند. برای یک مکث کوتاه <b>[break:200ms]</b> و برای مکث‌های طولانی‌تر <b>[break:1s]</b> یا <b>[break:2s]</b> بنویسید — آشکارسازی‌های نمایشی، آیتم‌های فهرست و تغییر صحنه‌ها با فضایی در اطرافشان تأثیر بهتری می‌گذارند. با فشردن <b>Ctrl+B</b> یک نشانگر [break:500ms] در محل مکان‌نما درج می‌شود. نشانگرها هرگز در فایل صوتی یا زیرنویس‌ها ظاهر نمی‌شوند؛ تنها مکث را می‌شنوید. یک قاعده سرانگشتی خوب: بین جمله‌هایی که موضوعشان تغییر می‌کند 300–600ms و بین صحنه‌ها 1–2 ثانیه. توجه داشته باشید که حالت پیش‌نمایش نشانگرها را به‌سادگی رد می‌کند، بنابراین زمان‌بندی نهایی را بر اساس فایل تولیدشده قضاوت کنید.", "tut_g3h": "مروری بر مجموعه صداها", "tut_g3p": "کاتالوگ Text 2 Speech بیش از 300+ صدای عصبی در 75 زبان دارد و هر زبان چند شخصیت صوتی ارائه می‌دهد — گوینده‌وار و خبری، گرم و محاوره‌ای، درخشان و جوان. نام‌ها منطقه صدا را نشان می‌دهند (Aria - US, Natasha - AU) و چند صدای چندزبانه نیز وجود دارند که متن‌های چندزبانه را به‌خوبی اجرا می‌کنند. فیلتر جنسیت و جستجوی نام، فهرست را قابل مدیریت نگه می‌دارد. وقتی شک دارید، همان پاراگراف را با سه صدای کاندید تولید کنید و با گوشتان انتخاب کنید، نه با نام‌ها: صدای درست به محتوا بستگی دارد، نه به برچسب آن.", "tut_h1": "آموزش", "tut_sub": "راهنماهای کوتاه و کاربردی برای بهره‌برداری هرچه بیشتر از Text 2 Speech."}, "fr": {"auth_alert_create": "Les comptes arriveront avec le lancement public. Aucune inscription n'est nécessaire pour convertir du texte.", "auth_alert_forgot": "La réinitialisation du mot de passe arrivera avec les comptes lors du lancement public.", "auth_alert_signin": "Les comptes arriveront avec le lancement public. Tout sur Text 2 Speech fonctionne déjà sans connexion.", "auth_create": "Créer un compte", "auth_email": "E-mail", "auth_forgot": "Mot de passe oublié ?", "auth_h1": "Bon retour", "auth_newq": "Nouveau ici ?", "auth_pass": "Mot de passe", "auth_signin": "Se connecter", "auth_sub": "Les comptes sont facultatifs : le convertisseur fonctionne entièrement sans. Connectez-vous pour synchroniser vos voix favorites et votre historique (déploiement avec le lancement public).", "doc_auth": "Compte — Text 2 Speech", "doc_donate": "Faire un don — Gardez Text 2 Speech gratuit pour tous | Text 2 Speech", "doc_privacy": "Politique de confidentialité — Text 2 Speech", "doc_support": "Assistance et FAQ — Aide pour la synthèse vocale Text 2 Speech", "doc_terms": "Conditions d'utilisation — Text 2 Speech", "doc_tutorial": "Tutoriel de synthèse vocale — Comment créer des voix off | Text 2 Speech", "don_alert": "Le paiement des dons ouvrira avec le lancement public. Merci pour votre proposition !", "don_alipay": "Alipay", "don_amount": "Montant", "don_btn": "Faire un don", "don_crypto": "Cryptomonnaie", "don_crypto_sub": "USDT · ETH · BTC et plus", "don_h1": "Faire un don", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech est gratuit pour tout le monde. S'il vous fait gagner du temps, une petite contribution aide à ce qu'il le reste.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Où vont les dons", "don_where_p": "Coûts des serveurs · Développement de fonctionnalités · Maintenance du service", "foot_privacy": "Politique de confidentialité", "foot_terms": "Conditions d'utilisation", "nav_donate": "Faire un don", "nav_home": "Accueil", "nav_support": "Assistance", "nav_tutorial": "Tutoriel", "priv_h1": "Politique de confidentialité", "priv_intro": "Text 2 Speech est conçu pour avoir besoin du moins de vos données possible. Vous pouvez utiliser le convertisseur sans compte et sans nous donner votre nom ni votre e-mail.", "priv_s1h": "Le texte que vous convertissez", "priv_s1p": "Le texte que vous soumettez est envoyé au moteur vocal uniquement pour produire votre audio. Les fichiers générés sont stockés sous un identifiant de session aléatoire et supprimés automatiquement après une courte période ; ils ne sont jamais publiés, indexés ni utilisés pour entraîner des modèles.", "priv_s2h": "Cookies et analyses", "priv_s2p": "Si vous acceptez la bannière de cookies, nous utilisons des cookies d'analyse respectueux de la vie privée pour compter les visites et voir quelles fonctionnalités sont populaires. Refuser ne change rien au fonctionnement de l'outil.", "priv_s3h": "Ce que nous ne faisons jamais", "priv_s3p": "Nous ne vendons pas de données personnelles, nous ne construisons pas de profils publicitaires et nous ne conservons pas votre audio généré après la fin de votre session.", "priv_s4h": "Contact", "priv_s4p": "Questions sur la confidentialité : contactez-nous via la <a href=\"/support.html\">page d'assistance</a>.", "priv_updated": "Dernière mise à jour : octobre 2026", "sup_alert": "Merci — la boîte de réception de l'assistance ouvrira avec le lancement public. En attendant, la FAQ couvre les cas les plus courants.", "sup_contact_h": "Contact", "sup_email": "Votre e-mail", "sup_h1": "Assistance", "sup_msg": "Message", "sup_msg_ph": "Décrivez ce qui s'est passé, quelle voix vous avez utilisée et ce que vous attendiez...", "sup_notice": "Le formulaire de contact ouvrira au lancement public. D'ici là, la FAQ de la page d'accueil répond aux questions les plus courantes.", "sup_o1": "Problème de génération", "sup_o2": "Demande de voix", "sup_o3": "Rapport de bug", "sup_o4": "Commercial / licences", "sup_o5": "Autre", "sup_quick_h": "Solutions rapides", "sup_quick_p": "• Pas de son dans l'aperçu : vérifiez que l'onglet du navigateur n'est pas en sourdine et essayez une autre voix.<br>• Une voix sonne mal pour votre texte : faites d'abord correspondre la langue de la voix à la langue du texte.<br>• Un texte long est lent : divisez-le en chapitres et générez par morceaux.<br>• Un résultat a disparu : les résultats n'existent que pendant la session actuelle du navigateur — téléchargez-les vite.", "sup_send": "Envoyer le message", "sup_sub": "La plupart des réponses se trouvent dans la FAQ de la page d'accueil. Toujours bloqué ? Envoyez-nous les détails.", "sup_topic": "Sujet", "terms_h1": "Conditions d'utilisation", "terms_s1h": "Le service", "terms_s1p": "Text 2 Speech convertit le texte que vous fournissez en parole synthétisée et vous permet d'écouter et de télécharger le résultat, ainsi que les fichiers de sous-titres. Le service est fourni tel quel, sans garantie de disponibilité ininterrompue.", "terms_s2h": "Vos responsabilités", "terms_s2p": "Ne convertissez que du texte que vous avez le droit d'utiliser. N'utilisez pas l'audio généré pour usurper l'identité de personnes réelles, tromper les auditeurs ou enfreindre les lois applicables. Vous êtes responsable de la manière dont vous publiez et concédez sous licence ce que vous créez.", "terms_s3h": "Utilisation acceptable", "terms_s3p": "L'utilisation personnelle, éducative et créative est la bienvenue. L'utilisation commerciale de l'audio généré relève de votre responsabilité : vérifiez-la au regard des droits sur votre texte source et des règles de licence vocale applicables dans votre juridiction.", "terms_s4h": "Modifications", "terms_s4p": "Les fonctionnalités et ces conditions peuvent évoluer ; les changements importants seront indiqués sur cette page avec une nouvelle date.", "terms_updated": "Dernière mise à jour : octobre 2026", "tut_g1h": "Premiers pas : votre première voix générée", "tut_g1p": "Commencez par le sélecteur de langue : c'est lui qui détermine les voix que vous voyez. Choisissez la langue dans laquelle votre texte est écrit, puis essayez deux ou trois voix avec le bouton Aperçu ; les voix diffèrent beaucoup en chaleur et en rythme. Tapez d'abord un court paragraphe, générez-le et écoutez. Quand la voix vous convient, activez la Vitesse ou la Hauteur et ajustez-les par petits pas : +10% de vitesse convient aux contenus dynamiques, une hauteur légèrement plus basse sonne souvent plus autoritaire. Pour tout texte plus long qu'une page, générez section par section et gardez la même voix et les mêmes réglages pour que les parties s'enchaînent bien.", "tut_g2h": "Comment utiliser la fonction de pause", "tut_g2p": "Les marqueurs de pause insèrent un silence exact dans l'audio généré. Tapez <b>[break:200ms]</b> pour une courte respiration, <b>[break:1s]</b> ou <b>[break:2s]</b> pour des pauses plus longues : les révélations dramatiques, les éléments de liste et les changements de scène rendent bien mieux avec de l'air autour. Appuyer sur <b>Ctrl+B</b> insère un marqueur [break:500ms] à l'endroit du curseur. Les marqueurs n'apparaissent jamais dans l'audio ni dans les sous-titres ; vous n'entendez que la pause. Une bonne règle : 300–600ms entre des phrases qui changent de sujet, 1–2 secondes entre les scènes. Notez que le mode Aperçu ignore simplement les marqueurs, alors jugez le rythme final sur le fichier généré.", "tut_g3h": "Un tour de la collection de voix", "tut_g3p": "Le catalogue de Text 2 Speech compte plus de 300 voix neuronales dans 75 langues, et chaque langue propose plusieurs personnalités : neutre façon lecteur de journal, chaleureuse et conversationnelle, claire et juvénile. Les noms indiquent leur région (Aria - US, Natasha - AU), et quelques voix sont multilingues et gèrent avec aisance les textes en plusieurs langues. Le filtre par genre et la recherche par nom gardent la liste gérable. En cas de doute, générez le même paragraphe avec trois voix candidates et choisissez à l'oreille, pas d'après les noms : la bonne voix dépend du contenu, pas de l'étiquette.", "tut_h1": "Tutoriel", "tut_sub": "Des guides courts et pratiques pour tirer le meilleur parti de Text 2 Speech."}, "hi": {"auth_alert_create": "खाते सार्वजनिक लॉन्च के साथ आएंगे। टेक्स्ट बदलने के लिए साइन-अप की ज़रूरत नहीं है।", "auth_alert_forgot": "पासवर्ड रीसेट सार्वजनिक लॉन्च पर खातों के साथ आएगा।", "auth_alert_signin": "खाते सार्वजनिक लॉन्च के साथ आएंगे। Text 2 Speech पर सब कुछ पहले से ही साइन-आउट करके काम करता है।", "auth_create": "खाता बनाएं", "auth_email": "ईमेल", "auth_forgot": "पासवर्ड भूल गए?", "auth_h1": "फिर से स्वागत है", "auth_newq": "यहाँ नए हैं?", "auth_pass": "पासवर्ड", "auth_signin": "साइन इन करें", "auth_sub": "खाते वैकल्पिक हैं — कनवर्टर बिना खाते के भी पूरी तरह काम करता है। अपनी पसंदीदा आवाज़ों और इतिहास को सिंक रखने के लिए साइन इन करें (सार्वजनिक लॉन्च के साथ आ रहा है)।", "doc_auth": "खाता — Text 2 Speech", "doc_donate": "दान करें — Text 2 Speech को सभी के लिए मुफ़्त रखें | Text 2 Speech", "doc_privacy": "गोपनीयता नीति — Text 2 Speech", "doc_support": "सहायता और सामान्य प्रश्न — Text 2 Speech टेक्स्ट टू स्पीच मदद", "doc_terms": "सेवा की शर्तें — Text 2 Speech", "doc_tutorial": "टेक्स्ट टू स्पीच ट्यूटोरियल — वॉइसओवर कैसे बनाएं | Text 2 Speech", "don_alert": "दान भुगतान सार्वजनिक लॉन्च के साथ खुलेगा। आपके प्रस्ताव के लिए धन्यवाद!", "don_alipay": "Alipay", "don_amount": "राशि", "don_btn": "अभी दान करें", "don_crypto": "क्रिप्टोकरेंसी", "don_crypto_sub": "USDT · ETH · BTC और भी बहुत कुछ", "don_h1": "दान करें", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech सभी के लिए मुफ़्त है। अगर यह आपका समय बचाता है, तो एक छोटा-सा योगदान इसे ऐसा ही बनाए रखता है।", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "दान कहाँ जाता है", "don_where_p": "सर्वर लागत · फ़ीचर विकास · सेवा रखरखाव", "foot_privacy": "गोपनीयता नीति", "foot_terms": "सेवा की शर्तें", "nav_donate": "दान करें", "nav_home": "होम", "nav_support": "सहायता", "nav_tutorial": "ट्यूटोरियल", "priv_h1": "गोपनीयता नीति", "priv_intro": "Text 2 Speech को इस तरह बनाया गया है कि उसे आपके डेटा की कम से कम ज़रूरत पड़े। आप बिना खाते के और बिना अपना नाम या ईमेल दिए कनवर्टर का उपयोग कर सकते हैं।", "priv_s1h": "आप जो टेक्स्ट बदलते हैं", "priv_s1p": "आप जो टेक्स्ट भेजते हैं, वह केवल आपका ऑडियो बनाने के लिए स्पीच इंजन को भेजा जाता है। तैयार फ़ाइलें एक यादृच्छिक सत्र पहचानकर्ता के साथ संग्रहीत होती हैं और थोड़े समय बाद स्वतः हट जाती हैं; वे कभी प्रकाशित, अनुक्रमित या मॉडल को प्रशिक्षित करने के लिए उपयोग नहीं होतीं।", "priv_s2h": "कुकीज़ और विश्लेषण", "priv_s2p": "अगर आप कुकी बैनर स्वीकार करते हैं, तो हम गोपनीयता का सम्मान करने वाली विश्लेषण कुकीज़ का उपयोग करके विज़िट गिनते हैं और देखते हैं कि कौन-से फ़ीचर लोकप्रिय हैं। अस्वीकार करने से टूल के काम करने के तरीके में कोई बदलाव नहीं आता।", "priv_s3h": "जो हम कभी नहीं करते", "priv_s3p": "हम व्यक्तिगत डेटा नहीं बेचते, हम विज्ञापन प्रोफ़ाइल नहीं बनाते, और सत्र समाप्त होने के बाद हम आपका तैयार ऑडियो नहीं रखते।", "priv_s4h": "संपर्क", "priv_s4p": "गोपनीयता से जुड़े सवाल: <a href=\"/support.html\">सहायता पृष्ठ</a> के ज़रिए हमसे संपर्क करें।", "priv_updated": "अंतिम अपडेट: अक्टूबर 2026", "sup_alert": "धन्यवाद — सहायता इनबॉक्स सार्वजनिक लॉन्च के साथ खुलेगा। फ़िलहाल, सामान्य प्रश्न आम मामलों को कवर करते हैं।", "sup_contact_h": "संपर्क", "sup_email": "आपका ईमेल", "sup_h1": "सहायता", "sup_msg": "संदेश", "sup_msg_ph": "बताएं कि क्या हुआ, आपने कौन-सी आवाज़ इस्तेमाल की, और आपको क्या उम्मीद थी...", "sup_notice": "संपर्क फ़ॉर्म सार्वजनिक लॉन्च के साथ खुलेगा। तब तक, होम पेज पर FAQ सबसे आम सवालों के जवाब देता है।", "sup_o1": "तैयारी में समस्या", "sup_o2": "आवाज़ का अनुरोध", "sup_o3": "बग रिपोर्ट", "sup_o4": "व्यवसाय / लाइसेंसिंग", "sup_o5": "अन्य", "sup_quick_h": "त्वरित समाधान", "sup_quick_p": "• पूर्वावलोकन में आवाज़ नहीं: जांचें कि ब्राउज़र टैब म्यूट तो नहीं है और दूसरी आवाज़ आज़माएं।<br>• आवाज़ आपके टेक्स्ट के लिए ग़लत लगती है: पहले आवाज़ की भाषा को टेक्स्ट की भाषा से मिलाएं।<br>• लंबा टेक्स्ट धीमा है: उसे अध्यायों में बांटकर हिस्सों में तैयार करें।<br>• कोई परिणाम गायब हो गया: परिणाम केवल वर्तमान ब्राउज़र सत्र के लिए रहते हैं — तुरंत डाउनलोड करें।", "sup_send": "संदेश भेजें", "sup_sub": "अधिकांश उत्तर होम पेज के सामान्य प्रश्नों में मिलते हैं। फिर भी अटके हैं? हमें विवरण भेजें।", "sup_topic": "विषय", "terms_h1": "सेवा की शर्तें", "terms_s1h": "सेवा", "terms_s1p": "Text 2 Speech आपके दिए गए टेक्स्ट को संश्लेषित भाषण में बदलता है और आपको परिणाम चलाने व डाउनलोड करने देता है, उपशीर्षक फ़ाइलों के साथ। सेवा जैसी है वैसी ही प्रदान की जाती है, बिना निर्बाध उपलब्धता की गारंटी के।", "terms_s2h": "आपकी ज़िम्मेदारियाँ", "terms_s2p": "केवल वही टेक्स्ट बदलें जिसका उपयोग करने का अधिकार आपके पास है। तैयार ऑडियो का उपयोग असली लोगों का रूप धारण करने, श्रोताओं को धोखा देने या लागू कानूनों को तोड़ने के लिए न करें। आप जो बनाते हैं, उसे कैसे प्रकाशित और लाइसेंस करते हैं, इसकी ज़िम्मेदारी आपकी है।", "terms_s3h": "स्वीकार्य उपयोग", "terms_s3p": "व्यक्तिगत, शैक्षणिक और रचनात्मक उपयोग स्वागत योग्य है। तैयार ऑडियो के व्यावसायिक उपयोग की ज़िम्मेदारी आपकी है कि आप अपने स्रोत टेक्स्ट के अधिकारों और अपने क्षेत्राधिकार में लागू आवाज़-लाइसेंसिंग नियमों के अनुसार उसे सुनिश्चित करें।", "terms_s4h": "परिवर्तन", "terms_s4p": "फ़ीचर और ये शर्तें समय के साथ बदल सकती हैं; महत्वपूर्ण बदलाव इस पृष्ठ पर नई तारीख़ के साथ दर्ज किए जाएंगे।", "terms_updated": "अंतिम अपडेट: अक्टूबर 2026", "tut_g1h": "शुरुआत करें: आपकी पहली तैयार आवाज़", "tut_g1p": "भाषा चयनकर्ता से शुरुआत करें — वही तय करता है कि आपको कौन-सी आवाज़ें दिखेंगी। वह भाषा चुनें जिसमें आपका टेक्स्ट लिखा है, फिर पूर्वावलोकन बटन से दो-तीन आवाज़ें आज़माएं; आवाज़ों में गर्माहट और गति का काफ़ी अंतर होता है। पहले एक छोटा पैराग्राफ लिखें, उसे तैयार करें और सुनें। जब आवाज़ सही लगे, तो गति या स्वर-ऊंचाई चालू करके उन्हें छोटे चरणों में समायोजित करें: +10% गति जोशीली सामग्री के लिए उपयुक्त है, और थोड़ा निचला स्वर अक्सर ज़्यादा अधिकारपूर्ण लगता है। एक पृष्ठ से लंबे टेक्स्ट के लिए, उसे खंड-दर-खंड तैयार करें और वही आवाज़ व सेटिंग बनाए रखें ताकि हिस्से आपस में घुल-मिल जाएं।", "tut_g2h": "ब्रेक फ़ीचर का उपयोग कैसे करें", "tut_g2p": "ब्रेक मार्कर तैयार ऑडियो में सटीक मौन डालते हैं। छोटे ठहराव के लिए <b>[break:200ms]</b> लिखें, और लंबे ठहराव के लिए <b>[break:1s]</b> या <b>[break:2s]</b> — नाटकीय खुलासे, सूची की चीज़ें और दृश्य परिवर्तन आसपास की हवा के साथ बेहतर असर डालते हैं। <b>Ctrl+B</b> दबाने से आपके कर्सर पर [break:500ms] मार्कर आ जाता है। मार्कर कभी ऑडियो या उपशीर्षकों में नहीं दिखते; आपको सिर्फ़ ठहराव सुनाई देता है। एक अच्छा नियम: विषय बदलने वाले वाक्यों के बीच 300–600ms, और दृश्यों के बीच 1–2 सेकंड। ध्यान रखें कि पूर्वावलोकन मोड मार्कर को सीधे छोड़ देता है, इसलिए अंतिम समय का आकलन तैयार फ़ाइल पर ही करें।", "tut_g3h": "आवाज़ों के संग्रह की एक झलक", "tut_g3p": "Text 2 Speech के कैटलॉग में 75 भाषाओं में 300+ न्यूरल आवाज़ें हैं, और हर भाषा कई व्यक्तित्व पेश करती है — समाचार-वाचक जैसी सपाट, गर्म और संवादात्मक, चमकीली और युवा। नामों में उनका क्षेत्र होता है (Aria - US, Natasha - AU), और कुछ आवाज़ें बहुभाषी हैं, जो मिश्रित-भाषा टेक्स्ट को सहजता से संभालती हैं। लिंग फ़िल्टर और नाम से खोज सूची को संभालने योग्य बनाए रखते हैं। जब संदेह हो, तो एक ही पैराग्राफ को तीन संभावित आवाज़ों से तैयार करें और नामों से नहीं, अपने कानों से चुनें: सही आवाज़ सामग्री पर निर्भर करती है, लेबल पर नहीं।", "tut_h1": "ट्यूटोरियल", "tut_sub": "Text 2 Speech का अधिकतम लाभ उठाने के लिए छोटे, व्यावहारिक गाइड।"}, "hu": {"auth_alert_create": "A fiókok a nyilvános indulással érkeznek. A szöveg átalakításához nincs szükség regisztrációra.", "auth_alert_forgot": "A jelszó-visszaállítás a fiókokkal együtt, a nyilvános induláskor érkezik.", "auth_alert_signin": "A fiókok a nyilvános indulással érkeznek. A Text 2 Speechban minden már most is működik kijelentkezve.", "auth_create": "Fiók létrehozása", "auth_email": "E-mail", "auth_forgot": "Elfelejtetted a jelszavad?", "auth_h1": "Üdv újra", "auth_newq": "Új vagy itt?", "auth_pass": "Jelszó", "auth_signin": "Bejelentkezés", "auth_sub": "A fiók nem kötelező — az átalakító teljesen működik nélküle is. Jelentkezz be, hogy a kedvenc hangjaid és az előzményeid szinkronban maradjanak (a nyilvános indulással érkezik).", "doc_auth": "Fiók — Text 2 Speech", "doc_donate": "Támogatás — segíts, hogy a Text 2 Speech mindenki számára ingyenes maradjon | Text 2 Speech", "doc_privacy": "Adatvédelmi szabályzat — Text 2 Speech", "doc_support": "Segítség és GYIK — Text 2 Speech szövegfelolvasó támogatás", "doc_terms": "Felhasználási feltételek — Text 2 Speech", "doc_tutorial": "Szövegfelolvasási útmutató — hogyan készíts narrációt | Text 2 Speech", "don_alert": "Az adományok kifizetése a nyilvános indulással nyílik meg. Köszönjük a felajánlást!", "don_alipay": "Alipay", "don_amount": "Összeg", "don_btn": "Adományozok", "don_crypto": "Kriptovaluta", "don_crypto_sub": "USDT · ETH · BTC és továbbiak", "don_h1": "Támogatás", "don_paypal": "PayPal (USD)", "don_sub": "A Text 2 Speech mindenki számára ingyenes. Ha időt takarít meg neked, egy kis hozzájárulás segít, hogy így is maradjon.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Mire fordítjuk az adományokat", "don_where_p": "Szerverköltségek · Funkciófejlesztés · A szolgáltatás karbantartása", "foot_privacy": "Adatvédelmi szabályzat", "foot_terms": "Felhasználási feltételek", "nav_donate": "Támogatás", "nav_home": "Kezdőlap", "nav_support": "Segítség", "nav_tutorial": "Útmutató", "priv_h1": "Adatvédelmi szabályzat", "priv_intro": "A Text 2 Speecht úgy terveztük, hogy minél kevesebb adatodra legyen szüksége. Az átalakítót fiók nélkül használhatod, anélkül hogy megadnád a neved vagy az e-mail-címed.", "priv_s1h": "Az általad átalakított szöveg", "priv_s1p": "A beküldött szöveget kizárólag azért küldjük el a beszédmotornak, hogy elkészítse a hangot. A generált fájlokat véletlenszerű munkamenet-azonosítóhoz tároljuk, és rövid idő után automatikusan töröljük; sosem tesszük közzé, nem indexeljük és nem használjuk fel modellek képzésére.", "priv_s2h": "Sütik és analitika", "priv_s2p": "Ha elfogadod a sütibannert, adatvédelmet tiszteletben tartó analitikai sütiket használunk a látogatások számlálására és annak megfigyelésére, mely funkciók népszerűek. Az elutasítás semmit sem változtat az eszköz működésén.", "priv_s3h": "Amit sosem teszünk", "priv_s3p": "Nem adjuk el a személyes adatokat, nem építünk hirdetési profilokat, és nem őrizzük meg a generált hangodat a munkameneted vége után.", "priv_s4h": "Kapcsolat", "priv_s4p": "Adatvédelmi kérdések: érj el minket a <a href=\"/support.html\">segítségoldalon</a> keresztül.", "priv_updated": "Utolsó frissítés: 2026. október", "sup_alert": "Köszönjük — a támogatási postaláda a nyilvános indulással nyílik meg. Addig a GYIK lefedi a gyakori eseteket.", "sup_contact_h": "Kapcsolat", "sup_email": "Az e-mail-címed", "sup_h1": "Segítség", "sup_msg": "Üzenet", "sup_msg_ph": "Írd le, mi történt, melyik hangot használtad, és mit vártál...", "sup_notice": "A kapcsolatfelvételi űrlap a nyilvános indulással nyílik meg. Addig a kezdőlap GYIK része válaszol a leggyakoribb kérdésekre.", "sup_o1": "Generálási probléma", "sup_o2": "Hangkérés", "sup_o3": "Hibajelentés", "sup_o4": "Üzlet / licencelés", "sup_o5": "Egyéb", "sup_quick_h": "Gyors megoldások", "sup_quick_p": "• Nincs hang az előnézetben: ellenőrizd, hogy a böngészőfül nincs-e lenémítva, és próbálj ki egy másik hangot.<br>• Egy hang rosszul hangzik a szövegedhez: először igazítsd a hang nyelvét a szöveg nyelvéhez.<br>• A hosszú szöveg lassú: bontsd fejezetekre, és részenként generáld.<br>• Eltűnt egy eredmény: az eredmények csak az aktuális böngészőmunkamenetben élnek — töltsd le őket azonnal.", "sup_send": "Üzenet küldése", "sup_sub": "A legtöbb választ a kezdőlapon található GYIK tartalmazza. Még mindig elakadtál? Küldd el nekünk a részleteket.", "sup_topic": "Téma", "terms_h1": "Felhasználási feltételek", "terms_s1h": "A szolgáltatás", "terms_s1p": "A Text 2 Speech az általad megadott szöveget szintetizált beszéddé alakítja, és lehetővé teszi az eredmény lejátszását és letöltését a feliratfájlokkal együtt. A szolgáltatást jelen állapotában nyújtjuk, a folyamatos elérhetőség garanciája nélkül.", "terms_s2h": "A te felelősséged", "terms_s2p": "Csak olyan szöveget alakíts át, amelynek használatára jogosult vagy. Ne használd a generált hangot valódi személyek megszemélyesítésére, a hallgatók megtévesztésére vagy a hatályos törvények megsértésére. Te felelsz azért, hogyan teszed közzé és licenceld, amit létrehozol.", "terms_s3h": "Elfogadható használat", "terms_s3p": "A személyes, oktatási és kreatív felhasználás szívesen látott. A generált hang kereskedelmi felhasználása a te felelősséged: tisztázd a forrásként használt szöveghez fűződő jogokat és a joghatóságodban érvényes hanglicencelési szabályokat.", "terms_s4h": "Változások", "terms_s4p": "A funkciók és ezek a feltételek változhatnak; a lényeges változásokat ezen az oldalon, új dátummal jelezzük.", "terms_updated": "Utolsó frissítés: 2026. október", "tut_g1h": "Első lépések: az első generált hangod", "tut_g1p": "Kezdd a nyelvválasztóval — ez határozza meg, milyen hangokat látsz. Válaszd ki azt a nyelvet, amelyen a szöveged íródott, majd próbálj ki két-három hangot az Előnézet gombbal; a hangok melegsége és tempója nagyon eltérő lehet. Először írj be egy rövid bekezdést, generáld le és hallgasd meg. Ha a hang megfelelőnek tűnik, kapcsold be a sebességet vagy a hangmagasságot, és apró lépésekben állíts rajtuk: a +10%-os sebesség az energikus tartalmakhoz illik, a kissé alacsonyabb hangmagasság pedig gyakran tekintélyesebben hangzik. Egy oldalnál hosszabb szövegnél szakaszonként generálj, és tartsd meg ugyanazt a hangot és beállításokat, hogy a részek összeolvadjanak.", "tut_g2h": "Hogyan használd a szünet funkciót", "tut_g2p": "A szünetjelölők pontos csendet illesztenek a generált hangba. Írd be a <b>[break:200ms]</b> jelölést egy rövid szünethez, a <b>[break:1s]</b> vagy <b>[break:2s]</b> jelölést hosszabb szünetekhez — a drámai fordulatok, a listaelemek és a jelenetváltások jobban működnek, ha levegő veszi körül őket. A <b>Ctrl+B</b> lenyomásával egy [break:500ms] jelölés kerül a kurzor helyére. A jelölések sosem jelennek meg a hangban vagy a feliratokban; csak a szünetet hallod. Jó ökölszabály: 300–600ms a témát váltó mondatok között, 1–2 másodperc a jelenetek között. Fontos, hogy az Előnézet mód egyszerűen átugorja a jelöléseket, ezért a végső időzítést a generált fájl alapján ítéld meg.", "tut_g3h": "Körbevezetés a hanggyűjteményben", "tut_g3p": "A Text 2 Speech katalógusa több mint 300 neurális hangot tartalmaz 75 nyelven, és minden nyelv többféle karaktert kínál — hírolvasóan tárgyilagost, melegen társalgósit, fényesen fiatalt. A nevek jelzik a régiót is (Aria - US, Natasha - AU), néhány hang pedig többnyelvű, és kecsesen kezeli a vegyes nyelvű szövegeket. A nem szerinti szűrés és a név szerinti keresés áttekinthetővé teszi a listát. Ha bizonytalan vagy, generáld le ugyanazt a bekezdést három jelölt hanggal, és a füleddel válassz, ne a nevek alapján: a megfelelő hang az anyagtól függ, nem a címkétől.", "tut_h1": "Útmutató", "tut_sub": "Rövid, gyakorlatias útmutatók, hogy a legtöbbet hozd ki a Text 2 Speechból."}, "id": {"auth_alert_create": "Akun akan hadir bersama peluncuran publik. Tidak perlu mendaftar untuk mengonversi teks.", "auth_alert_forgot": "Atur ulang kata sandi akan hadir bersama akun saat peluncuran publik.", "auth_alert_signin": "Akun akan hadir bersama peluncuran publik. Semua hal di Text 2 Speech sudah berfungsi tanpa masuk.", "auth_create": "Buat akun", "auth_email": "Email", "auth_forgot": "Lupa kata sandi?", "auth_h1": "Selamat datang kembali", "auth_newq": "Baru di sini?", "auth_pass": "Kata sandi", "auth_signin": "Masuk", "auth_sub": "Akun bersifat opsional — konverter berfungsi penuh tanpanya. Masuk untuk menjaga suara favorit dan riwayat Anda tetap sinkron (diluncurkan bersama peluncuran publik).", "doc_auth": "Akun — Text 2 Speech", "doc_donate": "Donasi — Jaga Text 2 Speech Tetap Gratis untuk Semua Orang | Text 2 Speech", "doc_privacy": "Kebijakan Privasi — Text 2 Speech", "doc_support": "Dukungan & FAQ — Bantuan Teks ke Suara Text 2 Speech", "doc_terms": "Ketentuan Layanan — Text 2 Speech", "doc_tutorial": "Tutorial Teks ke Suara — Cara Membuat Sulih Suara | Text 2 Speech", "don_alert": "Pembayaran donasi akan dibuka bersama peluncuran publik. Terima kasih atas tawaran Anda!", "don_alipay": "Alipay", "don_amount": "Jumlah", "don_btn": "Donasi Sekarang", "don_crypto": "Mata uang kripto", "don_crypto_sub": "USDT · ETH · BTC dan lainnya", "don_h1": "Donasi", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech gratis untuk semua orang. Jika Text 2 Speech menghemat waktu Anda, kontribusi kecil membantu mempertahankannya.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Ke mana donasi digunakan", "don_where_p": "Biaya server · Pengembangan fitur · Pemeliharaan layanan", "foot_privacy": "Kebijakan Privasi", "foot_terms": "Ketentuan Layanan", "nav_donate": "Donasi", "nav_home": "Beranda", "nav_support": "Dukungan", "nav_tutorial": "Tutorial", "priv_h1": "Kebijakan Privasi", "priv_intro": "Text 2 Speech dirancang agar membutuhkan data Anda sesedikit mungkin. Anda dapat menggunakan konverter tanpa akun dan tanpa memberikan nama atau email Anda kepada kami.", "priv_s1h": "Teks yang Anda konversi", "priv_s1p": "Teks yang Anda kirim hanya dikirim ke mesin ucapan untuk menghasilkan audio Anda. File yang dihasilkan disimpan dengan pengenal sesi acak dan dihapus secara otomatis setelah waktu singkat; file tersebut tidak pernah diterbitkan, diindeks, atau digunakan untuk melatih model.", "priv_s2h": "Cookie dan analitik", "priv_s2p": "Jika Anda menerima banner cookie, kami menggunakan cookie analitik yang menghormati privasi untuk menghitung kunjungan dan melihat fitur mana yang populer. Menolaknya tidak mengubah apa pun tentang cara kerja alat ini.", "priv_s3h": "Hal yang tidak pernah kami lakukan", "priv_s3p": "Kami tidak menjual data pribadi, tidak membangun profil periklanan, dan tidak menyimpan audio hasil buatan Anda setelah sesi Anda berakhir.", "priv_s4h": "Kontak", "priv_s4p": "Pertanyaan tentang privasi: hubungi kami melalui <a href=\"/support.html\">halaman Dukungan</a>.", "priv_updated": "Terakhir diperbarui: Oktober 2026", "sup_alert": "Terima kasih — kotak masuk dukungan akan dibuka bersama peluncuran publik. Untuk saat ini, FAQ mencakup kasus-kasus yang umum.", "sup_contact_h": "Kontak", "sup_email": "Email Anda", "sup_h1": "Dukungan", "sup_msg": "Pesan", "sup_msg_ph": "Jelaskan apa yang terjadi, suara mana yang Anda gunakan, dan apa yang Anda harapkan...", "sup_notice": "Formulir kontak dibuka saat peluncuran publik. Sampai saat itu, FAQ di beranda menjawab pertanyaan yang paling umum.", "sup_o1": "Masalah pembuatan", "sup_o2": "Permintaan suara", "sup_o3": "Laporan bug", "sup_o4": "Bisnis / lisensi", "sup_o5": "Lainnya", "sup_quick_h": "Perbaikan cepat", "sup_quick_p": "• Tidak ada suara saat Pratinjau: periksa tab browser tidak dalam keadaan senyap dan coba suara lain.<br>• Suara terdengar tidak cocok untuk teks Anda: sesuaikan dulu Bahasa Suara dengan bahasa teks.<br>• Teks panjang lambat: bagi menjadi beberapa bab dan hasilkan per bagian.<br>• Hasil menghilang: hasil hanya tersimpan selama sesi browser saat ini — segera unduh.", "sup_send": "Kirim pesan", "sup_sub": "Sebagian besar jawaban ada di FAQ di halaman utama. Masih buntu? Kirimkan detailnya kepada kami.", "sup_topic": "Topik", "terms_h1": "Ketentuan Layanan", "terms_s1h": "Layanan", "terms_s1p": "Text 2 Speech mengonversi teks yang Anda berikan menjadi ucapan sintetis dan memungkinkan Anda memutar serta mengunduh hasilnya, beserta file subtitle. Layanan disediakan sebagaimana adanya, tanpa jaminan ketersediaan tanpa gangguan.", "terms_s2h": "Tanggung jawab Anda", "terms_s2p": "Konversikan hanya teks yang berhak Anda gunakan. Jangan gunakan audio yang dihasilkan untuk meniru orang sungguhan, menipu pendengar, atau melanggar hukum yang berlaku. Anda bertanggung jawab atas cara Anda menerbitkan dan melisensikan apa yang Anda buat.", "terms_s3h": "Penggunaan yang dapat diterima", "terms_s3p": "Penggunaan pribadi, pendidikan, dan kreatif dipersilakan. Penggunaan komersial atas audio yang dihasilkan adalah tanggung jawab Anda untuk memastikan kesesuaiannya dengan hak atas teks sumber Anda dan aturan lisensi suara yang berlaku di wilayah hukum Anda.", "terms_s4h": "Perubahan", "terms_s4p": "Fitur dan ketentuan ini dapat berkembang; perubahan penting akan dicatat di halaman ini dengan tanggal baru.", "terms_updated": "Terakhir diperbarui: Oktober 2026", "tut_g1h": "Memulai: suara pertama yang Anda hasilkan", "tut_g1p": "Mulailah dengan pemilih bahasa — itulah yang menentukan suara mana yang Anda lihat. Pilih bahasa tempat teks Anda ditulis, lalu coba dua atau tiga suara dengan tombol Pratinjau; suara bisa sangat berbeda dalam kehangatan dan tempo. Ketik dulu satu paragraf pendek, hasilkan, dan dengarkan. Begitu suaranya terasa pas, aktifkan Kecepatan atau Nada dan geser sedikit demi sedikit: kecepatan +10% cocok untuk konten yang energik, sementara nada yang sedikit lebih rendah sering terdengar lebih berwibawa. Untuk teks yang lebih panjang dari satu halaman, hasilkan bagian demi bagian dan pertahankan suara serta pengaturan yang sama agar bagian-bagiannya menyatu.", "tut_g2h": "Cara menggunakan fitur jeda", "tut_g2p": "Penanda jeda menyisipkan keheningan yang tepat ke dalam audio yang dihasilkan. Ketik <b>[break:200ms]</b> untuk jeda singkat, <b>[break:1s]</b> atau <b>[break:2s]</b> untuk jeda yang lebih lama — pengungkapan dramatis, item daftar, dan pergantian adegan semuanya terasa lebih baik dengan ruang di sekitarnya. Menekan <b>Ctrl+B</b> akan menempatkan penanda [break:500ms] di posisi kursor Anda. Penanda tidak pernah muncul di audio atau subtitle; Anda hanya mendengar jedanya. Aturan praktis yang baik: 300–600ms di antara kalimat yang berganti topik, 1–2 detik di antara adegan. Perlu diingat bahwa mode Pratinjau langsung melewati penanda, jadi nilailah waktu akhir dari file yang dihasilkan.", "tut_g3h": "Mengenal koleksi suara", "tut_g3p": "Katalog Text 2 Speech menyimpan 300+ suara neural dalam 75 bahasa, dan setiap bahasa menawarkan beberapa kepribadian — datar ala pembaca berita, hangat dan akrab, cerah dan muda. Nama membawa wilayahnya (Aria - US, Natasha - AU), dan beberapa suara bersifat multibahasa, menangani teks campuran bahasa dengan mulus. Filter gender dan pencarian nama membuat daftar tetap mudah dikelola. Jika ragu, hasilkan paragraf yang sama dengan tiga suara kandidat dan pilihlah dengan telinga Anda, bukan dari namanya: suara yang tepat bergantung pada materinya, bukan labelnya.", "tut_h1": "Tutorial", "tut_sub": "Panduan singkat dan praktis untuk memaksimalkan Text 2 Speech."}, "it": {"auth_alert_create": "Gli account arriveranno con il lancio pubblico. Non serve registrarsi per convertire il testo.", "auth_alert_forgot": "Il recupero della password arriverà insieme agli account al lancio pubblico.", "auth_alert_signin": "Gli account arriveranno con il lancio pubblico. Tutto su Text 2 Speech funziona già senza accesso.", "auth_create": "Crea un account", "auth_email": "Email", "auth_forgot": "Password dimenticata?", "auth_h1": "Bentornato", "auth_newq": "Nuovo qui?", "auth_pass": "Password", "auth_signin": "Accedi", "auth_sub": "Gli account sono facoltativi: il convertitore funziona completamente senza. Accedi per mantenere sincronizzati le tue voci preferite e la cronologia (in arrivo con il lancio pubblico).", "doc_auth": "Account — Text 2 Speech", "doc_donate": "Dona — Mantieni Text 2 Speech gratuito per tutti | Text 2 Speech", "doc_privacy": "Informativa sulla privacy — Text 2 Speech", "doc_support": "Supporto e FAQ — Aiuto per la sintesi vocale di Text 2 Speech", "doc_terms": "Termini di servizio — Text 2 Speech", "doc_tutorial": "Tutorial di sintesi vocale — Come creare voiceover | Text 2 Speech", "don_alert": "Il pagamento delle donazioni sarà attivo con il lancio pubblico. Grazie per l'offerta!", "don_alipay": "Alipay", "don_amount": "Importo", "don_btn": "Dona ora", "don_crypto": "Criptovalute", "don_crypto_sub": "USDT · ETH · BTC e altro", "don_h1": "Dona", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech è gratuito per tutti. Se ti fa risparmiare tempo, un piccolo contributo aiuta a mantenerlo tale.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Dove vanno le donazioni", "don_where_p": "Costi dei server · Sviluppo di nuove funzioni · Manutenzione del servizio", "foot_privacy": "Informativa sulla privacy", "foot_terms": "Termini di servizio", "nav_donate": "Dona", "nav_home": "Home", "nav_support": "Supporto", "nav_tutorial": "Tutorial", "priv_h1": "Informativa sulla privacy", "priv_intro": "Text 2 Speech è progettato per richiedere il minor numero possibile dei tuoi dati. Puoi usare il convertitore senza un account e senza fornirci nome o email.", "priv_s1h": "Il testo che converti", "priv_s1p": "Il testo che invii viene trasmesso al motore vocale solo per produrre il tuo audio. I file generati sono archiviati con un identificatore di sessione casuale e vengono eliminati automaticamente dopo poco tempo; non vengono mai pubblicati, indicizzati né usati per addestrare modelli.", "priv_s2h": "Cookie e analisi", "priv_s2p": "Se accetti il banner dei cookie, usiamo cookie di analisi rispettosi della privacy per contare le visite e capire quali funzioni sono più popolari. Rifiutarli non cambia in alcun modo il funzionamento dello strumento.", "priv_s3h": "Cosa non facciamo mai", "priv_s3p": "Non vendiamo dati personali, non creiamo profili pubblicitari e non conserviamo l'audio che generi dopo la fine della tua sessione.", "priv_s4h": "Contatto", "priv_s4p": "Domande sulla privacy: contattaci tramite la <a href=\"/support.html\">pagina di supporto</a>.", "priv_updated": "Ultimo aggiornamento: ottobre 2026", "sup_alert": "Grazie — la casella di supporto sarà attiva con il lancio pubblico. Per ora, le FAQ coprono i casi più comuni.", "sup_contact_h": "Contatto", "sup_email": "La tua email", "sup_h1": "Supporto", "sup_msg": "Messaggio", "sup_msg_ph": "Descrivi cosa è successo, quale voce hai usato e cosa ti aspettavi...", "sup_notice": "Il modulo di contatto aprirà con il lancio pubblico. Fino ad allora, le FAQ della home page rispondono alle domande più comuni.", "sup_o1": "Problema di generazione", "sup_o2": "Richiesta di una voce", "sup_o3": "Segnalazione di bug", "sup_o4": "Business / licenze", "sup_o5": "Altro", "sup_quick_h": "Soluzioni rapide", "sup_quick_p": "• Nessun suono nell'anteprima: controlla che la scheda del browser non sia silenziata e prova un'altra voce.<br>• Una voce suona male per il tuo testo: prima abbina la lingua della voce alla lingua del testo.<br>• Un testo lungo è lento: dividilo in capitoli e genera a parti.<br>• Un risultato è scomparso: i risultati restano solo per la sessione corrente del browser — scaricali subito.", "sup_send": "Invia messaggio", "sup_sub": "La maggior parte delle risposte si trova nelle FAQ della pagina principale. Ancora bloccato? Inviaci i dettagli.", "sup_topic": "Argomento", "terms_h1": "Termini di servizio", "terms_s1h": "Il servizio", "terms_s1p": "Text 2 Speech converte il testo che fornisci in voce sintetizzata e ti consente di riprodurre e scaricare il risultato, insieme ai file dei sottotitoli. Il servizio è fornito così com'è, senza garanzie di disponibilità ininterrotta.", "terms_s2h": "Le tue responsabilità", "terms_s2p": "Converti solo testo che hai il diritto di utilizzare. Non usare l'audio generato per impersonare persone reali, ingannare gli ascoltatori o violare le leggi applicabili. Sei responsabile di come pubblichi e concedi in licenza ciò che crei.", "terms_s3h": "Uso accettabile", "terms_s3p": "L'uso personale, educativo e creativo è benvenuto. L'uso commerciale dell'audio generato è una tua responsabilità: verificalo rispetto ai diritti sul tuo testo di partenza e alle eventuali norme sulle licenze vocali vigenti nella tua giurisdizione.", "terms_s4h": "Modifiche", "terms_s4p": "Le funzioni e questi termini possono evolvere; le modifiche rilevanti saranno annotate in questa pagina con una nuova data.", "terms_updated": "Ultimo aggiornamento: ottobre 2026", "tut_g1h": "Per iniziare: la tua prima voce generata", "tut_g1p": "Parti dal selettore della lingua: determina quali voci vedrai. Scegli la lingua in cui è scritto il tuo testo, poi prova due o tre voci con il pulsante Anteprima; le voci differiscono molto per calore e ritmo. Digita prima un breve paragrafo, generalo e ascoltalo. Quando la voce ti sembra giusta, attiva Velocità o Tono e regolali a piccoli passi: +10% di velocità si adatta ai contenuti energici, un tono leggermente più basso spesso suona più autorevole. Per qualsiasi testo più lungo di una pagina, genera sezione per sezione e mantieni la stessa voce e le stesse impostazioni, così le parti si fondono bene.", "tut_g2h": "Come usare la funzione di pausa", "tut_g2p": "I marcatori di pausa inseriscono un silenzio esatto nell'audio generato. Digita <b>[break:200ms]</b> per una breve pausa, <b>[break:1s]</b> o <b>[break:2s]</b> per pause più lunghe: rivelazioni drammatiche, elenchi e cambi di scena funzionano meglio con un po' d'aria intorno. Premendo <b>Ctrl+B</b> inserisci un marcatore [break:500ms] alla posizione del cursore. I marcatori non compaiono mai nell'audio né nei sottotitoli; senti solo la pausa. Una buona regola pratica: 300–600ms tra frasi che cambiano argomento, 1–2 secondi tra le scene. Nota che la modalità Anteprima salta semplicemente i marcatori, quindi valuta i tempi finali sul file generato.", "tut_g3h": "Un giro nella collezione di voci", "tut_g3p": "Il catalogo di Text 2 Speech contiene oltre 300 voci neurali in 75 lingue, e ogni lingua offre diverse personalità: neutra da telegiornale, calda e colloquiale, vivace e giovanile. I nomi indicano la loro regione (Aria - US, Natasha - AU), e alcune voci sono multilingue e gestiscono con naturalezza testi in più lingue. Il filtro per genere e la ricerca per nome rendono l'elenco gestibile. In caso di dubbio, genera lo stesso paragrafo con tre voci candidate e scegli con le orecchie, non in base ai nomi: la voce giusta dipende dal materiale, non dall'etichetta.", "tut_h1": "Tutorial", "tut_sub": "Guide brevi e pratiche per sfruttare al meglio Text 2 Speech."}, "ja": {"auth_alert_create": "アカウント機能は正式リリース時に提供されます。テキストの変換に登録は不要です。", "auth_alert_forgot": "パスワードのリセットは、正式リリース時のアカウント機能とともに提供されます。", "auth_alert_signin": "アカウント機能は正式リリース時に提供されます。Text 2 Speech のすべての機能は、サインアウトした状態でもすでに使えます。", "auth_create": "アカウントを作成", "auth_email": "メールアドレス", "auth_forgot": "パスワードをお忘れですか？", "auth_h1": "おかえりなさい", "auth_newq": "初めての方はこちら", "auth_pass": "パスワード", "auth_signin": "サインイン", "auth_sub": "アカウントは任意です——コンバーターはアカウントなしでも全機能が使えます。サインインすると音声のお気に入りと履歴が同期されます（正式リリースとともに提供）。", "doc_auth": "アカウント — Text 2 Speech", "doc_donate": "寄付 — Text 2 Speech をみんなに無料で届け続けるために | Text 2 Speech", "doc_privacy": "プライバシーポリシー — Text 2 Speech", "doc_support": "サポートとよくある質問 — Text 2 Speech テキスト読み上げヘルプ", "doc_terms": "利用規約 — Text 2 Speech", "doc_tutorial": "テキスト読み上げチュートリアル — ナレーションの作り方 | Text 2 Speech", "don_alert": "寄付の決済は正式リリース時に開始します。お気持ちをありがとうございます！", "don_alipay": "Alipay", "don_amount": "金額", "don_btn": "今すぐ寄付", "don_crypto": "暗号資産", "don_crypto_sub": "USDT · ETH · BTC など", "don_h1": "寄付", "don_paypal": "PayPal（USD）", "don_sub": "Text 2 Speech は誰でも無料で使えます。時間を節約できたと感じたら、小さなご支援がその無料を支えます。", "don_wechat": "WeChat Pay（CNY）", "don_where_h": "寄付金の使い道", "don_where_p": "サーバー費用 · 機能開発 · サービス保守", "foot_privacy": "プライバシーポリシー", "foot_terms": "利用規約", "nav_donate": "寄付", "nav_home": "ホーム", "nav_support": "サポート", "nav_tutorial": "チュートリアル", "priv_h1": "プライバシーポリシー", "priv_intro": "Text 2 Speech は、あなたのデータをできる限り必要としないよう設計されています。アカウントなしで、名前やメールアドレスを提供することなくコンバーターを利用できます。", "priv_s1h": "変換するテキスト", "priv_s1p": "送信されたテキストは、音声を生成するためだけに音声エンジンへ送られます。生成されたファイルはランダムなセッション識別子に紐づけて保存され、短時間の後に自動的に削除されます。公開、インデックス化、モデルの学習に使われることは決してありません。", "priv_s2h": "Cookie とアナリティクス", "priv_s2p": "Cookie バナーに同意すると、プライバシーに配慮したアナリティクス Cookie を使用して訪問数を数え、人気のある機能を把握します。拒否してもツールの動作は一切変わりません。", "priv_s3h": "私たちが決してしないこと", "priv_s3p": "個人データを販売することはありません。広告プロファイルを作成することはありません。セッション終了後に生成された音声を保持することもありません。", "priv_s4h": "お問い合わせ", "priv_s4p": "プライバシーに関するご質問は、<a href=\"/support.html\">サポートページ</a>からご連絡ください。", "priv_updated": "最終更新：2026年10月", "sup_alert": "ありがとうございます——サポート受信箱は正式リリース時に開設します。当面は、よくある質問で一般的なケースをカバーしています。", "sup_contact_h": "お問い合わせ", "sup_email": "メールアドレス", "sup_h1": "サポート", "sup_msg": "メッセージ", "sup_msg_ph": "何が起きたか、どの音声を使ったか、何を期待していたかを説明してください...", "sup_notice": "お問い合わせフォームは正式公開時に利用可能になります。それまでは、ホームページのFAQでよくある質問をご確認ください。", "sup_o1": "生成の問題", "sup_o2": "音声のリクエスト", "sup_o3": "バグ報告", "sup_o4": "ビジネス / ライセンス", "sup_o5": "その他", "sup_quick_h": "クイック対処法", "sup_quick_p": "• プレビューで音が出ない：ブラウザのタブがミュートになっていないか確認し、別の音声を試してください。<br>• 音声がテキストに合わない：まず音声言語をテキストの言語に合わせてください。<br>• 長いテキストの生成が遅い：章ごとに分割して部分的に生成してください。<br>• 結果が消えた：結果は現在のブラウザセッションの間だけ保持されます——早めにダウンロードしてください。", "sup_send": "メッセージを送信", "sup_sub": "ほとんどの答えはホームページのよくある質問にあります。それでも解決しない場合は、詳細をお送りください。", "sup_topic": "件名", "terms_h1": "利用規約", "terms_s1h": "本サービス", "terms_s1p": "Text 2 Speech は、提供されたテキストを合成音声に変換し、結果と字幕ファイルを再生・ダウンロードできるようにします。本サービスは現状のまま提供され、中断のない利用可能性は保証されません。", "terms_s2h": "あなたの責任", "terms_s2p": "使用する権利のあるテキストのみを変換してください。生成された音声を実在の人物のなりすまし、聞き手の欺瞞、または適用法令の違反に使用しないでください。作成したものをどのように公開しライセンスするかは、あなたの責任です。", "terms_s3h": "許容される利用", "terms_s3p": "個人的、教育的、創作的な利用は歓迎します。生成された音声の商用利用については、元のテキストの権利およびお住まいの地域で適用される音声ライセンス規則に対して問題がないことを確認する責任があなたにあります。", "terms_s4h": "変更", "terms_s4p": "機能および本規約は進化する可能性があります。重要な変更は、新しい日付とともにこのページに記載されます。", "terms_updated": "最終更新：2026年10月", "tut_g1h": "はじめに：最初の音声を生成する", "tut_g1p": "まずは言語セレクターから始めましょう。表示される音声はここで決まります。テキストが書かれている言語を選び、プレビューボタンで2〜3種類の音声を試してみてください。音声によって温かみやテンポは大きく異なります。まず短い段落を入力して生成し、聴いてみましょう。音声の雰囲気が合ってきたら、速度やピッチをオンにして少しずつ調整します。速度 +10% は活気のあるコンテンツに適し、ピッチを少し下げると権威のある響きになりがちです。1ページを超える長さの場合は、セクションごとに生成し、同じ音声と設定を保つことで各部分が自然につながります。", "tut_g2h": "ブレイク機能の使い方", "tut_g2p": "ブレイクマーカーは、生成された音声に正確な無音を挿入します。短い間には <b>[break:200ms]</b>、長めの間には <b>[break:1s]</b> や <b>[break:2s]</b> と入力してください。ドラマチックな展開、リストの項目、場面転換は、周りに間があるとより効果的になります。<b>Ctrl+B</b> を押すと、カーソル位置に [break:500ms] マーカーが挿入されます。マーカーは音声や字幕には現れません。聞こえるのは間のみです。目安として、話題が変わる文の間は 300–600ms、場面の間は1〜2秒がおすすめです。なお、プレビューモードではマーカーは単にスキップされるため、最終的なタイミングは生成されたファイルで判断してください。", "tut_g3h": "音声コレクションのツアー", "tut_g3p": "Text 2 Speech のカタログには、75言語にわたる 300+ のニューラル音声が収録されており、各言語にはニュース読みのような落ち着いた声、温かく会話的な声、明るく若々しい声など、複数の個性があります。名前には地域が含まれており（Aria - US、Natasha - AU）、一部の音声は多言語対応で、言語が混在したテキストも自然に処理します。性別フィルタと名前検索でリストを扱いやすくできます。迷ったときは、同じ段落を3つの候補音声で生成し、名前ではなく耳で選びましょう。合う音声はラベルではなく素材で決まります。", "tut_h1": "チュートリアル", "tut_sub": "Text 2 Speech を最大限に活用するための、短く実践的なガイドです。"}, "ko": {"auth_alert_create": "계정 기능은 정식 출시와 함께 제공됩니다. 텍스트 변환에는 가입이 필요하지 않습니다.", "auth_alert_forgot": "비밀번호 재설정은 정식 출시 시 계정 기능과 함께 제공됩니다.", "auth_alert_signin": "계정 기능은 정식 출시와 함께 제공됩니다. Text 2 Speech의 모든 기능은 로그아웃 상태에서도 이미 사용할 수 있습니다.", "auth_create": "계정 만들기", "auth_email": "이메일", "auth_forgot": "비밀번호를 잊으셨나요?", "auth_h1": "다시 오신 것을 환영합니다", "auth_newq": "처음이신가요?", "auth_pass": "비밀번호", "auth_signin": "로그인", "auth_sub": "계정은 선택 사항입니다 — 변환기는 계정 없이도 모든 기능을 사용할 수 있습니다. 로그인하면 음성 즐겨찾기와 기록이 동기화됩니다(정식 출시와 함께 제공).", "doc_auth": "계정 — Text 2 Speech", "doc_donate": "후원 — Text 2 Speech를 모두에게 무료로 유지해 주세요 | Text 2 Speech", "doc_privacy": "개인정보 처리방침 — Text 2 Speech", "doc_support": "지원 및 FAQ — Text 2 Speech 텍스트 음성 변환 도움말", "doc_terms": "서비스 약관 — Text 2 Speech", "doc_tutorial": "텍스트 음성 변환 튜토리얼 — 보이스오버 만드는 법 | Text 2 Speech", "don_alert": "후원 결제는 정식 출시와 함께 열립니다. 마음을 전해 주셔서 감사합니다!", "don_alipay": "Alipay", "don_amount": "금액", "don_btn": "지금 후원하기", "don_crypto": "암호화폐", "don_crypto_sub": "USDT · ETH · BTC 등", "don_h1": "후원", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech는 모두에게 무료입니다. 시간을 절약해 드렸다면, 작은 후원이 그 무료를 이어 갑니다.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "후원금 사용처", "don_where_p": "서버 비용 · 기능 개발 · 서비스 유지보수", "foot_privacy": "개인정보 처리방침", "foot_terms": "서비스 약관", "nav_donate": "후원", "nav_home": "홈", "nav_support": "지원", "nav_tutorial": "튜토리얼", "priv_h1": "개인정보 처리방침", "priv_intro": "Text 2 Speech는 여러분의 데이터를 가능한 한 적게 필요로 하도록 설계되었습니다. 계정 없이, 이름이나 이메일을 제공하지 않고도 변환기를 사용할 수 있습니다.", "priv_s1h": "변환하는 텍스트", "priv_s1p": "제출한 텍스트는 오디오를 만들기 위해서만 음성 엔진으로 전송됩니다. 생성된 파일은 임의의 세션 식별자에 연결되어 저장되며 짧은 기간이 지나면 자동으로 삭제됩니다. 절대로 게시되거나, 색인되거나, 모델 학습에 사용되지 않습니다.", "priv_s2h": "쿠키 및 분석", "priv_s2p": "쿠키 배너에 동의하면 개인정보를 존중하는 분석 쿠키를 사용해 방문 수를 세고 어떤 기능이 인기 있는지 파악합니다. 거부해도 도구의 작동 방식은 전혀 달라지지 않습니다.", "priv_s3h": "우리가 절대 하지 않는 것", "priv_s3p": "개인 데이터를 판매하지 않고, 광고 프로필을 만들지 않으며, 세션이 끝난 뒤에도 생성된 오디오를 보관하지 않습니다.", "priv_s4h": "문의", "priv_s4p": "개인정보 관련 문의: <a href=\"/support.html\">지원 페이지</a>를 통해 연락해 주세요.", "priv_updated": "최종 업데이트: 2026년 10월", "sup_alert": "감사합니다 — 지원 받은편지함은 정식 출시와 함께 열립니다. 그전까지는 FAQ에서 일반적인 경우를 다룹니다.", "sup_contact_h": "문의", "sup_email": "이메일", "sup_h1": "지원", "sup_msg": "메시지", "sup_msg_ph": "무슨 일이 있었는지, 어떤 음성을 사용했는지, 무엇을 기대했는지 설명해 주세요...", "sup_notice": "문의 양식은 정식 출시와 함께 열립니다. 그때까지는 홈페이지의 FAQ에서 자주 묻는 질문을 확인하세요.", "sup_o1": "생성 문제", "sup_o2": "음성 요청", "sup_o3": "버그 신고", "sup_o4": "비즈니스 / 라이선스", "sup_o5": "기타", "sup_quick_h": "빠른 해결법", "sup_quick_p": "• 미리 듣기에서 소리가 나지 않음: 브라우저 탭이 음소거되어 있지 않은지 확인하고 다른 음성을 시도해 보세요.<br>• 음성이 텍스트와 어울리지 않게 들림: 먼저 음성 언어를 텍스트 언어와 맞춰 보세요.<br>• 긴 텍스트가 느림: 장별로 나누어 부분적으로 생성하세요.<br>• 결과가 사라짐: 결과는 현재 브라우저 세션 동안만 유지됩니다 — 바로 다운로드하세요.", "sup_send": "메시지 보내기", "sup_sub": "대부분의 답은 홈페이지의 FAQ에 있습니다. 그래도 해결되지 않나요? 자세한 내용을 보내 주세요.", "sup_topic": "주제", "terms_h1": "서비스 약관", "terms_s1h": "서비스", "terms_s1p": "Text 2 Speech는 여러분이 제공한 텍스트를 합성 음성으로 변환하고, 결과물과 자막 파일을 재생하고 다운로드할 수 있게 합니다. 서비스는 있는 그대로 제공되며, 중단 없는 이용 가능성을 보장하지 않습니다.", "terms_s2h": "여러분의 책임", "terms_s2p": "사용할 권리가 있는 텍스트만 변환하세요. 생성된 오디오를 실제 인물을 사칭하거나, 청취자를 속이거나, 관련 법률을 위반하는 데 사용하지 마세요. 만든 결과물을 어떻게 게시하고 라이선스를 부여할지는 여러분의 책임입니다.", "terms_s3h": "허용되는 사용", "terms_s3p": "개인적, 교육적, 창작적 사용은 환영합니다. 생성된 오디오의 상업적 사용은 원본 텍스트의 권리와 관할 지역에서 적용되는 음성 라이선스 규칙에 대해 문제가 없는지 직접 확인할 책임이 있습니다.", "terms_s4h": "변경", "terms_s4p": "기능과 본 약관은 변경될 수 있으며, 중요한 변경 사항은 새 날짜와 함께 이 페이지에 표시됩니다.", "terms_updated": "최종 업데이트: 2026년 10월", "tut_g1h": "시작하기: 첫 음성 생성하기", "tut_g1p": "언어 선택기부터 시작하세요 — 어떤 음성이 표시될지가 여기서 결정됩니다. 텍스트가 작성된 언어를 선택한 다음, 미리 듣기 버튼으로 두세 가지 음성을 들어 보세요. 음성마다 따뜻함과 속도감이 크게 다릅니다. 먼저 짧은 단락을 입력해 생성하고 들어 보세요. 음성이 마음에 들면 속도와 피치를 켜고 조금씩 조정하세요. 속도 +10%는 활기찬 콘텐츠에 잘 어울리고, 피치를 살짝 낮추면 보통 더 권위 있게 들립니다. 한 페이지가 넘는 분량이라면 섹션별로 생성하고 같은 음성과 설정을 유지해야 각 부분이 자연스럽게 어우러집니다.", "tut_g2h": "쉼표 기능 사용법", "tut_g2p": "쉼표 마커는 생성된 오디오에 정확한 무음을 삽입합니다. 짧은 쉼에는 <b>[break:200ms]</b>, 더 긴 쉼에는 <b>[break:1s]</b> 또는 <b>[break:2s]</b>를 입력하세요 — 극적인 반전, 목록 항목, 장면 전환은 모두 주변에 여백이 있을 때 더 잘 전달됩니다. <b>Ctrl+B</b>를 누르면 커서 위치에 [break:500ms] 마커가 삽입됩니다. 마커는 오디오나 자막에 나타나지 않으며, 들리는 것은 쉼뿐입니다. 유용한 기준: 주제가 바뀌는 문장 사이는 300–600ms, 장면 사이는 1–2초입니다. 미리 듣기 모드에서는 마커가 그냥 건너뛰어지므로, 최종 타이밍은 생성된 파일로 판단하세요.", "tut_g3h": "음성 컬렉션 둘러보기", "tut_g3p": "Text 2 Speech 카탈로그에는 75개 언어에 걸쳐 300+개의 신경망 음성이 수록되어 있으며, 각 언어마다 뉴스 진행자처럼 차분한 음성, 따뜻하고 대화체 같은 음성, 밝고 젊은 음성 등 여러 개성을 제공합니다. 이름에는 지역이 표시되고(Aria - US, Natasha - AU), 일부 음성은 다국어를 지원해 언어가 섞인 텍스트도 자연스럽게 처리합니다. 성별 필터와 이름 검색으로 목록을 쉽게 관리할 수 있습니다. 고민될 때는 같은 단락을 후보 음성 세 가지로 생성해 이름이 아닌 귀로 고르세요. 어울리는 음성은 라벨이 아니라 콘텐츠에 따라 결정됩니다.", "tut_h1": "튜토리얼", "tut_sub": "Text 2 Speech를 최대한 활용할 수 있는 짧고 실용적인 가이드입니다."}, "nl": {"auth_alert_create": "Accounts komen beschikbaar bij de openbare lancering. Aanmelden is niet nodig om tekst om te zetten.", "auth_alert_forgot": "Wachtwoordherstel komt samen met accounts bij de openbare lancering.", "auth_alert_signin": "Accounts komen beschikbaar bij de openbare lancering. Alles op Text 2 Speech werkt nu al zonder in te loggen.", "auth_create": "Account aanmaken", "auth_email": "E-mailadres", "auth_forgot": "Wachtwoord vergeten?", "auth_h1": "Welkom terug", "auth_newq": "Nieuw hier?", "auth_pass": "Wachtwoord", "auth_signin": "Inloggen", "auth_sub": "Accounts zijn optioneel — de converter werkt volledig zonder account. Log in om je stemfavorieten en geschiedenis gesynchroniseerd te houden (wordt uitgerold bij de openbare lancering).", "doc_auth": "Account — Text 2 Speech", "doc_donate": "Doneren — Houd Text 2 Speech gratis voor iedereen | Text 2 Speech", "doc_privacy": "Privacybeleid — Text 2 Speech", "doc_support": "Ondersteuning & FAQ — Hulp bij Text 2 Speech Tekst naar spraak", "doc_terms": "Algemene voorwaarden — Text 2 Speech", "doc_tutorial": "Tekst-naar-spraak handleiding — Zo maak je voice-overs | Text 2 Speech", "don_alert": "Het afrekenen van donaties opent bij de openbare lancering. Bedankt voor je aanbod!", "don_alipay": "Alipay", "don_amount": "Bedrag", "don_btn": "Doneer nu", "don_crypto": "Cryptovaluta", "don_crypto_sub": "USDT · ETH · BTC en meer", "don_h1": "Doneren", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech is gratis voor iedereen. Als het je tijd bespaart, helpt een kleine bijdrage om dat zo te houden.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Waar donaties naartoe gaan", "don_where_p": "Serverkosten · Ontwikkeling van functies · Onderhoud van de dienst", "foot_privacy": "Privacybeleid", "foot_terms": "Algemene voorwaarden", "nav_donate": "Doneren", "nav_home": "Home", "nav_support": "Ondersteuning", "nav_tutorial": "Handleiding", "priv_h1": "Privacybeleid", "priv_intro": "Text 2 Speech is ontworpen om zo min mogelijk van je gegevens nodig te hebben. Je kunt de converter gebruiken zonder account en zonder ons je naam of e-mailadres te geven.", "priv_s1h": "Tekst die je omzet", "priv_s1p": "Tekst die je indient, wordt alleen naar de spraakengine gestuurd om je audio te produceren. Gegenereerde bestanden worden opgeslagen onder een willekeurige sessie-id en na korte tijd automatisch verwijderd; ze worden nooit gepubliceerd, geïndexeerd of gebruikt om modellen te trainen.", "priv_s2h": "Cookies en analyse", "priv_s2p": "Als je de cookiebanner accepteert, gebruiken we privacyvriendelijke analysecookies om bezoeken te tellen en te zien welke functies populair zijn. Weigeren verandert niets aan hoe de tool werkt.", "priv_s3h": "Wat we nooit doen", "priv_s3p": "We verkopen geen persoonsgegevens, we bouwen geen advertentieprofielen op en we bewaren je gegenereerde audio niet nadat je sessie is beëindigd.", "priv_s4h": "Contact", "priv_s4p": "Vragen over privacy: bereik ons via de <a href=\"/support.html\">ondersteuningspagina</a>.", "priv_updated": "Laatst bijgewerkt: oktober 2026", "sup_alert": "Bedankt — de supportinbox opent bij de openbare lancering. Voorlopig behandelt de FAQ de meest voorkomende gevallen.", "sup_contact_h": "Contact", "sup_email": "Je e-mailadres", "sup_h1": "Ondersteuning", "sup_msg": "Bericht", "sup_msg_ph": "Beschrijf wat er gebeurde, welke stem je gebruikte en wat je verwachtte...", "sup_notice": "Het contactformulier gaat open bij de publieke lancering. Tot die tijd beantwoordt de FAQ op de startpagina de meest gestelde vragen.", "sup_o1": "Probleem met genereren", "sup_o2": "Stem aanvragen", "sup_o3": "Bugrapport", "sup_o4": "Zakelijk / licenties", "sup_o5": "Anders", "sup_quick_h": "Snelle oplossingen", "sup_quick_p": "• Geen geluid bij Voorbeeld: controleer of het browsertabblad niet gedempt is en probeer een andere stem.<br>• Een stem klinkt verkeerd bij je tekst: stem eerst de Stemtaal af op de taal van de tekst.<br>• Lange tekst is traag: splits hem in hoofdstukken en genereer in delen.<br>• Een resultaat is verdwenen: resultaten bestaan alleen tijdens de huidige browsersessie — download ze meteen.", "sup_send": "Bericht verzenden", "sup_sub": "De meeste antwoorden staan in de FAQ op de homepagina. Kom je er toch niet uit? Stuur ons de details.", "sup_topic": "Onderwerp", "terms_h1": "Algemene voorwaarden", "terms_s1h": "De dienst", "terms_s1p": "Text 2 Speech zet tekst die je aanlevert om in gesynthetiseerde spraak en laat je het resultaat afspelen en downloaden, samen met ondertitelbestanden. De dienst wordt geleverd zoals hij is, zonder garanties voor ononderbroken beschikbaarheid.", "terms_s2h": "Jouw verantwoordelijkheden", "terms_s2p": "Zet alleen tekst om die je mag gebruiken. Gebruik gegenereerde audio niet om echte personen te imiteren, luisteraars te misleiden of toepasselijke wetten te overtreden. Je bent zelf verantwoordelijk voor hoe je publiceert en licentieert wat je maakt.", "terms_s3h": "Aanvaardbaar gebruik", "terms_s3p": "Persoonlijk, educatief en creatief gebruik is welkom. Commercieel gebruik van gegenereerde audio is je eigen verantwoordelijkheid om af te stemmen op de rechten in je brontekst en eventuele toepasselijke regels voor stemlicenties in jouw rechtsgebied.", "terms_s4h": "Wijzigingen", "terms_s4p": "Functies en deze voorwaarden kunnen evolueren; belangrijke wijzigingen worden op deze pagina vermeld met een nieuwe datum.", "terms_updated": "Laatst bijgewerkt: oktober 2026", "tut_g1h": "Aan de slag: je eerste gegenereerde stem", "tut_g1p": "Begin met de taalkiezer — die bepaalt welke stemmen je ziet. Kies de taal waarin je tekst is geschreven en probeer daarna twee of drie stemmen met de knop Voorbeeld; stemmen verschillen sterk in warmte en tempo. Typ eerst een korte alinea, genereer die en luister. Voelt de stem goed, zet dan Snelheid of Toonhoogte aan en pas ze in kleine stapjes aan: +10% snelheid past bij energieke content, een iets lagere toonhoogte klinkt vaak gezaghebbender. Genereer bij alles wat langer is dan een pagina sectie voor sectie en behoud dezelfde stem en instellingen, zodat de delen mooi in elkaar overlopen.", "tut_g2h": "Zo gebruik je de pauzefunctie", "tut_g2p": "Pauzemarkeringen voegen exacte stilte in de gegenereerde audio in. Typ <b>[break:200ms]</b> voor een korte adempauze, <b>[break:1s]</b> of <b>[break:2s]</b> voor langere pauzes — dramatische onthullingen, lijstitems en scènewisselingen komen allemaal beter tot hun recht met lucht eromheen. Met <b>Ctrl+B</b> plaats je een [break:500ms]-markering bij je cursor. Markeringen verschijnen nooit in de audio of de ondertiteling; je hoort alleen de pauze. Een goede vuistregel: 300–600 ms tussen zinnen die van onderwerp veranderen, 1–2 seconden tussen scènes. Let op: de voorbeeldmodus slaat de markeringen gewoon over, dus beoordeel de uiteindelijke timing op het gegenereerde bestand.", "tut_g3h": "Een rondleiding door de stemmencollectie", "tut_g3p": "De catalogus van Text 2 Speech bevat 300+ neurale stemmen in 75 talen, en elke taal biedt meerdere persoonlijkheden — vlak als een nieuwslezer, warm en gemoedelijk, helder en jeugdig. Namen vermelden hun regio (Aria - US, Natasha - AU), en een paar stemmen zijn meertalig en gaan soepel om met tekst in gemengde talen. Met genderfilter en zoeken op naam blijft de lijst overzichtelijk. Twijfel je, genereer dan dezelfde alinea met drie kandidaat-stemmen en kies met je oren, niet op basis van de namen: de juiste stem hangt af van het materiaal, niet van het label.", "tut_h1": "Handleiding", "tut_sub": "Korte, praktische gidsen om het maximale uit Text 2 Speech te halen."}, "no": {"auth_alert_create": "Kontoer kommer ved den offentlige lanseringen. Registrering er ikke nødvendig for å konvertere tekst.", "auth_alert_forgot": "Tilbakestilling av passord kommer sammen med kontoer ved den offentlige lanseringen.", "auth_alert_signin": "Kontoer kommer ved den offentlige lanseringen. Alt på Text 2 Speech fungerer allerede i utlogget tilstand.", "auth_create": "Opprett en konto", "auth_email": "E-post", "auth_forgot": "Glemt passord?", "auth_h1": "Velkommen tilbake", "auth_newq": "Ny her?", "auth_pass": "Passord", "auth_signin": "Logg inn", "auth_sub": "Kontoer er valgfrie — omformeren fungerer fullt ut uten en konto. Logg inn for å holde stemmefavorittene og historikken din synkronisert (rulles ut ved den offentlige lanseringen).", "doc_auth": "Konto — Text 2 Speech", "doc_donate": "Doner — Hold Text 2 Speech gratis for alle | Text 2 Speech", "doc_privacy": "Personvernerklæring — Text 2 Speech", "doc_support": "Kundestøtte og FAQ — Hjelp til Text 2 Speech Tekst til tale", "doc_terms": "Vilkår for bruk — Text 2 Speech", "doc_tutorial": "Tekst til tale-veiledning — Slik lager du voiceover | Text 2 Speech", "don_alert": "Betaling av donasjoner åpner ved den offentlige lanseringen. Tusen takk for tilbudet!", "don_alipay": "Alipay", "don_amount": "Beløp", "don_btn": "Doner nå", "don_crypto": "Kryptovaluta", "don_crypto_sub": "USDT · ETH · BTC og mer", "don_h1": "Doner", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech er gratis for alle. Hvis det sparer deg tid, bidrar en liten gave til å holde det slik.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Hva donasjoner går til", "don_where_p": "Serverkostnader · Funksjonsutvikling · Vedlikehold av tjenesten", "foot_privacy": "Personvernerklæring", "foot_terms": "Vilkår for bruk", "nav_donate": "Doner", "nav_home": "Hjem", "nav_support": "Kundestøtte", "nav_tutorial": "Veiledning", "priv_h1": "Personvernerklæring", "priv_intro": "Text 2 Speech er utformet for å trenge så lite av dataene dine som mulig. Du kan bruke omformeren uten konto og uten å gi oss navn eller e-post.", "priv_s1h": "Tekst du konverterer", "priv_s1p": "Tekst du sender inn, sendes bare til talemotoren for å produsere lyden din. Genererte filer lagres under en tilfeldig øktidentifikator og slettes automatisk etter kort tid; de blir aldri publisert, indeksert eller brukt til å trene modeller.", "priv_s2h": "Informasjonskapsler og analyse", "priv_s2p": "Hvis du godtar informasjonskapselbanneret, bruker vi personvernvennlige analyse-informasjonskapsler til å telle besøk og se hvilke funksjoner som er populære. Å avslå endrer ingenting ved hvordan verktøyet fungerer.", "priv_s3h": "Det vi aldri gjør", "priv_s3p": "Vi selger ikke personopplysninger, vi bygger ikke reklameprofiler, og vi beholder ikke den genererte lyden din etter at økten er over.", "priv_s4h": "Kontakt", "priv_s4p": "Spørsmål om personvern: nå oss via <a href=\"/support.html\">kundestøttesiden</a>.", "priv_updated": "Sist oppdatert: oktober 2026", "sup_alert": "Takk — støtteinnboksen åpner ved den offentlige lanseringen. Inntil videre dekker FAQ-en de vanligste tilfellene.", "sup_contact_h": "Kontakt", "sup_email": "E-postadressen din", "sup_h1": "Kundestøtte", "sup_msg": "Melding", "sup_msg_ph": "Beskriv hva som skjedde, hvilken stemme du brukte og hva du forventet...", "sup_notice": "Kontaktskjemaet åpner ved den offentlige lanseringen. Inntil da dekker FAQ-en på forsiden de vanligste spørsmålene.", "sup_o1": "Problem med generering", "sup_o2": "Ønske om stemme", "sup_o3": "Feilrapport", "sup_o4": "Forretning / lisensiering", "sup_o5": "Annet", "sup_quick_h": "Raske løsninger", "sup_quick_p": "• Ingen lyd ved Forhåndsvis: sjekk at nettleserfanen ikke er dempet, og prøv en annen stemme.<br>• En stemme høres feil ut for teksten din: match først Stemmespråk med tekstspråket.<br>• Lang tekst går tregt: del den opp i kapitler og generer i deler.<br>• Et resultat forsvant: resultater finnes bare i den gjeldende nettleserøkten — last ned med en gang.", "sup_send": "Send melding", "sup_sub": "De fleste svar finner du i FAQ-en på forsiden. Sitter du fortsatt fast? Send oss detaljene.", "sup_topic": "Emne", "terms_h1": "Vilkår for bruk", "terms_s1h": "Tjenesten", "terms_s1p": "Text 2 Speech konverterer tekst du oppgir, til syntetisert tale og lar deg spille av og laste ned resultatet sammen med undertekstfiler. Tjenesten leveres som den er, uten garantier for uavbrutt tilgjengelighet.", "terms_s2h": "Ditt ansvar", "terms_s2p": "Konverter bare tekst du har rett til å bruke. Ikke bruk generert lyd til å etterligne virkelige personer, villede lyttere eller bryte gjeldende lover. Du er ansvarlig for hvordan du publiserer og lisensierer det du skaper.", "terms_s3h": "Akseptabel bruk", "terms_s3p": "Personlig, pedagogisk og kreativ bruk er velkommen. Kommersiell bruk av generert lyd er ditt ansvar å avklare mot rettighetene i kildeteksten din og eventuelle gjeldende regler for stemmelisensiering i din jurisdiksjon.", "terms_s4h": "Endringer", "terms_s4p": "Funksjoner og disse vilkårene kan endre seg; vesentlige endringer vil bli notert på denne siden med en ny dato.", "terms_updated": "Sist oppdatert: oktober 2026", "tut_g1h": "Kom i gang: din første genererte stemme", "tut_g1p": "Start med språkvelgeren — den bestemmer hvilke stemmer du ser. Velg språket teksten din er skrevet på, og prøv deretter to eller tre stemmer med Forhåndsvis-knappen; stemmer varierer mye i varme og tempo. Skriv først et kort avsnitt, generer det og lytt. Når stemmen føles riktig, slår du på Hastighet eller Tonehøyde og justerer i små trinn: +10 % hastighet passer til energisk innhold, mens en litt lavere tonehøyde ofte høres mer autoritativ ut. For alt som er lengre enn én side, genererer du avsnitt for avsnitt og beholder samme stemme og innstillinger, slik at delene glir sammen.", "tut_g2h": "Slik bruker du pausefunksjonen", "tut_g2p": "Pausemarkører setter inn nøyaktig stillhet i den genererte lyden. Skriv <b>[break:200ms]</b> for et kort opphold, <b>[break:1s]</b> eller <b>[break:2s]</b> for lengre pauser — dramatiske avsløringer, listepunkter og sceneskifter fungerer alle bedre med luft rundt seg. Trykk på <b>Ctrl+B</b> for å sette inn en [break:500ms]-markør ved markøren. Markører vises aldri i lyden eller undertekstene; du hører bare pausen. En god tommelfingerregel: 300–600 ms mellom setninger som bytter tema, 1–2 sekunder mellom scener. Merk at Forhåndsvis-modus ganske enkelt hopper over markørene, så vurder den endelige timingen på den genererte filen.", "tut_g3h": "En omvisning i stemmesamlingen", "tut_g3p": "Katalogen til Text 2 Speech rommer 300+ nevrale stemmer på 75 språk, og hvert språk byr på flere personligheter — flat som en nyhetsoppleser, varm og samtalepreget, lys og ungdommelig. Navnene angir regionen deres (Aria - US, Natasha - AU), og noen få stemmer er flerspråklige og håndterer tekst på blandede språk uten problemer. Kjønnsfiltrering og navnesøk holder listen oversiktlig. Er du i tvil, genererer du samme avsnitt med tre kandidatstemmer og velger med ørene, ikke navnene: den rette stemmen avhenger av materialet, ikke etiketten.", "tut_h1": "Veiledning", "tut_sub": "Korte, praktiske guider som hjelper deg å få mest mulig ut av Text 2 Speech."}, "pl": {"auth_alert_create": "Konta pojawią się wraz z publiczną premierą. Do konwersji tekstu rejestracja nie jest potrzebna.", "auth_alert_forgot": "Resetowanie hasła pojawi się wraz z kontami przy publicznej premierze.", "auth_alert_signin": "Konta pojawią się wraz z publiczną premierą. Wszystko w Text 2 Speech działa już teraz bez logowania.", "auth_create": "Załóż konto", "auth_email": "Email", "auth_forgot": "Nie pamiętasz hasła?", "auth_h1": "Witaj ponownie", "auth_newq": "Jesteś tu nowy?", "auth_pass": "Hasło", "auth_signin": "Zaloguj się", "auth_sub": "Konta są opcjonalne — konwerter działa w pełni bez konta. Zaloguj się, aby synchronizować ulubione głosy i historię (funkcja pojawi się wraz z publiczną premierą).", "doc_auth": "Konto — Text 2 Speech", "doc_donate": "Wesprzyj — pomóż utrzymać Text 2 Speech za darmo dla wszystkich | Text 2 Speech", "doc_privacy": "Polityka prywatności — Text 2 Speech", "doc_support": "Pomoc i FAQ — wsparcie Text 2 Speech Text to Speech", "doc_terms": "Regulamin — Text 2 Speech", "doc_tutorial": "Poradnik zamiany tekstu na mowę — jak tworzyć narracje głosowe | Text 2 Speech", "don_alert": "Płatności za datki zostaną uruchomione wraz z publiczną premierą. Dziękujemy za chęć wsparcia!", "don_alipay": "Alipay", "don_amount": "Kwota", "don_btn": "Wesprzyj teraz", "don_crypto": "Kryptowaluty", "don_crypto_sub": "USDT · ETH · BTC i inne", "don_h1": "Wesprzyj", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech jest darmowy dla wszystkich. Jeśli oszczędza ci czas, niewielki wkład pomoże utrzymać ten stan.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Na co trafiają datki", "don_where_p": "Koszty serwera · Rozwój funkcji · Utrzymanie usługi", "foot_privacy": "Polityka prywatności", "foot_terms": "Regulamin", "nav_donate": "Wesprzyj", "nav_home": "Strona główna", "nav_support": "Pomoc", "nav_tutorial": "Poradnik", "priv_h1": "Polityka prywatności", "priv_intro": "Text 2 Speech zaprojektowano tak, aby potrzebował jak najmniej twoich danych. Możesz korzystać z konwertera bez konta i bez podawania nam imienia czy adresu email.", "priv_s1h": "Tekst, który konwertujesz", "priv_s1p": "Przesłany przez ciebie tekst jest wysyłany do silnika mowy wyłącznie w celu wygenerowania dźwięku. Wygenerowane pliki są przechowywane pod losowym identyfikatorem sesji i automatycznie usuwane po krótkim czasie; nigdy nie są publikowane, indeksowane ani wykorzystywane do trenowania modeli.", "priv_s2h": "Pliki cookie i analityka", "priv_s2p": "Jeśli zaakceptujesz baner plików cookie, używamy szanujących prywatność analitycznych plików cookie, aby liczyć wizyty i sprawdzać, które funkcje są popularne. Odrzucenie niczego nie zmienia w działaniu narzędzia.", "priv_s3h": "Czego nigdy nie robimy", "priv_s3p": "Nie sprzedajemy danych osobowych, nie budujemy profili reklamowych i nie przechowujemy wygenerowanego przez ciebie dźwięku po zakończeniu sesji.", "priv_s4h": "Kontakt", "priv_s4p": "Pytania dotyczące prywatności: skontaktuj się z nami przez <a href=\"/support.html\">stronę pomocy</a>.", "priv_updated": "Ostatnia aktualizacja: październik 2026", "sup_alert": "Dziękujemy — skrzynka pomocy zostanie uruchomiona wraz z publiczną premierą. Na razie FAQ obejmuje najczęstsze przypadki.", "sup_contact_h": "Kontakt", "sup_email": "Twój email", "sup_h1": "Pomoc", "sup_msg": "Wiadomość", "sup_msg_ph": "Opisz, co się stało, jakiego głosu używałeś i czego się spodziewałeś...", "sup_notice": "Formularz kontaktowy zostanie uruchomiony wraz z publicznym startem. Do tego czasu FAQ na stronie głównej odpowiada na najczęstsze pytania.", "sup_o1": "Problem z generowaniem", "sup_o2": "Prośba o głos", "sup_o3": "Zgłoszenie błędu", "sup_o4": "Biznes / licencje", "sup_o5": "Inne", "sup_quick_h": "Szybkie rozwiązania", "sup_quick_p": "• Brak dźwięku w podglądzie: sprawdź, czy karta przeglądarki nie jest wyciszona, i wypróbuj inny głos.<br>• Głos brzmi nieodpowiednio do twojego tekstu: najpierw dopasuj język głosu do języka tekstu.<br>• Długi tekst działa wolno: podziel go na rozdziały i generuj partiami.<br>• Wynik zniknął: wyniki istnieją tylko w bieżącej sesji przeglądarki — pobieraj je od razu.", "sup_send": "Wyślij wiadomość", "sup_sub": "Większość odpowiedzi znajdziesz w FAQ na stronie głównej. Nadal coś nie działa? Prześlij nam szczegóły.", "sup_topic": "Temat", "terms_h1": "Regulamin", "terms_s1h": "Usługa", "terms_s1p": "Text 2 Speech zamienia dostarczony przez ciebie tekst na mowę syntetyczną i pozwala odtworzyć oraz pobrać wynik wraz z plikami napisów. Usługa jest świadczona w stanie, w jakim się znajduje, bez gwarancji nieprzerwanej dostępności.", "terms_s2h": "Twoje obowiązki", "terms_s2p": "Konwertuj wyłącznie tekst, do którego masz prawo. Nie używaj wygenerowanego dźwięku do podszywania się pod prawdziwe osoby, wprowadzania słuchaczy w błąd ani łamania obowiązującego prawa. Odpowiadasz za to, jak publikujesz i licencjonujesz to, co tworzysz.", "terms_s3h": "Dozwolone użycie", "terms_s3p": "Użycie osobiste, edukacyjne i twórcze jest mile widziane. Komercyjne wykorzystanie wygenerowanego dźwięku wymaga od ciebie sprawdzenia praw do tekstu źródłowego oraz wszelkich obowiązujących zasad licencjonowania głosów w twojej jurysdykcji.", "terms_s4h": "Zmiany", "terms_s4p": "Funkcje i niniejszy regulamin mogą ewoluować; istotne zmiany zostaną odnotowane na tej stronie wraz z nową datą.", "terms_updated": "Ostatnia aktualizacja: październik 2026", "tut_g1h": "Pierwsze kroki: twój pierwszy wygenerowany głos", "tut_g1p": "Zacznij od wyboru języka — to on decyduje, jakie głosy zobaczysz. Wybierz język, w którym napisany jest twój tekst, a następnie wypróbuj dwa lub trzy głosy przyciskiem podglądu; głosy bardzo różnią się ciepłem i tempem. Najpierw wpisz krótki akapit, wygeneruj go i posłuchaj. Gdy głos będzie pasował, włącz prędkość lub wysokość tonu i zmieniaj je małymi krokami: prędkość +10% sprawdza się przy energicznych treściach, a nieco niższy ton często brzmi bardziej autorytatywnie. Przy tekstach dłuższych niż strona generuj sekcja po sekcji i trzymaj się tego samego głosu oraz ustawień, aby fragmenty płynnie się łączyły.", "tut_g2h": "Jak korzystać z funkcji pauz", "tut_g2p": "Znaczniki pauz wstawiają do wygenerowanego dźwięku dokładną ciszę. Wpisz <b>[break:200ms]</b>, aby zrobić krótką pauzę, a <b>[break:1s]</b> lub <b>[break:2s]</b>, aby zrobić dłuższą — dramatyczne momenty, punkty listy i zmiany scen wypadają lepiej, gdy otacza je oddech. Naciśnięcie <b>Ctrl+B</b> wstawia znacznik [break:500ms] w miejscu kursora. Znaczniki nigdy nie pojawiają się w dźwięku ani w napisach; słychać tylko pauzę. Dobra zasada: 300–600ms między zdaniami zmieniającymi temat, 1–2 sekundy między scenami. Pamiętaj, że tryb podglądu po prostu pomija znaczniki, więc ostateczne wyczucie czasu oceniaj na wygenerowanym pliku.", "tut_g3h": "Przegląd kolekcji głosów", "tut_g3p": "Katalog Text 2 Speech zawiera ponad 300 głosów neuronowych w 75 językach, a każdy język oferuje kilka osobowości — płaską jak lektor wiadomości, ciepłą i konwersacyjną, jasną i młodzieżową. Nazwy zawierają region (Aria - US, Natasha - AU), a kilka głosów jest wielojęzycznych i zgrabnie radzi sobie z tekstem mieszanym językowo. Filtrowanie według płci i wyszukiwanie po nazwie ułatwiają poruszanie się po liście. W razie wątpliwości wygeneruj ten sam akapit trzema kandydatami i wybieraj uszami, a nie nazwami: właściwy głos zależy od materiału, a nie od etykiety.", "tut_h1": "Poradnik", "tut_sub": "Krótkie, praktyczne wskazówki, jak wycisnąć z Text 2 Speech jak najwięcej."}, "pt": {"auth_alert_create": "As contas chegam com o lançamento público. Não é preciso se cadastrar para converter texto.", "auth_alert_forgot": "A redefinição de senha chega junto com as contas no lançamento público.", "auth_alert_signin": "As contas chegam com o lançamento público. Tudo no Text 2 Speech já funciona sem login.", "auth_create": "Criar uma conta", "auth_email": "E-mail", "auth_forgot": "Esqueceu a senha?", "auth_h1": "Bem-vindo de volta", "auth_newq": "Novo por aqui?", "auth_pass": "Senha", "auth_signin": "Entrar", "auth_sub": "As contas são opcionais — o conversor funciona totalmente sem uma. Entre para manter suas vozes favoritas e seu histórico sincronizados (chegando com o lançamento público).", "doc_auth": "Conta — Text 2 Speech", "doc_donate": "Doar — Mantenha o Text 2 Speech gratuito para todos | Text 2 Speech", "doc_privacy": "Política de privacidade — Text 2 Speech", "doc_support": "Suporte e perguntas frequentes — Ajuda do texto para fala do Text 2 Speech", "doc_terms": "Termos de serviço — Text 2 Speech", "doc_tutorial": "Tutorial de conversão de texto em fala — Como criar narrações | Text 2 Speech", "don_alert": "O pagamento de doações será aberto com o lançamento público. Obrigado pela oferta!", "don_alipay": "Alipay", "don_amount": "Valor", "don_btn": "Doar agora", "don_crypto": "Criptomoedas", "don_crypto_sub": "USDT · ETH · BTC e mais", "don_h1": "Doar", "don_paypal": "PayPal (USD)", "don_sub": "O Text 2 Speech é gratuito para todos. Se ele economiza seu tempo, uma pequena contribuição ajuda a mantê-lo assim.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Para onde vão as doações", "don_where_p": "Custos de servidor · Desenvolvimento de recursos · Manutenção do serviço", "foot_privacy": "Política de privacidade", "foot_terms": "Termos de serviço", "nav_donate": "Doar", "nav_home": "Início", "nav_support": "Suporte", "nav_tutorial": "Tutorial", "priv_h1": "Política de privacidade", "priv_intro": "O Text 2 Speech foi projetado para precisar do mínimo possível dos seus dados. Você pode usar o conversor sem uma conta e sem nos informar seu nome ou e-mail.", "priv_s1h": "O texto que você converte", "priv_s1p": "O texto enviado é encaminhado ao mecanismo de voz apenas para produzir seu áudio. Os arquivos gerados ficam armazenados vinculados a um identificador de sessão aleatório e são excluídos automaticamente após um curto período; nunca são publicados, indexados ou usados para treinar modelos.", "priv_s2h": "Cookies e análises", "priv_s2p": "Se você aceitar o banner de cookies, usamos cookies de análise que respeitam a privacidade para contar visitas e ver quais recursos são populares. Recusar não muda nada no funcionamento da ferramenta.", "priv_s3h": "O que nunca fazemos", "priv_s3p": "Não vendemos dados pessoais, não criamos perfis de publicidade e não mantemos o áudio que você gera depois que sua sessão termina.", "priv_s4h": "Contato", "priv_s4p": "Dúvidas sobre privacidade: fale conosco pela <a href=\"/support.html\">página de suporte</a>.", "priv_updated": "Última atualização: outubro de 2026", "sup_alert": "Obrigado — a caixa de entrada do suporte será aberta com o lançamento público. Por enquanto, as perguntas frequentes cobrem os casos mais comuns.", "sup_contact_h": "Contato", "sup_email": "Seu e-mail", "sup_h1": "Suporte", "sup_msg": "Mensagem", "sup_msg_ph": "Descreva o que aconteceu, qual voz você usou e o que esperava...", "sup_notice": "O formulário de contato abre com o lançamento público. Até lá, as perguntas frequentes da página inicial respondem às dúvidas mais comuns.", "sup_o1": "Problema de geração", "sup_o2": "Pedido de voz", "sup_o3": "Relato de erro", "sup_o4": "Negócios / licenciamento", "sup_o5": "Outro", "sup_quick_h": "Soluções rápidas", "sup_quick_p": "• Sem som na prévia: verifique se a aba do navegador não está silenciada e experimente outra voz.<br>• Uma voz soa estranha para o seu texto: primeiro ajuste o idioma da voz para o idioma do texto.<br>• Texto longo está lento: divida-o em capítulos e gere em partes.<br>• Um resultado sumiu: os resultados ficam apenas na sessão atual do navegador — baixe logo.", "sup_send": "Enviar mensagem", "sup_sub": "A maioria das respostas está nas perguntas frequentes da página inicial. Ainda travado? Envie-nos os detalhes.", "sup_topic": "Assunto", "terms_h1": "Termos de serviço", "terms_s1h": "O serviço", "terms_s1p": "O Text 2 Speech converte o texto que você fornece em fala sintetizada e permite ouvir e baixar o resultado, junto com os arquivos de legenda. O serviço é fornecido como está, sem garantias de disponibilidade ininterrupta.", "terms_s2h": "Suas responsabilidades", "terms_s2p": "Converta apenas textos que você tem o direito de usar. Não use o áudio gerado para se passar por pessoas reais, enganar ouvintes ou violar leis aplicáveis. Você é responsável por como publica e licencia o que cria.", "terms_s3h": "Uso aceitável", "terms_s3p": "O uso pessoal, educacional e criativo é bem-vindo. O uso comercial do áudio gerado é sua responsabilidade: verifique-o em relação aos direitos sobre o seu texto de origem e às regras de licenciamento de voz aplicáveis na sua jurisdição.", "terms_s4h": "Alterações", "terms_s4p": "Os recursos e estes termos podem evoluir; alterações relevantes serão registradas nesta página com uma nova data.", "terms_updated": "Última atualização: outubro de 2026", "tut_g1h": "Primeiros passos: sua primeira voz gerada", "tut_g1p": "Comece pelo seletor de idioma — ele define quais vozes você verá. Escolha o idioma em que seu texto está escrito e experimente duas ou três vozes com o botão Ouvir; as vozes diferem muito em calor e ritmo. Digite primeiro um parágrafo curto, gere e escute. Quando a voz parecer certa, ative a Velocidade ou o Tom e ajuste em pequenos passos: +10% de velocidade combina com conteúdo enérgico, e um tom um pouco mais baixo costuma soar mais autoritário. Para textos com mais de uma página, gere seção por seção e mantenha a mesma voz e as mesmas configurações para as partes combinarem.", "tut_g2h": "Como usar o recurso de pausa", "tut_g2p": "Os marcadores de pausa inserem silêncio exato no áudio gerado. Digite <b>[break:200ms]</b> para uma pausa curta, <b>[break:1s]</b> ou <b>[break:2s]</b> para pausas mais longas — revelações dramáticas, itens de lista e mudanças de cena funcionam melhor com respiro ao redor. Pressionar <b>Ctrl+B</b> insere um marcador [break:500ms] na posição do cursor. Os marcadores nunca aparecem no áudio nem nas legendas; você ouve apenas a pausa. Uma boa regra: 300–600ms entre frases que mudam de assunto, 1–2 segundos entre cenas. Observe que o modo de prévia simplesmente ignora os marcadores, então avalie o ritmo final no arquivo gerado.", "tut_g3h": "Um passeio pela coleção de vozes", "tut_g3p": "O catálogo do Text 2 Speech reúne mais de 300 vozes neurais em 75 idiomas, e cada idioma oferece várias personalidades: neutra estilo apresentador de notícias, calorosa e conversacional, vibrante e jovem. Os nomes indicam sua região (Aria - US, Natasha - AU), e algumas vozes são multilíngues, lidando com textos em idiomas mistos com naturalidade. O filtro por gênero e a busca por nome mantêm a lista sob controle. Na dúvida, gere o mesmo parágrafo com três vozes candidatas e escolha pelos ouvidos, não pelos nomes: a voz certa depende do material, não do rótulo.", "tut_h1": "Tutorial", "tut_sub": "Guias curtos e práticos para aproveitar ao máximo o Text 2 Speech."}, "ru": {"auth_alert_create": "Аккаунты появятся вместе с публичным запуском. Для преобразования текста регистрация не нужна.", "auth_alert_forgot": "Сброс пароля появится вместе с аккаунтами при публичном запуске.", "auth_alert_signin": "Аккаунты появятся вместе с публичным запуском. Всё в Text 2 Speech уже работает без входа.", "auth_create": "Создать аккаунт", "auth_email": "Email", "auth_forgot": "Забыли пароль?", "auth_h1": "С возвращением", "auth_newq": "Впервые здесь?", "auth_pass": "Пароль", "auth_signin": "Войти", "auth_sub": "Аккаунт необязателен — конвертер полностью работает и без него. Войдите, чтобы синхронизировать избранные голоса и историю (появится вместе с публичным запуском).", "doc_auth": "Аккаунт — Text 2 Speech", "doc_donate": "Поддержать — помогите Text 2 Speech оставаться бесплатным для всех | Text 2 Speech", "doc_privacy": "Политика конфиденциальности — Text 2 Speech", "doc_support": "Поддержка и FAQ — помощь по Text 2 Speech Text to Speech", "doc_terms": "Условия использования — Text 2 Speech", "doc_tutorial": "Руководство по синтезу речи — как создавать озвучку | Text 2 Speech", "don_alert": "Оплата пожертвований откроется вместе с публичным запуском. Спасибо за вашу готовность помочь!", "don_alipay": "Alipay", "don_amount": "Сумма", "don_btn": "Пожертвовать", "don_crypto": "Криптовалюта", "don_crypto_sub": "USDT · ETH · BTC и другие", "don_h1": "Поддержать", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech бесплатен для всех. Если он экономит вам время, небольшой вклад поможет ему таким и оставаться.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "На что идут пожертвования", "don_where_p": "Расходы на серверы · Разработка функций · Поддержка сервиса", "foot_privacy": "Политика конфиденциальности", "foot_terms": "Условия использования", "nav_donate": "Поддержать", "nav_home": "Главная", "nav_support": "Поддержка", "nav_tutorial": "Руководство", "priv_h1": "Политика конфиденциальности", "priv_intro": "Text 2 Speech спроектирован так, чтобы нуждаться в минимальном количестве ваших данных. Вы можете пользоваться конвертером без аккаунта и не сообщая нам имя или email.", "priv_s1h": "Текст, который вы преобразуете", "priv_s1p": "Отправленный вами текст передаётся речевому движку только для создания вашего аудио. Сгенерированные файлы хранятся под случайным идентификатором сессии и автоматически удаляются через короткое время; они никогда не публикуются, не индексируются и не используются для обучения моделей.", "priv_s2h": "Файлы cookie и аналитика", "priv_s2p": "Если вы примете баннер cookie, мы используем уважающие конфиденциальность аналитические cookie, чтобы подсчитывать посещения и видеть, какие функции популярны. Отказ ничего не меняет в работе инструмента.", "priv_s3h": "Чего мы никогда не делаем", "priv_s3p": "Мы не продаём персональные данные, не создаём рекламные профили и не храним ваше сгенерированное аудио после окончания сессии.", "priv_s4h": "Контакты", "priv_s4p": "Вопросы о конфиденциальности: свяжитесь с нами через <a href=\"/support.html\">страницу поддержки</a>.", "priv_updated": "Последнее обновление: октябрь 2026", "sup_alert": "Спасибо — почта поддержки откроется вместе с публичным запуском. А пока в FAQ собраны ответы на частые вопросы.", "sup_contact_h": "Связаться с нами", "sup_email": "Ваш email", "sup_h1": "Поддержка", "sup_msg": "Сообщение", "sup_msg_ph": "Опишите, что произошло, какой голос вы использовали и что ожидали...", "sup_notice": "Форма обратной связи откроется с публичным запуском. А пока ответы на самые частые вопросы есть в разделе FAQ на главной странице.", "sup_o1": "Проблема с генерацией", "sup_o2": "Запрос голоса", "sup_o3": "Сообщение об ошибке", "sup_o4": "Бизнес / лицензирование", "sup_o5": "Другое", "sup_quick_h": "Быстрые решения", "sup_quick_p": "• Нет звука при предпрослушивании: проверьте, не отключён ли звук на вкладке браузера, и попробуйте другой голос.<br>• Голос звучит неподходяще для вашего текста: сначала подберите язык голоса под язык текста.<br>• Длинный текст обрабатывается медленно: разделите его на главы и генерируйте по частям.<br>• Результат исчез: результаты хранятся только в текущей сессии браузера — скачивайте их сразу.", "sup_send": "Отправить сообщение", "sup_sub": "Большинство ответов — в разделе FAQ на главной странице. Всё ещё не получается? Напишите нам подробности.", "sup_topic": "Тема", "terms_h1": "Условия использования", "terms_s1h": "Сервис", "terms_s1p": "Text 2 Speech преобразует предоставленный вами текст в синтезированную речь и позволяет прослушать и скачать результат вместе с файлами субтитров. Сервис предоставляется «как есть», без гарантий бесперебойной доступности.", "terms_s2h": "Ваши обязанности", "terms_s2p": "Преобразуйте только тот текст, на использование которого у вас есть права. Не используйте сгенерированное аудио, чтобы выдавать себя за реальных людей, вводить слушателей в заблуждение или нарушать применимые законы. Вы несёте ответственность за то, как публикуете и лицензируете созданное вами.", "terms_s3h": "Допустимое использование", "terms_s3p": "Личное, образовательное и творческое использование приветствуется. Коммерческое использование сгенерированного аудио — ваша ответственность: проверьте права на исходный текст и любые применимые правила лицензирования голосов в вашей юрисдикции.", "terms_s4h": "Изменения", "terms_s4p": "Функции и настоящие условия могут меняться; существенные изменения будут отмечены на этой странице с новой датой.", "terms_updated": "Последнее обновление: октябрь 2026", "tut_g1h": "Начало работы: ваш первый сгенерированный голос", "tut_g1p": "Начните с выбора языка — от него зависит, какие голоса вы увидите. Выберите язык, на котором написан ваш текст, затем послушайте два-три голоса с помощью кнопки предпрослушивания: голоса сильно различаются по теплоте и темпу. Сначала введите короткий абзац, сгенерируйте его и послушайте. Когда голос покажется подходящим, включите скорость или высоту тона и меняйте их небольшими шагами: скорость +10% подходит для энергичного контента, а чуть более низкий тон часто звучит авторитетнее. Для текстов длиннее одной страницы генерируйте по частям и сохраняйте один и тот же голос и настройки, чтобы фрагменты плавно сочетались.", "tut_g2h": "Как пользоваться функцией пауз", "tut_g2p": "Метки пауз вставляют в сгенерированный звук точную тишину. Введите <b>[break:200ms]</b> для короткой паузы, <b>[break:1s]</b> или <b>[break:2s]</b> — для более длинной: драматичные моменты, пункты списка и смена сцен звучат лучше, когда вокруг них есть воздух. Нажатие <b>Ctrl+B</b> вставляет метку [break:500ms] в позицию курсора. Метки никогда не попадают в звук или субтитры — вы слышите только паузу. Хорошее практическое правило: 300–600ms между предложениями, меняющими тему, 1–2 секунды между сценами. Учтите, что режим предпрослушивания просто пропускает метки, поэтому итоговый тайминг оценивайте по сгенерированному файлу.", "tut_g3h": "Обзор коллекции голосов", "tut_g3p": "В каталоге Text 2 Speech более 300 нейронных голосов на 75 языках, и для каждого языка есть несколько характеров — ровный дикторский, тёплый разговорный, яркий и молодой. В названиях указан регион (Aria - US, Natasha - AU), а некоторые голоса многоязычны и изящно справляются с текстами на смешанных языках. Фильтр по полу и поиск по имени помогают не потеряться в списке. Если сомневаетесь, сгенерируйте один и тот же абзац тремя голосами-кандидатами и выбирайте ушами, а не по названиям: правильный голос зависит от материала, а не от ярлыка.", "tut_h1": "Руководство", "tut_sub": "Короткие практические советы, которые помогут получить от Text 2 Speech максимум."}, "sv": {"auth_alert_create": "Konton kommer i samband med den offentliga lanseringen. Ingen registrering behövs för att konvertera text.", "auth_alert_forgot": "Återställning av lösenord kommer tillsammans med konton vid den offentliga lanseringen.", "auth_alert_signin": "Konton kommer i samband med den offentliga lanseringen. Allt på Text 2 Speech fungerar redan i utloggat läge.", "auth_create": "Skapa ett konto", "auth_email": "E-post", "auth_forgot": "Glömt lösenordet?", "auth_h1": "Välkommen tillbaka", "auth_newq": "Ny här?", "auth_pass": "Lösenord", "auth_signin": "Logga in", "auth_sub": "Konton är valfria — omvandlaren fungerar fullt ut utan ett konto. Logga in för att hålla dina röstfavoriter och din historik synkroniserade (rullas ut i samband med den offentliga lanseringen).", "doc_auth": "Konto — Text 2 Speech", "doc_donate": "Donera — Håll Text 2 Speech gratis för alla | Text 2 Speech", "doc_privacy": "Integritetspolicy — Text 2 Speech", "doc_support": "Support och vanliga frågor — Hjälp för Text 2 Speech Text till tal", "doc_terms": "Användarvillkor — Text 2 Speech", "doc_tutorial": "Handledning för text till tal — Så gör du voiceovers | Text 2 Speech", "don_alert": "Donationskassan öppnar i samband med den offentliga lanseringen. Tack för erbjudandet!", "don_alipay": "Alipay", "don_amount": "Belopp", "don_btn": "Donera nu", "don_crypto": "Kryptovaluta", "don_crypto_sub": "USDT · ETH · BTC med mera", "don_h1": "Donera", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech är gratis för alla. Om det sparar dig tid hjälper ett litet bidrag till att hålla det så.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Vad donationer går till", "don_where_p": "Serverkostnader · Funktionsutveckling · Underhåll av tjänsten", "foot_privacy": "Integritetspolicy", "foot_terms": "Användarvillkor", "nav_donate": "Donera", "nav_home": "Hem", "nav_support": "Support", "nav_tutorial": "Handledning", "priv_h1": "Integritetspolicy", "priv_intro": "Text 2 Speech är utformad för att behöva så lite av dina uppgifter som möjligt. Du kan använda omvandlaren utan konto och utan att ge oss ditt namn eller din e-postadress.", "priv_s1h": "Text du konverterar", "priv_s1p": "Text du skickar in skickas endast till talmotorn för att producera ditt ljud. Genererade filer lagras under en slumpmässig sessionsidentifierare och raderas automatiskt efter en kort tid; de publiceras, indexeras eller används aldrig för att träna modeller.", "priv_s2h": "Cookies och analys", "priv_s2p": "Om du accepterar cookiebannern använder vi integritetsvänliga analyscookies för att räkna besök och se vilka funktioner som är populära. Att avböja ändrar ingenting i hur verktyget fungerar.", "priv_s3h": "Vad vi aldrig gör", "priv_s3p": "Vi säljer inte personuppgifter, vi bygger inte reklamprofiler och vi behåller inte ditt genererade ljud efter att din session har avslutats.", "priv_s4h": "Kontakt", "priv_s4p": "Frågor om integritet: nå oss via <a href=\"/support.html\">supportsidan</a>.", "priv_updated": "Senast uppdaterad: oktober 2026", "sup_alert": "Tack — supportinkorgen öppnar i samband med den offentliga lanseringen. Tills vidare täcker FAQ:n de vanliga fallen.", "sup_contact_h": "Kontakt", "sup_email": "Din e-postadress", "sup_h1": "Support", "sup_msg": "Meddelande", "sup_msg_ph": "Beskriv vad som hände, vilken röst du använde och vad du förväntade dig...", "sup_notice": "Kontaktformuläret öppnar vid den offentliga lanseringen. Fram till dess besvarar FAQ:n på startsidan de vanligaste frågorna.", "sup_o1": "Problem med generering", "sup_o2": "Önskemål om röst", "sup_o3": "Felrapport", "sup_o4": "Företag / licensiering", "sup_o5": "Övrigt", "sup_quick_h": "Snabba lösningar", "sup_quick_p": "• Inget ljud vid Förhandslyssna: kontrollera att webbläsarfliken inte är avstängd och prova en annan röst.<br>• En röst låter fel för din text: matcha först Röstspråk med textspråket.<br>• Lång text är långsam: dela upp den i kapitel och generera i delar.<br>• Ett resultat försvann: resultat finns bara kvar under den aktuella webbläsarsessionen — ladda ner direkt.", "sup_send": "Skicka meddelande", "sup_sub": "De flesta svar finns i FAQ:n på startsidan. Sitter du ändå fast? Skicka detaljerna till oss.", "sup_topic": "Ämne", "terms_h1": "Användarvillkor", "terms_s1h": "Tjänsten", "terms_s1p": "Text 2 Speech omvandlar text som du tillhandahåller till syntetiserat tal och låter dig spela upp och ladda ner resultatet tillsammans med undertextfiler. Tjänsten tillhandahålls i befintligt skick, utan garantier för oavbruten tillgänglighet.", "terms_s2h": "Ditt ansvar", "terms_s2p": "Konvertera endast text som du har rätt att använda. Använd inte genererat ljud för att efterlikna verkliga personer, vilseleda lyssnare eller bryta mot tillämpliga lagar. Du ansvarar för hur du publicerar och licensierar det du skapar.", "terms_s3h": "Acceptabel användning", "terms_s3p": "Personlig, utbildningsmässig och kreativ användning är välkommen. Kommersiell användning av genererat ljud är ditt ansvar att klargöra mot rättigheterna i din källtext och eventuella tillämpliga regler för röstlicensiering i din jurisdiktion.", "terms_s4h": "Ändringar", "terms_s4p": "Funktioner och dessa villkor kan utvecklas; väsentliga ändringar noteras på den här sidan med ett nytt datum.", "terms_updated": "Senast uppdaterad: oktober 2026", "tut_g1h": "Kom igång: din första genererade röst", "tut_g1p": "Börja med språkväljaren — den avgör vilka röster du ser. Välj det språk din text är skriven på och prova sedan två eller tre röster med knappen Förhandslyssna; röster skiljer sig mycket åt i värme och tempo. Skriv först ett kort stycke, generera det och lyssna. När rösten känns rätt kan du slå på Hastighet eller Tonhöjd och justera i små steg: +10 % hastighet passar energiskt innehåll, och en något lägre tonhöjd låter ofta mer auktoritativ. För allt som är längre än en sida genererar du avsnitt för avsnitt och behåller samma röst och inställningar så att delarna smälter ihop.", "tut_g2h": "Så använder du pausfunktionen", "tut_g2p": "Pausmarkörer infogar exakt tystnad i det genererade ljudet. Skriv <b>[break:200ms]</b> för en kort paus, <b>[break:1s]</b> eller <b>[break:2s]</b> för längre pauser — dramatiska avslöjanden, listpunkter och scenbyten landar alla bättre med luft omkring sig. Tryck på <b>Ctrl+B</b> för att lägga in en [break:500ms]-markör vid markören. Markörer syns aldrig i ljudet eller undertexterna; du hör bara pausen. En bra tumregel: 300–600 ms mellan meningar som byter ämne, 1–2 sekunder mellan scener. Observera att förhandslyssningsläget helt enkelt hoppar över markörerna, så bedöm den slutliga tajmingen på den genererade filen.", "tut_g3h": "En rundtur i röstsamlingen", "tut_g3p": "Text 2 Speechs katalog rymmer 300+ neurala röster på 75 språk, och varje språk erbjuder flera personligheter — platt som en nyhetsuppläsare, varm och samtalslik, ljus och ungdomlig. Namnen anger deras region (Aria - US, Natasha - AU), och några röster är flerspråkiga och hanterar text på blandade språk utan problem. Könsfiltrering och namnsökning håller listan hanterbar. Är du osäker, generera samma stycke med tre kandidatröster och välj med öronen, inte namnen: rätt röst beror på materialet, inte på etiketten.", "tut_h1": "Handledning", "tut_sub": "Korta, praktiska guider för att få ut mesta möjliga av Text 2 Speech."}, "th": {"auth_alert_create": "บัญชีจะมาพร้อมกับการเปิดตัวสาธารณะ ไม่จำเป็นต้องสมัครเพื่อแปลงข้อความ", "auth_alert_forgot": "การรีเซ็ตรหัสผ่านจะมาพร้อมกับบัญชีเมื่อเปิดตัวสาธารณะ", "auth_alert_signin": "บัญชีจะมาพร้อมกับการเปิดตัวสาธารณะ ทุกอย่างบน Text 2 Speech ใช้งานได้แล้วแม้ไม่ได้ลงชื่อเข้าใช้", "auth_create": "สร้างบัญชี", "auth_email": "อีเมล", "auth_forgot": "ลืมรหัสผ่าน?", "auth_h1": "ยินดีต้อนรับกลับ", "auth_newq": "เพิ่งมาใหม่ใช่ไหม", "auth_pass": "รหัสผ่าน", "auth_signin": "ลงชื่อเข้าใช้", "auth_sub": "บัญชีเป็นทางเลือก — ตัวแปลงใช้งานได้เต็มรูปแบบโดยไม่ต้องมีบัญชี ลงชื่อเข้าใช้เพื่อซิงค์เสียงโปรดและประวัติของคุณ (เปิดให้ใช้เมื่อเปิดตัวสาธารณะ)", "doc_auth": "บัญชี — Text 2 Speech", "doc_donate": "บริจาค — ช่วยให้ Text 2 Speech ฟรีสำหรับทุกคนต่อไป | Text 2 Speech", "doc_privacy": "นโยบายความเป็นส่วนตัว — Text 2 Speech", "doc_support": "การสนับสนุนและคำถามที่พบบ่อย — ความช่วยเหลือ Text 2 Speech แปลงข้อความเป็นเสียง", "doc_terms": "ข้อกำหนดการใช้บริการ — Text 2 Speech", "doc_tutorial": "บทช่วยสอนแปลงข้อความเป็นเสียง — วิธีสร้างเสียงบรรยาย | Text 2 Speech", "don_alert": "การชำระเงินบริจาคจะเปิดเมื่อเปิดตัวสาธารณะ ขอบคุณสำหรับน้ำใจของคุณ!", "don_alipay": "Alipay", "don_amount": "จำนวนเงิน", "don_btn": "บริจาคตอนนี้", "don_crypto": "สกุลเงินดิจิทัล", "don_crypto_sub": "USDT · ETH · BTC และอื่น ๆ", "don_h1": "บริจาค", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech ฟรีสำหรับทุกคน หากมันช่วยประหยัดเวลาของคุณ การสนับสนุนเล็ก ๆ น้อย ๆ จะช่วยให้มันยังคงฟรีต่อไป", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "เงินบริจาคนำไปใช้ที่ไหน", "don_where_p": "ค่าเซิร์ฟเวอร์ · การพัฒนาฟีเจอร์ · การดูแลบริการ", "foot_privacy": "นโยบายความเป็นส่วนตัว", "foot_terms": "ข้อกำหนดการใช้บริการ", "nav_donate": "บริจาค", "nav_home": "หน้าแรก", "nav_support": "การสนับสนุน", "nav_tutorial": "บทช่วยสอน", "priv_h1": "นโยบายความเป็นส่วนตัว", "priv_intro": "Text 2 Speech ถูกออกแบบมาให้ต้องการข้อมูลของคุณน้อยที่สุดเท่าที่จะเป็นไปได้ คุณสามารถใช้ตัวแปลงได้โดยไม่มีบัญชี และไม่ต้องให้ชื่อหรืออีเมลแก่เรา", "priv_s1h": "ข้อความที่คุณแปลง", "priv_s1p": "ข้อความที่คุณส่งจะถูกส่งไปยังเครื่องมือสร้างเสียงเพื่อผลิตเสียงของคุณเท่านั้น ไฟล์ที่สร้างขึ้นจะถูกจัดเก็บไว้กับตัวระบุเซสชันแบบสุ่ม และจะถูกลบโดยอัตโนมัติหลังจากช่วงเวลาสั้น ๆ ไฟล์เหล่านี้จะไม่ถูกเผยแพร่ จัดทำดัชนี หรือใช้ฝึกโมเดลเด็ดขาด", "priv_s2h": "คุกกี้และการวิเคราะห์", "priv_s2p": "หากคุณยอมรับแบนเนอร์คุกกี้ เราจะใช้คุกกี้วิเคราะห์ที่เคารพความเป็นส่วนตัวเพื่อนับจำนวนการเข้าชมและดูว่าฟีเจอร์ใดได้รับความนิยม การปฏิเสธจะไม่เปลี่ยนแปลงวิธีการทำงานของเครื่องมือแต่อย่างใด", "priv_s3h": "สิ่งที่เราไม่เคยทำ", "priv_s3p": "เราไม่ขายข้อมูลส่วนบุคคล เราไม่สร้างโปรไฟล์โฆษณา และเราไม่เก็บเสียงที่คุณสร้างไว้หลังจากเซสชันของคุณสิ้นสุดลง", "priv_s4h": "ติดต่อ", "priv_s4p": "คำถามเกี่ยวกับความเป็นส่วนตัว: ติดต่อเราผ่าน <a href=\"/support.html\">หน้าการสนับสนุน</a>", "priv_updated": "อัปเดตล่าสุด: ตุลาคม 2026", "sup_alert": "ขอบคุณ — กล่องข้อความสนับสนุนจะเปิดเมื่อเปิดตัวสาธารณะ ในตอนนี้ คำถามที่พบบ่อยครอบคลุมกรณีทั่วไปแล้ว", "sup_contact_h": "ติดต่อ", "sup_email": "อีเมลของคุณ", "sup_h1": "การสนับสนุน", "sup_msg": "ข้อความ", "sup_msg_ph": "อธิบายว่าเกิดอะไรขึ้น คุณใช้เสียงใด และคุณคาดหวังอะไร...", "sup_notice": "แบบฟอร์มติดต่อจะเปิดใช้งานเมื่อเปิดตัวอย่างเป็นทางการ ระหว่างนี้ คำถามที่พบบ่อยในหน้าแรกตอบคำถามที่พบบ่อยที่สุดไว้แล้ว", "sup_o1": "ปัญหาการสร้างเสียง", "sup_o2": "ขอเสียง", "sup_o3": "รายงานข้อบกพร่อง", "sup_o4": "ธุรกิจ / การอนุญาตใช้สิทธิ์", "sup_o5": "อื่น ๆ", "sup_quick_h": "วิธีแก้ด่วน", "sup_quick_p": "• ตัวอย่างไม่มีเสียง: ตรวจสอบว่าแท็บเบราว์เซอร์ไม่ได้ปิดเสียงไว้ และลองเปลี่ยนเสียงอื่น<br>• เสียงฟังดูไม่เหมาะกับข้อความของคุณ: จับคู่ภาษาของเสียงให้ตรงกับภาษาของข้อความก่อน<br>• ข้อความยาวสร้างช้า: แบ่งเป็นบท ๆ แล้วสร้างทีละส่วน<br>• ผลลัพธ์หายไป: ผลลัพธ์จะมีอยู่เฉพาะในเซสชันเบราว์เซอร์ปัจจุบันเท่านั้น — โปรดดาวน์โหลดทันที", "sup_send": "ส่งข้อความ", "sup_sub": "คำตอบส่วนใหญ่อยู่ในคำถามที่พบบ่อยบนหน้าแรก ยังติดปัญหาอยู่ใช่ไหม ส่งรายละเอียดมาให้เรา", "sup_topic": "หัวข้อ", "terms_h1": "ข้อกำหนดการใช้บริการ", "terms_s1h": "บริการ", "terms_s1p": "Text 2 Speech แปลงข้อความที่คุณให้มาเป็นเสียงสังเคราะห์ และให้คุณเล่นและดาวน์โหลดผลลัพธ์พร้อมกับไฟล์คำบรรยาย บริการนี้ให้บริการตามสภาพที่เป็นอยู่ โดยไม่รับประกันว่าจะพร้อมใช้งานโดยไม่หยุดชะงัก", "terms_s2h": "ความรับผิดชอบของคุณ", "terms_s2p": "แปลงเฉพาะข้อความที่คุณมีสิทธิ์ใช้เท่านั้น อย่าใช้เสียงที่สร้างขึ้นเพื่อแอบอ้างเป็นบุคคลจริง หลอกลวงผู้ฟัง หรือฝ่าฝืนกฎหมายที่เกี่ยวข้อง คุณต้องรับผิดชอบวิธีการเผยแพร่และอนุญาตใช้สิทธิ์สิ่งที่คุณสร้างขึ้น", "terms_s3h": "การใช้งานที่ยอมรับได้", "terms_s3p": "ยินดีต้อนรับการใช้งานส่วนบุคคล การศึกษา และเชิงสร้างสรรค์ การใช้เสียงที่สร้างขึ้นในเชิงพาณิชย์เป็นความรับผิดชอบของคุณในการตรวจสอบสิทธิ์ในข้อความต้นฉบับของคุณและกฎการอนุญาตใช้เสียงที่เกี่ยวข้องในเขตอำนาจศาลของคุณ", "terms_s4h": "การเปลี่ยนแปลง", "terms_s4p": "ฟีเจอร์และข้อกำหนดเหล่านี้อาจเปลี่ยนแปลงไป การเปลี่ยนแปลงที่สำคัญจะระบุไว้ในหน้านี้พร้อมวันที่ใหม่", "terms_updated": "อัปเดตล่าสุด: ตุลาคม 2026", "tut_g1h": "เริ่มต้นใช้งาน: สร้างเสียงแรกของคุณ", "tut_g1p": "เริ่มจากตัวเลือกภาษา — มันเป็นตัวกำหนดว่าคุณจะเห็นเสียงใดบ้าง เลือกภาษาที่ข้อความของคุณเขียนไว้ จากนั้นลองฟังเสียงสองหรือสามเสียงด้วยปุ่มตัวอย่าง เสียงแต่ละเสียงแตกต่างกันมากทั้งในด้านความอบอุ่นและจังหวะ พิมพ์ย่อหน้าสั้น ๆ ก่อน สร้างและฟังดู เมื่อรู้สึกว่าเสียงใช่แล้ว ให้เปิดความเร็วหรือระดับเสียงแล้วปรับทีละน้อย ความเร็ว +10% เหมาะกับเนื้อหาที่มีพลัง ส่วนระดับเสียงที่ต่ำลงเล็กน้อยมักฟังดูน่าเชื่อถือกว่า สำหรับเนื้อหาที่ยาวกว่าหนึ่งหน้า ให้สร้างทีละส่วนและใช้เสียงและการตั้งค่าเดียวกัน เพื่อให้แต่ละส่วนกลมกลืนกัน", "tut_g2h": "วิธีใช้ฟีเจอร์หยุดพัก", "tut_g2p": "เครื่องหมายหยุดพักจะแทรกความเงียบที่แม่นยำลงในเสียงที่สร้างขึ้น พิมพ์ <b>[break:200ms]</b> สำหรับการหยุดสั้น ๆ และ <b>[break:1s]</b> หรือ <b>[break:2s]</b> สำหรับการหยุดที่ยาวกว่า — การเปิดเผยที่น่าตื่นเต้น รายการ และการเปลี่ยนฉาก ล้วนได้ผลดีกว่าเมื่อมีช่องว่างรอบ ๆ การกด <b>Ctrl+B</b> จะวางเครื่องหมาย [break:500ms] ไว้ที่ตำแหน่งเคอร์เซอร์ เครื่องหมายจะไม่ปรากฏในเสียงหรือคำบรรยาย คุณจะได้ยินเพียงการหยุดพักเท่านั้น หลักง่าย ๆ คือ 300–600ms ระหว่างประโยคที่เปลี่ยนหัวข้อ และ 1–2 วินาทีระหว่างฉาก โปรดทราบว่าโหมดตัวอย่างจะข้ามเครื่องหมายไปเฉย ๆ ดังนั้นให้ตัดสินจังหวะสุดท้ายจากไฟล์ที่สร้างขึ้น", "tut_g3h": "พาชมคอลเลกชันเสียง", "tut_g3p": "แคตตาล็อกของ Text 2 Speech มีเสียงนิวรัลมากกว่า 300+ เสียง ครอบคลุม 75 ภาษา และแต่ละภาษามีบุคลิกหลายแบบ — เรียบแบบผู้ประกาศข่าว อบอุ่นและเป็นกันเอง สดใสและดูอ่อนเยาว์ ชื่อจะมีภูมิภาคกำกับไว้ (Aria - US, Natasha - AU) และบางเสียงรองรับหลายภาษา จัดการข้อความหลายภาษาปนกันได้อย่างเป็นธรรมชาติ ตัวกรองเพศและการค้นหาตามชื่อช่วยให้รายการจัดการได้ง่าย เมื่อลังเล ให้สร้างย่อหน้าเดียวกันด้วยเสียงที่เลือกไว้สามเสียง แล้วเลือกด้วยหูของคุณ ไม่ใช่ด้วยชื่อ เสียงที่เหมาะสมขึ้นอยู่กับเนื้อหา ไม่ใช่ฉลาก", "tut_h1": "บทช่วยสอน", "tut_sub": "คู่มือสั้น ๆ ที่ใช้ได้จริง เพื่อให้คุณใช้ Text 2 Speech ได้คุ้มค่าที่สุด"}, "tr": {"auth_alert_create": "Hesaplar herkese açık lansmanla birlikte gelecek. Metin dönüştürmek için kayıt gerekmez.", "auth_alert_forgot": "Şifre sıfırlama, herkese açık lansmanda hesaplarla birlikte gelecek.", "auth_alert_signin": "Hesaplar herkese açık lansmanla birlikte gelecek. Text 2 Speech'deki her şey zaten giriş yapmadan çalışıyor.", "auth_create": "Hesap oluştur", "auth_email": "E-posta", "auth_forgot": "Şifrenizi mi unuttunuz?", "auth_h1": "Tekrar hoş geldiniz", "auth_newq": "Burada yeni misiniz?", "auth_pass": "Şifre", "auth_signin": "Giriş yap", "auth_sub": "Hesaplar isteğe bağlıdır — dönüştürücü onlar olmadan da tam olarak çalışır. Favori seslerinizi ve geçmişinizi senkron tutmak için giriş yapın (herkese açık lansmanla geliyor).", "doc_auth": "Hesap — Text 2 Speech", "doc_donate": "Bağış Yap — Text 2 Speech'yi Herkes İçin Ücretsiz Tutun | Text 2 Speech", "doc_privacy": "Gizlilik Politikası — Text 2 Speech", "doc_support": "Destek ve SSS — Text 2 Speech Metinden Konuşmaya Yardımı", "doc_terms": "Kullanım Şartları — Text 2 Speech", "doc_tutorial": "Metinden Konuşmaya Eğitimi — Seslendirme Nasıl Yapılır | Text 2 Speech", "don_alert": "Bağış ödeme sayfası herkese açık lansmanla birlikte açılacaktır. Teklifiniz için teşekkürler!", "don_alipay": "Alipay", "don_amount": "Tutar", "don_btn": "Şimdi Bağış Yap", "don_crypto": "Kripto para", "don_crypto_sub": "USDT · ETH · BTC ve daha fazlası", "don_h1": "Bağış Yap", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech herkes için ücretsizdir. Size zaman kazandırıyorsa, küçük bir katkı onun böyle kalmasını sağlar.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Bağışlar nereye gidiyor", "don_where_p": "Sunucu maliyetleri · Özellik geliştirme · Hizmet bakımı", "foot_privacy": "Gizlilik Politikası", "foot_terms": "Kullanım Şartları", "nav_donate": "Bağış Yap", "nav_home": "Ana Sayfa", "nav_support": "Destek", "nav_tutorial": "Eğitim", "priv_h1": "Gizlilik Politikası", "priv_intro": "Text 2 Speech, verilerinize mümkün olduğunca az ihtiyaç duyacak şekilde tasarlanmıştır. Dönüştürücüyü hesap oluşturmadan ve adınızı ya da e-postanızı vermeden kullanabilirsiniz.", "priv_s1h": "Dönüştürdüğünüz metin", "priv_s1p": "Gönderdiğiniz metin, yalnızca sesinizi üretmek için konuşma motoruna iletilir. Oluşturulan dosyalar rastgele bir oturum tanımlayıcısına bağlı olarak saklanır ve kısa bir süre sonra otomatik olarak silinir; asla yayımlanmaz, dizine eklenmez veya modelleri eğitmek için kullanılmaz.", "priv_s2h": "Çerezler ve analiz", "priv_s2p": "Çerez çubuğunu kabul ederseniz, ziyaretleri saymak ve hangi özelliklerin popüler olduğunu görmek için gizliliğe saygılı analiz çerezleri kullanırız. Reddetmek, aracın çalışma şekliyle ilgili hiçbir şeyi değiştirmez.", "priv_s3h": "Asla yapmadıklarımız", "priv_s3p": "Kişisel verileri satmayız, reklam profilleri oluşturmayız ve oturumunuz sona erdikten sonra oluşturduğunuz sesi saklamayız.", "priv_s4h": "İletişim", "priv_s4p": "Gizlilikle ilgili sorularınız için <a href=\"/support.html\">Destek sayfası</a> üzerinden bize ulaşın.", "priv_updated": "Son güncelleme: Ekim 2026", "sup_alert": "Teşekkürler — destek gelen kutusu herkese açık lansmanla birlikte açılacak. Şimdilik SSS, sık karşılaşılan durumları kapsıyor.", "sup_contact_h": "İletişim", "sup_email": "E-postanız", "sup_h1": "Destek", "sup_msg": "Mesaj", "sup_msg_ph": "Ne olduğunu, hangi sesi kullandığınızı ve ne beklediğinizi anlatın...", "sup_notice": "İletişim formu genel lansmanla birlikte açılacak. O zamana kadar ana sayfadaki SSS en sık sorulan soruları yanıtlıyor.", "sup_o1": "Oluşturma sorunu", "sup_o2": "Ses isteği", "sup_o3": "Hata bildirimi", "sup_o4": "Ticari / lisanslama", "sup_o5": "Diğer", "sup_quick_h": "Hızlı çözümler", "sup_quick_p": "• Önizlemede ses yok: tarayıcı sekmesinin sessize alınmadığını kontrol edin ve başka bir ses deneyin.<br>• Bir ses metniniz için yanlış duyuluyor: önce Ses Dili'ni metnin diliyle eşleştirin.<br>• Uzun metin yavaş: bölümlere ayırın ve parçalar halinde oluşturun.<br>• Bir sonuç kayboldu: sonuçlar yalnızca geçerli tarayıcı oturumu boyunca kalır — hemen indirin.", "sup_send": "Mesajı gönder", "sup_sub": "Çoğu yanıt ana sayfadaki SSS bölümünde yer alır. Hâlâ takıldınız mı? Ayrıntıları bize gönderin.", "sup_topic": "Konu", "terms_h1": "Kullanım Şartları", "terms_s1h": "Hizmet", "terms_s1p": "Text 2 Speech, sağladığınız metni sentezlenmiş konuşmaya dönüştürür ve sonucu alt yazı dosyalarıyla birlikte oynatıp indirmenize olanak tanır. Hizmet olduğu gibi sunulur; kesintisiz kullanılabilirlik garantisi verilmez.", "terms_s2h": "Sorumluluklarınız", "terms_s2p": "Yalnızca kullanma hakkına sahip olduğunuz metinleri dönüştürün. Oluşturulan sesi gerçek kişileri taklit etmek, dinleyicileri aldatmak veya geçerli yasaları ihlal etmek için kullanmayın. Oluşturduklarınızı nasıl yayımlayıp lisansladığınızdan siz sorumlusunuz.", "terms_s3h": "Kabul edilebilir kullanım", "terms_s3p": "Kişisel, eğitimsel ve yaratıcı kullanım memnuniyetle karşılanır. Oluşturulan sesin ticari kullanımının, kaynak metninizdeki haklara ve yargı alanınızdaki geçerli ses lisanslama kurallarına göre uygunluğunu sağlamak sizin sorumluluğunuzdadır.", "terms_s4h": "Değişiklikler", "terms_s4p": "Özellikler ve bu şartlar değişebilir; önemli değişiklikler bu sayfada yeni bir tarihle belirtilecektir.", "terms_updated": "Son güncelleme: Ekim 2026", "tut_g1h": "Başlangıç: ilk oluşturduğunuz ses", "tut_g1p": "Dil seçiciyle başlayın — hangi sesleri göreceğinizi o belirler. Metninizin yazıldığı dili seçin, ardından Önizleme düğmesiyle iki üç sesi deneyin; sesler sıcaklık ve tempo bakımından epey farklıdır. Önce kısa bir paragraf yazın, oluşturun ve dinleyin. Ses doğru hissettirdiğinde Hız veya Perde ayarını açın ve küçük adımlarla oynayın: +%10 hız enerjik içeriklere uygundur, biraz daha düşük bir perde çoğu zaman daha otoriter duyulur. Bir sayfadan uzun metinlerde bölümleri tek tek oluşturun ve parçaların birbirine uyması için aynı sesi ve ayarları koruyun.", "tut_g2h": "Duraklatma özelliği nasıl kullanılır", "tut_g2p": "Duraklatma işaretleri, oluşturulan sese tam süreli sessizlik ekler. Kısa bir durak için <b>[break:200ms]</b>, daha uzun duraklar için <b>[break:1s]</b> veya <b>[break:2s]</b> yazın — dramatik açıklamalar, liste öğeleri ve sahne geçişleri, etraflarında boşluk olduğunda çok daha etkili olur. <b>Ctrl+B</b> tuşlarına basmak imlecinizin olduğu yere bir [break:500ms] işareti bırakır. İşaretler asla seste veya alt yazılarda görünmez; yalnızca duraklamayı duyarsınız. İyi bir pratik kural: konu değiştiren cümleler arasında 300–600ms, sahneler arasında 1–2 saniye. Önizleme modunun işaretleri atladığını unutmayın; bu yüzden nihai zamanlamayı oluşturulan dosyaya göre değerlendirin.", "tut_g3h": "Ses koleksiyonunda bir tur", "tut_g3p": "Text 2 Speech'nin kataloğunda 75 dilde 300+ sinir ağı sesi bulunur ve her dil birkaç kişilik sunar — haber spikeri gibi nötr, sıcak ve sohbet havasında, parlak ve genç. İsimler bölgeyi taşır (Aria - US, Natasha - AU) ve birkaç ses çok dillidir; karışık dilli metinleri rahatça işler. Cinsiyet filtreleme ve isim araması listeyi yönetilebilir tutar. Kararsız kaldığınızda aynı paragrafı üç aday sesle oluşturun ve isimlere değil kulaklarınıza göre seçin: doğru ses, etikete değil malzemeye bağlıdır.", "tut_h1": "Eğitim", "tut_sub": "Text 2 Speech'den en iyi şekilde yararlanmanız için kısa ve pratik kılavuzlar."}, "vi": {"auth_alert_create": "Tài khoản sẽ có khi ra mắt công khai. Không cần đăng ký để chuyển đổi văn bản.", "auth_alert_forgot": "Đặt lại mật khẩu sẽ có cùng với tài khoản khi ra mắt công khai.", "auth_alert_signin": "Tài khoản sẽ có khi ra mắt công khai. Mọi thứ trên Text 2 Speech đều đã hoạt động khi chưa đăng nhập.", "auth_create": "Tạo tài khoản", "auth_email": "Email", "auth_forgot": "Quên mật khẩu?", "auth_h1": "Chào mừng trở lại", "auth_newq": "Bạn mới đến đây?", "auth_pass": "Mật khẩu", "auth_signin": "Đăng nhập", "auth_sub": "Tài khoản là tùy chọn — công cụ chuyển đổi hoạt động đầy đủ mà không cần tài khoản. Đăng nhập để đồng bộ giọng yêu thích và lịch sử của bạn (sẽ ra mắt cùng đợt phát hành công khai).", "doc_auth": "Tài khoản — Text 2 Speech", "doc_donate": "Ủng hộ — Giúp Text 2 Speech luôn miễn phí cho mọi người | Text 2 Speech", "doc_privacy": "Chính sách bảo mật — Text 2 Speech", "doc_support": "Hỗ trợ & Câu hỏi thường gặp — Trợ giúp Text 2 Speech Text to Speech", "doc_terms": "Điều khoản dịch vụ — Text 2 Speech", "doc_tutorial": "Hướng dẫn chuyển văn bản thành giọng nói — Cách tạo lồng tiếng | Text 2 Speech", "don_alert": "Thanh toán ủng hộ sẽ mở cùng với đợt ra mắt công khai. Cảm ơn bạn đã ngỏ ý!", "don_alipay": "Alipay", "don_amount": "Số tiền", "don_btn": "Ủng hộ ngay", "don_crypto": "Tiền điện tử", "don_crypto_sub": "USDT · ETH · BTC và hơn nữa", "don_h1": "Ủng hộ", "don_paypal": "PayPal (USD)", "don_sub": "Text 2 Speech miễn phí cho mọi người. Nếu nó giúp bạn tiết kiệm thời gian, một khoản đóng góp nhỏ sẽ giúp nó tiếp tục như vậy.", "don_wechat": "WeChat Pay (CNY)", "don_where_h": "Khoản ủng hộ được dùng vào đâu", "don_where_p": "Chi phí máy chủ · Phát triển tính năng · Bảo trì dịch vụ", "foot_privacy": "Chính sách bảo mật", "foot_terms": "Điều khoản dịch vụ", "nav_donate": "Ủng hộ", "nav_home": "Trang chủ", "nav_support": "Hỗ trợ", "nav_tutorial": "Hướng dẫn", "priv_h1": "Chính sách bảo mật", "priv_intro": "Text 2 Speech được thiết kế để cần càng ít dữ liệu của bạn càng tốt. Bạn có thể dùng công cụ chuyển đổi mà không cần tài khoản và không cần cho chúng tôi biết tên hay email của bạn.", "priv_s1h": "Văn bản bạn chuyển đổi", "priv_s1p": "Văn bản bạn gửi chỉ được chuyển đến công cụ giọng nói để tạo âm thanh cho bạn. Các tệp được tạo được lưu gắn với một mã định danh phiên ngẫu nhiên và tự động bị xóa sau một thời gian ngắn; chúng không bao giờ được công bố, lập chỉ mục hay dùng để huấn luyện mô hình.", "priv_s2h": "Cookie và phân tích", "priv_s2p": "Nếu bạn chấp nhận banner cookie, chúng tôi sử dụng cookie phân tích tôn trọng quyền riêng tư để đếm lượt truy cập và xem tính năng nào được ưa chuộng. Từ chối không làm thay đổi cách công cụ hoạt động.", "priv_s3h": "Những điều chúng tôi không bao giờ làm", "priv_s3p": "Chúng tôi không bán dữ liệu cá nhân, không xây dựng hồ sơ quảng cáo và không giữ âm thanh bạn đã tạo sau khi phiên của bạn kết thúc.", "priv_s4h": "Liên hệ", "priv_s4p": "Câu hỏi về quyền riêng tư: hãy liên hệ với chúng tôi qua <a href=\"/support.html\">trang Hỗ trợ</a>.", "priv_updated": "Cập nhật lần cuối: tháng 10 năm 2026", "sup_alert": "Cảm ơn bạn — hộp thư hỗ trợ sẽ mở cùng với đợt ra mắt công khai. Tạm thời, mục Câu hỏi thường gặp bao quát các trường hợp phổ biến.", "sup_contact_h": "Liên hệ", "sup_email": "Email của bạn", "sup_h1": "Hỗ trợ", "sup_msg": "Tin nhắn", "sup_msg_ph": "Mô tả chuyện đã xảy ra, giọng bạn đã dùng và điều bạn mong đợi...", "sup_notice": "Biểu mẫu liên hệ sẽ mở khi ra mắt chính thức. Trong thời gian chờ, mục Câu hỏi thường gặp trên trang chủ trả lời những câu hỏi phổ biến nhất.", "sup_o1": "Sự cố khi tạo âm thanh", "sup_o2": "Yêu cầu giọng nói", "sup_o3": "Báo lỗi", "sup_o4": "Kinh doanh / cấp phép", "sup_o5": "Khác", "sup_quick_h": "Cách khắc phục nhanh", "sup_quick_p": "• Không có tiếng khi Nghe thử: kiểm tra tab trình duyệt có bị tắt tiếng không và thử giọng khác.<br>• Giọng nghe không hợp với văn bản của bạn: trước tiên hãy khớp Ngôn ngữ giọng nói với ngôn ngữ của văn bản.<br>• Văn bản dài chạy chậm: chia thành các chương và tạo theo từng phần.<br>• Kết quả biến mất: kết quả chỉ tồn tại trong phiên trình duyệt hiện tại — hãy tải xuống ngay.", "sup_send": "Gửi tin nhắn", "sup_sub": "Hầu hết câu trả lời nằm trong mục Câu hỏi thường gặp ở trang chủ. Vẫn chưa giải quyết được? Hãy gửi cho chúng tôi chi tiết.", "sup_topic": "Chủ đề", "terms_h1": "Điều khoản dịch vụ", "terms_s1h": "Dịch vụ", "terms_s1p": "Text 2 Speech chuyển đổi văn bản bạn cung cấp thành giọng nói tổng hợp và cho phép bạn phát, tải xuống kết quả cùng với các tệp phụ đề. Dịch vụ được cung cấp nguyên trạng, không đảm bảo tính khả dụng liên tục.", "terms_s2h": "Trách nhiệm của bạn", "terms_s2p": "Chỉ chuyển đổi văn bản mà bạn có quyền sử dụng. Không dùng âm thanh đã tạo để mạo danh người thật, lừa dối người nghe hoặc vi phạm luật hiện hành. Bạn chịu trách nhiệm về cách bạn công bố và cấp phép những gì mình tạo ra.", "terms_s3h": "Sử dụng được chấp nhận", "terms_s3p": "Chúng tôi hoan nghênh việc sử dụng cho mục đích cá nhân, giáo dục và sáng tạo. Việc sử dụng âm thanh đã tạo cho mục đích thương mại là trách nhiệm của bạn trong việc làm rõ quyền đối với văn bản nguồn và mọi quy tắc cấp phép giọng nói áp dụng tại khu vực của bạn.", "terms_s4h": "Thay đổi", "terms_s4p": "Các tính năng và điều khoản này có thể thay đổi; những thay đổi quan trọng sẽ được ghi chú trên trang này kèm ngày mới.", "terms_updated": "Cập nhật lần cuối: tháng 10 năm 2026", "tut_g1h": "Bắt đầu: giọng nói đầu tiên bạn tạo", "tut_g1p": "Hãy bắt đầu bằng bộ chọn ngôn ngữ — nó quyết định bạn sẽ thấy những giọng nào. Chọn ngôn ngữ mà văn bản của bạn được viết bằng ngôn ngữ đó, rồi thử hai hoặc ba giọng bằng nút Nghe thử; các giọng khác nhau rất nhiều về độ ấm và nhịp điệu. Trước tiên hãy nhập một đoạn văn ngắn, tạo âm thanh và lắng nghe. Khi giọng đã ưng ý, bật Tốc độ hoặc Cao độ và điều chỉnh từng bước nhỏ: tốc độ +10% phù hợp với nội dung sôi động, cao độ thấp hơn một chút thường nghe có uy hơn. Với bất kỳ nội dung nào dài hơn một trang, hãy tạo theo từng phần và giữ nguyên giọng cùng cài đặt để các phần hòa quyện với nhau.", "tut_g2h": "Cách sử dụng tính năng ngắt nghỉ", "tut_g2p": "Các thẻ ngắt nghỉ chèn khoảng lặng chính xác vào âm thanh được tạo. Nhập <b>[break:200ms]</b> để nghỉ ngắn, <b>[break:1s]</b> hoặc <b>[break:2s]</b> để nghỉ dài hơn — những khoảnh khắc hé lộ kịch tính, các mục trong danh sách và chuyển cảnh đều hiệu quả hơn khi có khoảng thở xung quanh. Nhấn <b>Ctrl+B</b> sẽ đặt thẻ [break:500ms] tại vị trí con trỏ. Các thẻ không bao giờ xuất hiện trong âm thanh hay phụ đề; bạn chỉ nghe thấy khoảng lặng. Một quy tắc hữu ích: 300–600ms giữa các câu đổi chủ đề, 1–2 giây giữa các cảnh. Lưu ý rằng chế độ Nghe thử sẽ bỏ qua các thẻ, vì vậy hãy đánh giá thời lượng cuối cùng dựa trên tệp đã tạo.", "tut_g3h": "Khám phá bộ sưu tập giọng nói", "tut_g3p": "Danh mục của Text 2 Speech có hơn 300 giọng nói thần kinh trên 75 ngôn ngữ, và mỗi ngôn ngữ có nhiều phong cách — phẳng như phát thanh viên tin tức, ấm áp và trò chuyện, tươi sáng và trẻ trung. Tên giọng mang theo khu vực của chúng (Aria - US, Natasha - AU), và một vài giọng là đa ngôn ngữ, xử lý văn bản trộn nhiều ngôn ngữ một cách mượt mà. Bộ lọc giới tính và tìm kiếm theo tên giúp danh sách dễ quản lý. Khi phân vân, hãy tạo cùng một đoạn văn với ba giọng ứng viên và chọn bằng tai của bạn, không phải bằng tên: giọng phù hợp phụ thuộc vào nội dung, không phải nhãn dán.", "tut_h1": "Hướng dẫn", "tut_sub": "Các hướng dẫn ngắn gọn, thiết thực để bạn khai thác Text 2 Speech hiệu quả nhất."}};
